window.SIMS_DATA = {"sessions": [{"id": "s88", "titre": "Interventionnel MSK : transmettre l'information et les consignes", "horaire": "8h30–9h00", "duree": "38 min"}, {"id": "s89", "titre": "Échographie démo « Re-live 1 »", "horaire": "9h00–10h45", "duree": "62 min"}, {"id": "s90", "titre": "Mini-battle : Lisfranc & LCA mucoïde", "horaire": "10h45–11h10", "duree": "27 min"}, {"id": "s91", "titre": "Battles géniculés", "horaire": "11h10–11h50", "duree": "50 min"}, {"id": "s92", "titre": "Échographie : muscles", "horaire": "11h50–12h30", "duree": "30 min"}, {"id": "s93", "titre": "Interventionnel « Re-live 2 »", "horaire": "14h00–14h50", "duree": "72 min"}, {"id": "s94", "titre": "Mini-battle rayons X", "horaire": "14h50–16h10", "duree": "87 min"}, {"id": "s95", "titre": "Embolisations, RF, moelle osseuse : indications & résultats", "horaire": "17h00–17h45", "duree": "51 min"}], "fiches": [{"id": "consultation-avant-infiltration-rachidienne-race", "horaire": "8h30", "titre": "Intérêt de la consultation avant les infiltrations rachidiennes : étude prospective randomisée (étude RACE)", "orateur": "M. Pastor (CHU de Montpellier, hôpital Lapeyronie)", "t_start": 0, "t_end": 758, "resume": "L'étude RACE (RAdiology Consultation Effectiveness), prospective randomisée à 3 bras (consultation physique, téléconsultation, pas de consultation) avant infiltration rachidienne, ne montre à mi-parcours (170-180 patients inclus) aucune différence sur la douleur (J15, J30, J90) ni sur l'anxiété pré-geste. En revanche, 38 % des patients non vus auraient souhaité une consultation, et le geste est plus souvent modifié quand le radiologue voit le patient (≈ 55 % vs 39 %, NS).", "chiffres": [{"val": "170-180", "label": "patients inclus depuis février 2025 (NSN ≈ 240-250, ≈ 75 % de l'étude)"}, {"val": "p = 0,79", "label": "différence douleur J0-J30 : 2,08 (CS) vs 1,73 (télé-CS) vs 1,95 (sans CS)"}, {"val": "38,6 %", "label": "des patients « sans consultation » auraient préféré un autre groupe (p = 0,001)"}, {"val": "53,7 % / 55,6 % / 39,1 %", "label": "gestes modifiés : CS / télé-CS / sans CS (p = 0,22)"}], "points_cles": ["Hypothèses : la consultation crée une relation de confiance (relation soignant-soigné), module les attentes (composantes de l'effet placebo) et permet de s'assurer que le geste est adapté à la clinique et à l'imagerie (« le bon geste au bon patient »). Aucune donnée dans la littérature.", "Design : étude prospective, monocentrique, ouverte, randomisée en 3 bras (consultation physique n = 54, téléconsultation n = 45, sans consultation n = 46 au moment de l'analyse).", "Inclusion : adultes adressés pour infiltration rachidienne, tous étages, tous types (épidurale, interapophysaire postérieure, foraminale, intra/péri-discale), douleur EN ≥ 5/10 ; exclusion : antécédent opératoire rachidien (vus systématiquement en consultation).", "Critère principal : douleur à J30 (EN 0-10). Secondaires : douleur J15 et J90, anxiété pré-procédurale J0 (STAI-Y), satisfaction à J30 (geste et groupe alloué), consommation d'antalgiques/AINS, nombre de gestes modifiés par le radiologue.", "Résultats intermédiaires : aucune différence significative sur la réduction de la douleur à J15, J30, J90 ni sur l'anxiété pré-geste ; satisfaction de la prise en charge très élevée dans les 3 bras (100 % / 100 % / 95,5 %).", "Biais à corriger : plus d'antécédents d'infiltration (patients potentiellement moins répondeurs) et plus de femmes dans le bras consultation ; refus de participation des patients ne souhaitant pas être vus.", "Pas de différence entre téléconsultation et consultation physique ; consultations réalisées uniquement par les seniors ; indications posées par tous types de correspondants (rhumatologues, généralistes, chirurgiens) en « vraie vie ».", "Pistes : réserver la consultation systématique aux gestes à risque et laisser le choix au patient pour les autres ; la consultation ancre le rôle du radiologue interventionnel comme clinicien et non comme « prestataire de service ».", "Discussion : intérêt aussi d'une consultation après le geste en cas d'échec (déconditionnement musculaire, récidive précoce → discuter une rhizolyse) ; sur le plan médico-légal, l'information orale prime sur l'écrite et doit être délivrée suffisamment tôt pour permettre un délai de réflexion."], "technique": [], "alertes": [{"type": "warning", "texte": "Médico-légal : recueillir la signature du consentement le jour même du geste est assimilé à une extorsion du consentement — à proscrire. L'information doit être délivrée en amont (délai de réflexion) ; un document signé reste exigé par les assureurs et en expertise."}, {"type": "important", "texte": "Résultats intermédiaires d'une étude en cours (≈ 75 % des inclusions) : ne pas en tirer de conclusion définitive avant la publication et les analyses en sous-groupes."}], "cochin": "Pour les infiltrations rachidiennes simples, une consultation (ou téléconsultation) proposée à la demande du patient semble raisonnable, en la gardant systématique pour les gestes à risque ; prévoir une consultation post-geste en cas d'échec.", "tags": ["Rachis", "Infiltration", "Organisation", "Études"], "images": [{"src": "img/consultation-avant-infiltration-rachidienne-race-1.jpg", "legende": "Design de l'étude RACE : 3 bras randomisés, critères d'inclusion et critères de jugement", "t": 260}, {"src": "img/consultation-avant-infiltration-rachidienne-race-2.jpg", "legende": "Critère principal (douleur J30) : aucune différence entre consultation, téléconsultation et absence de consultation (p = 0,793)", "t": 320}, {"src": "img/consultation-avant-infiltration-rachidienne-race-3.jpg", "legende": "Satisfaction (38 % des patients non vus auraient voulu une CS) et changements de geste selon le bras", "t": 380}, {"src": "img/consultation-avant-infiltration-rachidienne-race-4.jpg", "legende": "Take-home messages : consultation pour les gestes à risque, choix laissé au patient, rôle clinique du radiologue interventionnel", "t": 480}], "session": "s88"}, {"id": "fiches-information-patients-sims", "horaire": "8h40", "titre": "Fiches d'information aux patients des gestes interventionnels — Groupe de travail SIMS", "orateur": "C. Cyteval (CHU de Montpellier), au nom du Dr Chamard-Champliaud", "t_start": 758, "t_end": 1058, "resume": "Le groupe de travail SIMS propose des fiches d'information et de consentement standardisées pour les gestes interventionnels ostéo-articulaires, relues par plusieurs CHU et testées auprès de patients pour leur compréhensibilité. Elles sont disponibles en PDF et en Word sur le site de la SIMS pour être adaptées à chaque pratique, et doivent être remises au moins 48 h avant le geste.", "chiffres": [{"val": "10 (9 finalisées)", "label": "fiches d'information/consentement (fiche nerf d'Arnold en cours de modification)"}, {"val": "≥ 48 h", "label": "délai minimal de remise de la fiche avant le geste"}], "points_cles": ["Contexte : le radiologue doit devenir un clinicien-thérapeute à part entière, avant comme après le geste, à l'image des chirurgiens, et disposer de références communes.", "Objectifs : délivrer une information standardisée et compréhensible (fiches relues par des patients pour éviter le jargon), harmoniser les pratiques.", "Groupe de travail : Dr Chamard-Champliaud, Dr S. Grange (CHU Saint-Étienne), Pr C. Cyteval (Montpellier), Pr V. Bousson (Lariboisière) ; base = fiches du CHU de Montpellier mises à jour, relectures successives, relecture par le secrétaire général puis synthèse finale.", "Modèle commun pour toutes les fiches : principe théorique du geste, produits utilisés, complications potentielles, questionnaire patient (traitements, coagulation, allergies…), signature du consentement.", "Format PDF et Word : chacun peut modifier facilement selon sa pratique ou sa population et créer de nouvelles fiches pour des gestes plus « confidentiels ».", "Si consultation : remettre la fiche lors de la consultation pour relecture « à tête reposée ». Sans consultation : l'adresser lors de la prise de RDV avec les ordonnances de produits et l'éventuel bilan biologique ; le patient la rapporte signée le jour du geste.", "Fiches en ligne sur le site de la SIMS, accessibles aux radiologues membres."], "technique": [], "alertes": [{"type": "warning", "texte": "Ne pas remettre la fiche de consentement le jour du geste : respecter un délai de réflexion (au moins 48 h)."}], "cochin": "Les fiches SIMS (Word) peuvent servir de base pour harmoniser les documents d'information du service, envoyés avec la convocation, les ordonnances et le bilan biologique.", "tags": ["Organisation", "Infiltration"], "images": [{"src": "img/fiches-information-patients-sims-1.jpg", "legende": "Groupe de travail : fiches de Montpellier mises à jour, relues par les CHU de Saint-Étienne et Lariboisière", "t": 920}, {"src": "img/fiches-information-patients-sims-2.jpg", "legende": "Modèle commun des fiches : principe du geste, produits, complications, questionnaire patient (coagulation, allergies)", "t": 980}, {"src": "img/fiches-information-patients-sims-3.jpg", "legende": "En pratique : remise de la fiche en consultation ou avec les ordonnances et le bilan lors de la prise de RDV", "t": 1000}], "session": "s88"}, {"id": "gestion-risque-hemorragique-thrombotique-sims", "horaire": "8h45", "titre": "Gestion des risques hémorragiques et thrombotiques des procédures interventionnelles musculosquelettiques — Groupe de travail SIMS", "orateur": "Y. Thouvenin et coll. (R. Guillin, J.-F. Budzik, P. Viala, E. Decoux, L. Deffontis [anesthésiste], J.-C. Macia [cardiologue])", "t_start": 1058, "t_end": 1420, "resume": "Groupe de travail SIMS (radiologues public/privé, anesthésiste, cardiologue) préparant une documentation pratique fondée sur une synthèse des recommandations internationales récentes, couvrant l'ensemble de la prise en charge du risque hémorragique et thrombotique en RI ostéo-articulaire. Mise en ligne prévue sur le site de la SIMS (travail en voie de finalisation, contenu détaillé non présenté).", "chiffres": [], "points_cles": ["Objectif : regrouper des éléments jusque-là disparates (antiagrégants, AVK, AOD, indications du bilan d'hémostase…) dans une documentation unique.", "Préciser la place du questionnaire HEMSTOP (déjà utilisé par les anesthésistes) et du bilan d'hémostase systématique ou non.", "Réajuster les niveaux de risque hémorragique des principales procédures, dans un sens plutôt moins strict que certaines références anciennes, en laissant la place à l'expertise de l'opérateur (corpulence, guidage, calibre de l'aiguille, expérience).", "Fournir un mode d'emploi des modalités d'arrêt et de reprise des antiagrégants et anticoagulants par grandes familles.", "Livrables : tableau récapitulatif (une colonne par niveau de risque, conduite à tenir de la prise de sang à l'arrêt/reprise du traitement), texte explicatif, questionnaire HEMSTOP, modèle de courrier/courriel au prescripteur.", "Communication avec le prescripteur : courriel exposant le niveau de risque du geste et la modulation habituelle, avec retour de validation du prescripteur (simple pour les cardiologues, intérêt médico-légal)."], "technique": [], "alertes": [{"type": "important", "texte": "Document non encore publié : les niveaux de risque et les délais d'arrêt/reprise n'ont pas été détaillés lors de la présentation."}, {"type": "tip", "texte": "Obtenir une validation écrite (courriel) du prescripteur avant toute modulation d'un traitement antithrombotique plutôt qu'une simple consigne orale au patient."}], "cochin": "Dans l'attente du document SIMS, formaliser un courriel type au prescripteur (niveau de risque du geste + modulation proposée) et envisager le questionnaire HEMSTOP en pré-geste.", "tags": ["Complications", "Organisation"], "images": [{"src": "img/gestion-risque-hemorragique-thrombotique-sims-1.jpg", "legende": "Objectifs du groupe : questionnaire HEMSTOP et bilan d'hémostase, niveaux de risque, arrêt/reprise des antithrombotiques, communication avec le prescripteur", "t": 1120}, {"src": "img/gestion-risque-hemorragique-thrombotique-sims-2.jpg", "legende": "Mise à disposition : tableau récapitulatif, texte explicatif, questionnaire HEMSTOP, courrier/courriel type au prescripteur", "t": 1160}], "session": "s88"}, {"id": "retour-domicile-gestes-lourds-cochin", "horaire": "8h50", "titre": "Gestion du retour à domicile dans le cadre des gestes interventionnels lourds (réhabilitation accélérée, protocole Cochin)", "orateur": "M.-P. Talabard (Hôpital Cochin, AP-HP — avec M. Barat, A. Dohan, A. Feydy)", "t_start": 1420, "t_end": 2330, "resume": "Après une introduction sur la réhabilitation accélérée (RAC, recommandations SFAR) et le groupe RA-RI SFR-SFAR (publication prévue en 2026), l'oratrice présente une étude rétrospective de Cochin comparant les patients d'HDJ de RI ostéo-articulaire avec ou sans réseau d'infirmières à domicile (Midiperf). Aucune différence de satisfaction (e-SATIS), de récupération (FQoR-15) ni d'anxiété, pour un surcoût d'environ 2 000 € par intervention : le service prévoit d'arrêter Midiperf pour ces indications.", "chiffres": [{"val": "89", "label": "patients analysés (29 Midiperf vs 60 non Midiperf) sur 423 éligibles"}, {"val": "0", "label": "différence significative sur la satisfaction, la récupération et l'anxiété"}, {"val": "≈ 2 000 €", "label": "surcoût par intervention (≈ 1 000 € de forfait + ≈ 1 000 € IDE et matériel)"}, {"val": "2/89", "label": "patients non sortis à J0 (surveillance simple)"}], "points_cles": ["RAC : approche multidisciplinaire standardisée fondée sur les preuves, visant à réduire la durée de séjour sans augmenter les réadmissions ni les complications et à améliorer l'expérience patient (base du développement de l'ambulatoire chirurgical ; RFE SFAR avec niveaux de preuve pré/per/post-opératoires).", "RA-RI (réhabilitation accélérée en radiologie interventionnelle) : groupe conjoint SFR-SFAR (Montpellier) définissant les protocoles pré-op (nutrition, kiné, douleur, anxiété/sommeil, parcours, sélection des patients), per-op (anesthésie, anxiolyse BZD vs hypnose/« digicaments », jeûne) et post-op (douleur, récupération précoce, soins à domicile) ; publication prévue courant 2026.", "Protocole Cochin sans Midiperf : anesthésie locale, analgésie IV, prémédication sédative à la demande ou hypnothérapie en per-op ; antalgie per os et fiche de suivi avec numéros d'urgence en post-op.", "Protocole Cochin avec Midiperf : en pré-op, analgésie IV ou per os, IDE à domicile 2×/j, débutée au maximum 12 jours avant, ± corticothérapie IV ; per-op identique ; post-op, analgésie IV ou per os au maximum jusqu'à J2 avec IDE 2×/j. Choix selon l'opérateur ou le patient (livraison de matériel au domicile, entrée dans un circuit de soins).", "Étude rétrospective : patients d'HDJ de RI MSK du 01/03/2022 au 30/10/2025 ; questionnaires e-SATIS (HAS, chirurgie ambulatoire) et FQoR-15 (qualité de récupération) envoyés par mail/appel ARC ; 423 éligibles, 100 contactés, 89 analysés.", "Gestes : majoritairement biopsies osseuses ou des parties molles profondes (66,7 % vs 48,3 %), cimentoplasties, radiofréquence (ostéomes ostéoïdes, plus fréquents dans le groupe Midiperf), cryothérapie, 1 vissage. Les biopsies des parties molles superficielles sont faites en externe.", "Groupe Midiperf plus jeune (42,3 vs 53,7 ans, p = 0,02) et plus souvent sous AG (58,6 % vs 30 %, p = 0,03).", "Sorties à J0 : 87/89 ; 2 hospitalisations de surveillance : embolie pulmonaire de ciment asymptomatique post-cimentoplastie, désaturation au réveil d'AG. Aucune complication grave.", "Aucune différence sur la qualité du contact, la satisfaction après retour à domicile, la satisfaction globale, ni sur les items FQoR-15 (soutien des soignants, anxiété) : un dispositif « contraphobique pour le médecin mais pas pour le patient ».", "Discussion : pour les gestes hyperalgiques (vertébroplasties en cascade fracturaire, décompressions discales, implants interépineux), le suivi IDE à domicile peut rester utile (rebond douloureux, œdème post-opératoire, moins de rappels/reconsultations) ; nombre d'appels des patients non évalué ; intérêt à phénotyper les gestes et à mener une étude multicentrique."], "technique": ["Sélectionner les patients éligibles à l'ambulatoire (HDJ) : biopsies osseuses/parties molles profondes, cimentoplasties, ablations simples (RF d'ostéome ostéoïde, petites cryothérapies) chez des patients peu comorbides.", "Per-op : anesthésie locale, analgésie IV, prémédication sédative à la demande ou hypnothérapie (AG si nécessaire).", "Post-op : antalgie per os, sortie à J0, fiche de suivi avec numéros d'urgence.", "Option réseau IDE à domicile (type Midiperf) : à réserver à des indications sélectionnées (gestes hyperalgiques) plutôt qu'en systématique."], "alertes": [{"type": "warning", "texte": "Après cimentoplastie, une embolie pulmonaire de ciment (même asymptomatique) a imposé une hospitalisation de surveillance : prévoir cette éventualité dans le parcours ambulatoire."}, {"type": "important", "texte": "Étude rétrospective, résultats intermédiaires, petits effectifs (29 vs 60) et groupes non comparables (âge, AG) : manque de puissance, notamment pour les cimentoplasties (8 + 3 patients)."}, {"type": "tip", "texte": "Une fiche de sortie avec numéros d'urgence et une antalgie per os suffisent pour la majorité des gestes d'HDJ ostéo-articulaires ; le réseau IDE coûte ≈ 2 000 €/intervention sans bénéfice démontré."}], "cochin": "Protocole du service : HDJ avec fiche de suivi et numéros d'urgence pour la plupart des gestes ; l'équipe prévoit d'arrêter le recours systématique à Midiperf, à réserver éventuellement aux gestes hyperalgiques (vertébroplasties en cascade fracturaire).", "tags": ["Organisation", "Cimentoplastie", "Radiofréquence", "Études"], "images": [{"src": "img/retour-domicile-gestes-lourds-cochin-1.jpg", "legende": "Protocole Cochin : parcours HDJ sans et avec Midiperf (pré-op, per-op, post-op)", "t": 1680}, {"src": "img/retour-domicile-gestes-lourds-cochin-2.jpg", "legende": "Flow chart de l'étude : 423 patients éligibles, 100 contactés, 89 analysés (29 Midiperf / 60 non Midiperf)", "t": 1800}, {"src": "img/retour-domicile-gestes-lourds-cochin-3.jpg", "legende": "Caractéristiques des groupes : âge, type d'intervention, sortie à J0, anesthésie", "t": 1860}, {"src": "img/retour-domicile-gestes-lourds-cochin-4.jpg", "legende": "Conclusion RA-RI en ostéo-articulaire : encadrer l'ambulatoire, sélectionner les patients, pas d'IDE à domicile systématique", "t": 2000}], "session": "s88"}, {"id": "gleno-humerale-posterieure-echo", "horaire": "9h00", "titre": "Comment j'infiltre une articulation gléno-humérale par voie postérieure ?", "orateur": "H. Guerini", "t_start": 0, "t_end": 440, "resume": "Pour l'injection gléno-humérale échoguidée, H. Guerini privilégie la voie postérolatérale en décubitus latéral, plus simple que les voies antérieures (intervalle des rotateurs serré, aiguille mal vue, coracoïde) ou postéro-médiale (trajet long). Deux cibles successives : contact cartilagineux juste sous la capsule, puis le triangle hyperéchogène capsulo-synovial plus profond, avec une astuce de rotation du biseau.", "chiffres": [{"val": "×2", "label": "plus rapide sous écho que sous scopie (de l'entrée à la sortie de salle)"}, {"val": "≈100 %", "label": "taux de réussite, équivalent écho vs scopie"}, {"val": "68 % vs 52 %", "label": "« taches » extra-articulaires : voie antérieure sous scopie vs voie postérieure sous écho"}, {"val": "45°", "label": "angle d'entrée conseillé pour atteindre la cible 2"}], "points_cles": ["Indications identiques à la voie scopique (arthropathie, lésions de coiffe face profonde/transfixiantes, long biceps, capsulite, arthroscanner/arthro-IRM) ; écho à privilégier en cas d'allergie au produit de contraste iodé.", "Avantages de l'écho : non irradiant, pas de PDC iodé, 2 fois plus rapide, injections moins douloureuses, réussite équivalente proche de 100 %.", "Voies antérieures (dont intervalle des rotateurs) jugées plus difficiles : aiguille peu visible, profondeur, coracoïde, espace ligamentaire serré.", "La voie postérieure génère aussi des fuites (52 %) mais une tache postérieure ne gêne pas l'interprétation d'un arthroscanner/arthro-IRM, contrairement à une tache antérieure dans le sous-scapulaire.", "Repère clé : fine ligne hyperéchogène entre muscle (petit rond le plus souvent, ou infra-épineux) et cartilage huméral hypoéchogène = capsule postérieure, très fine (plus facile à franchir qu'en avant).", "Cible 1 : entre cette ligne capsulaire et le cartilage, au plus près du point d'entrée.", "Cible 2 (si échec) : triangle hyperéchogène plus profond (capsule et synoviale épaissies, ce n'est pas le labrum), nécessite une entrée à ~45°, pas trop parallèle au cartilage.", "Le passage intra-articulaire se voit mal ; les microbulles du Diprostène aident à le confirmer."], "technique": ["Patient en décubitus latéral sur le côté opposé, épaule à infiltrer en haut ; main posée sur la table ou sur l'épaule controlatérale.", "Sonde en coupe axiale juste sous le bord osseux de l'acromion : interligne gléno-huméral, tête et cartilage, muscle petit rond/infra-épineux.", "Palper du doigt la peau en regardant l'écran pour choisir le point d'entrée et un angle d'environ 45° ; repérer la profondeur sur l'échelle en cm.", "Désinfection, puis progression dans le plan, biseau orienté vers l'arrière du patient pour « crocheter » la capsule au contact du cartilage.", "Pousser : la résistance cède brusquement à l'entrée dans l'articulation (sensation de passage, piston qui descend).", "Une fois dans l'articulation, retourner le biseau dans l'autre sens pour éviter que le produit ne file entre muscle et capsule.", "Si la cible 1 échoue (tache blanche dans le muscle, résistance), se repositionner vers le triangle hyperéchogène profond (cible 2) avec la même technique de biseau ; le passage y est en général immédiat.", "Contrôle : diffusion intra-articulaire et microbulles visibles (Diprostène)."], "alertes": [{"type": "tip", "texte": "Biseau vers l'arrière pour crocheter la capsule, puis rotation du biseau une fois dedans : limite l'injection à cheval entre muscle et capsule."}, {"type": "warning", "texte": "Une résistance ou une tache hyperéchogène dans le muscle signe une injection extra-articulaire : ne pas forcer, se repositionner (cible 2)."}, {"type": "important", "texte": "Entrée trop parallèle au cartilage : impossible d'atteindre la cible profonde, garder ~45°."}], "cochin": "Voie postérolatérale échoguidée utilisable pour les arthro-IRM/arthroscanners et infiltrations gléno-humérales, notamment chez les allergiques au PDC iodé, avec un gain de temps de salle par rapport à la scopie.", "tags": ["Échographie", "Épaule", "Infiltration"], "images": [{"src": "img/gleno-humerale-posterieure-echo-1.jpg", "legende": "Installation : décubitus latéral, sonde axiale sous l'acromion", "t": 200}, {"src": "img/gleno-humerale-posterieure-echo-2.jpg", "legende": "Cible 1 : aiguille entre la fine capsule postérieure hyperéchogène et le cartilage huméral (schéma et coupe écho)", "t": 220}, {"src": "img/gleno-humerale-posterieure-echo-3.jpg", "legende": "Cible 2 : triangle hyperéchogène capsulo-synovial plus profond, abord à 45°", "t": 280}, {"src": "img/gleno-humerale-posterieure-echo-4.jpg", "legende": "« Taches » de produit de contraste : 68 % par voie antérieure sous scopie contre 52 % par voie postérieure sous écho, sans conséquence en arrière", "t": 160}], "session": "s89"}, {"id": "sous-talienne-posterieure-sinus-tarse", "horaire": "9h08", "titre": "Comment j'infiltre l'articulation sous-talienne postérieure par voie antérieure (antérolatérale, sinus du tarse) ?", "orateur": "O. Leluc (IMPS, Clinique Juge)", "t_start": 440, "t_end": 860, "resume": "O. Leluc infiltre la sous-talienne postérieure sous écho par voie antérolatérale, en ciblant non pas l'interligne mais le petit récessus articulaire antérolatéral au contact de la face latérale du calcanéum, à l'entrée du sinus du tarse. Technique simple, rapide à apprendre, à condition de rester très superficiel et latéral et de repérer la branche intermédiaire du nerf fibulaire superficiel.", "chiffres": [{"val": "15°", "label": "inclinaison de la sonde depuis l'axe du ligament calcanéo-fibulaire"}, {"val": "21 G", "label": "calibre d'aiguille cité (repérer le nerf pour éviter un névrome)"}, {"val": "3", "label": "articles (même auteur, Smith 2009 et 2015) décrivant les voies échoguidées"}], "points_cles": ["Articulation en selle (inversion/éversion), adaptative à la marche : arthropathie très mal tolérée cliniquement ; arthrose quasi toujours post-traumatique ; variantes anatomiques exceptionnelles (hors coalitions).", "Anatomie : interligne latéral prolongé par un récessus articulaire antérolatéral (face superficielle du sinus du tarse) et une partie postérieure transverse.", "Voies selon Smith (J Ultrasound Med 2009, étude cadavérique) : postérolatérale peu recommandée (articulation profonde), médiale à proscrire (tunnel tarsien), latérale préférée ; confirmée comme la plus aisée en 2015 (abord par le sinus du tarse).", "En latéral, fibula, tendons fibulaires et nerf sural occupent la place : comme pour les zygapophysaires, on vise le récessus et non l'interligne.", "Chez beaucoup de patients le récessus est petit et moule la face latérale du calcanéum : ponctionner le plus superficiellement possible.", "Injection normalement indolore avec sensation de dépression (comme au genou) ; une résistance signifie qu'on est dans la graisse du sinus du tarse.", "Le produit peut filer directement dans l'interligne sans distendre le récessus ; un ostéophyte peut masquer l'interligne sans gêner l'abord par le récessus."], "technique": ["Repérage écho : sonde dans l'axe du ligament calcanéo-fibulaire, puis inclinaison d'environ 15°, point fixe sur le calcanéum, pour se placer sur le sinus du tarse et le récessus articulaire.", "Repérer et marquer la branche intermédiaire du nerf fibulaire superficiel (parfois proche si l'abord est un peu médian).", "Aiguille (21 G citée) en approche tangentielle au récessus pour ne pas l'écraser ; s'il y a du liquide, la ponction est facile, à distance des tendons fibulaires.", "Articulation sèche : avancer jusqu'au contact osseux sur la face latérale du calcanéum (portion la plus superficielle du récessus).", "Injecter : doit être indolore avec dépression ; si ça résiste, ne pas insister (graisse du sinus du tarse), se repositionner.", "En cas de doute, verticaliser la sonde pour voir le récessus se remplir.", "Débutant ou articulation sèche : distendre d'abord la cavité avec un peu de xylocaïne ou de sérum physiologique."], "alertes": [{"type": "warning", "texte": "Branche intermédiaire du nerf fibulaire superficiel : à repérer systématiquement (variantes possibles) pour éviter un névrome iatrogène."}, {"type": "warning", "texte": "Voie médiale à proscrire (tunnel tarsien) ; ne pas aller chercher l'intérieur du sinus du tarse, rester superficiel et latéral."}, {"type": "tip", "texte": "Résistance à l'injection = graisse du sinus du tarse, pas le récessus : ne pas forcer."}], "cochin": "Alternative échoguidée simple à l'injection sous-talienne sous scopie/TDM ; repérage du nerf fibulaire superficiel et pré-distension au sérum en cas d'articulation sèche.", "tags": ["Échographie", "Cheville-pied", "Infiltration", "Nerfs"], "images": [{"src": "img/sous-talienne-posterieure-sinus-tarse-1.jpg", "legende": "Voie latérale : récessus antérolatéral, rapports avec le nerf fibulaire superficiel et le nerf sural", "t": 620}, {"src": "img/sous-talienne-posterieure-sinus-tarse-2.jpg", "legende": "Repérage échographique : sonde dans l'axe du ligament calcanéo-fibulaire inclinée de 15°", "t": 680}, {"src": "img/sous-talienne-posterieure-sinus-tarse-3.jpg", "legende": "Schéma et coupe écho : sinus du tarse, calcanéum, talus et interligne sous-talien", "t": 720}, {"src": "img/sous-talienne-posterieure-sinus-tarse-4.jpg", "legende": "Démonstration : aiguille tangente au récessus au contact de la face latérale du calcanéum", "t": 780}], "session": "s89"}, {"id": "hydrodissection-tunnel-radial-dextrose", "horaire": "9h16", "titre": "Comment je réalise une hydrodissection du tunnel radial au dextrose", "orateur": "Guillaume Favarel (Échographie 38, Meylan) — orthographié « Faravel » au programme", "t_start": 860, "t_end": 1290, "resume": "Vidéo pré-enregistrée : hydrodissection échoguidée non sélective de la branche profonde du nerf radial au dextrose 5 % (~15 mL) dans le syndrome du tunnel radial, diagnostic purement clinique. Le liquide, poussé dès l'entrée de l'aiguille, ouvre les plans jusqu'à obtenir un nerf qui « flotte » ; alternative non cortisonée, résultats en 4 à 6 semaines.", "chiffres": [{"val": "≈15 mL", "label": "dextrose 5 % injecté (inondation non sélective)"}, {"val": "≈5 cm", "label": "sous la tête radiale : point douloureux clinique"}, {"val": "4–6 sem.", "label": "délai d'apparition des résultats ; 2e geste possible à 6 semaines"}, {"val": "18 MHz", "label": "sonde linéaire"}], "points_cles": ["Syndrome du tunnel radial : douleur neuropathique antérolatérale du coude, uniquement sensitive (≠ syndrome du nerf interosseux postérieur, déficit moteur).", "Tunnel radial : de l'épicondyle latéral au bord distal du muscle supinateur ; bifurcation en branche superficielle sensitive et branche profonde mixte (cible).", "Clinique : point douloureux distal (≈5 cm sous la tête radiale), tendon indolore ; douleur majorée par la supination contrariée ; tests de neurotension souvent positifs.", "Imagerie souvent normale, EMG normal (élimine les différentiels) : diagnostic clinique.", "Diagnostics différentiels : syndrome du NIO, névralgie cervico-brachiale, syndrome de Wartenberg, épicondylite latérale.", "Principe : libérer les adhérences et réduire la compression mécanique en recréant un espace de glissement ; dextrose 5 % à excellente innocuité, sans effet indésirable significatif rapporté.", "Geste volontairement non sélectif du fait des grandes variations des rameaux nerveux."], "technique": ["Matériel : seringue 5 mL + aiguille 25 G pour anesthésie sous-cutanée à la xylocaïne 1 % ; seringue 20 mL Luer-lock (gestion de la pression) + aiguille 21 G pour le dextrose 5 %.", "Sonde linéaire 18 MHz, focale centrée sur la cible ; repérer le nerf radial, sa bifurcation, l'arcade de Frohse et les limites du tunnel radial.", "Point d'entrée marqué au stylo dermographique, désinfection en 3 temps à la Bétadine.", "Hydrodissection dès l'entrée de l'aiguille : c'est la pression du liquide, pas le biseau, qui écarte les tissus ; avancer en poussant.", "À l'arcade de Frohse : injecter autour du nerf, réorienter l'aiguille vers le haut, le bas, en proximal et en distal pour inonder la zone.", "Hydrodissection de la partie superficielle, puis de la zone distale entre les deux faisceaux du supinateur.", "Objectif : nerf qui flotte dans un halo anéchogène (liquide au-dessus et en dessous), vérifié en balayant le long du nerf (technique de l'ascenseur) ; compléter plus en proximal/distal si besoin.", "Volume total ≈15 mL ; pansement sec.", "Suites : pas de massage, pas de compression, pas de bracelet anti-épicondylite ; apprendre au patient les exercices de neuroglissement du nerf radial (mouvements coordonnés du membre et inclinaison cervicale)."], "alertes": [{"type": "important", "texte": "Après le geste, proscrire toute recompression de la zone : massages, compressions, bracelets d'épicondylite."}, {"type": "tip", "texte": "Seringue Luer-lock de 20 mL pour contrôler la pression ; laisser le liquide ouvrir les plans devant le biseau."}, {"type": "tip", "texte": "Résultats tardifs (4–6 semaines) : prévenir le patient ; 2e geste possible à 6 semaines."}], "cochin": "Option non cortisonée pour les douleurs neuropathiques du coude latéral à EMG normal ; matériel simple (dextrose 5 %, 21 G, Luer-lock 20 mL) disponible en salle d'écho.", "tags": ["Échographie", "Coude", "Nerfs", "Infiltration"], "images": [{"src": "img/hydrodissection-tunnel-radial-dextrose-1.jpg", "legende": "Anatomie du tunnel radial : de l'épicondyle latéral au bord distal du supinateur, arcade de Frohse", "t": 940}, {"src": "img/hydrodissection-tunnel-radial-dextrose-2.jpg", "legende": "Matériel : seringue 5 mL/25 G (xylocaïne 1 %), seringue Luer-lock 20 mL/21 G (dextrose 5 %)", "t": 1020}, {"src": "img/hydrodissection-tunnel-radial-dextrose-3.jpg", "legende": "Hydrodissection échoguidée : aiguille dans le plan, liquide anéchogène écartant les tissus autour du nerf", "t": 1100}, {"src": "img/hydrodissection-tunnel-radial-dextrose-4.jpg", "legende": "Consignes post-geste : ni massage, ni compression, ni brassard", "t": 1220}], "session": "s89"}, {"id": "nerf-cluneal-inferieur-echo", "horaire": "9h24", "titre": "Comment j'infiltre le nerf clunéal inférieur ?", "orateur": "Loïc Colleter (IMPS, Clinique Juge)", "t_start": 1290, "t_end": 1580, "resume": "La névralgie clunéale inférieure, méconnue et souvent confondue avec la pudendalgie, se diagnostique par les 5 critères de Nantes dont un test anesthésique guidé par l'imagerie. L'orateur propose un abord échoguidé (non décrit dans la littérature, qui ne rapporte que le scanner) en décubitus ventral, visant un triangle graisseux sous la tubérosité ischiatique, par voie médiale vers latérale.", "chiffres": [{"val": "5", "label": "critères de Nantes (4 cliniques + test anesthésique guidé par l'imagerie)"}, {"val": "20 %", "label": "territoire sensitif commun possible avec le nerf pudendal"}, {"val": "45°", "label": "obliquité de l'aiguille vers le triangle graisseux"}], "points_cles": ["Branches du nerf clunéal inférieur issues du nerf cutané postérieur de cuisse (S1-S3), qui passe sous le piriforme, entre nerf sciatique (en dehors) et nerf pudendal (en dedans).", "Trajet : bord latéral de la tubérosité ischiatique jusqu'à son bord inférieur, superficiel à l'insertion des ischio-jambiers et profond au grand glutéal, puis contourne le bord inférieur du grand glutéal et perfore son fascia.", "Hypothèse de conflit : expansion fibreuse entre bord latéro-distal de l'ischion et fascia profond du grand glutéal.", "Critères de Nantes : douleur neuropathique dans le territoire (sous l'ischion/la fesse, brûlure, sensation de carton ou de caillou, irradiant au scrotum/grandes lèvres, épargnant anus, pénis/clitoris), douleur en position assise (siège dur), pas de réveil nocturne, pas de perte de sensibilité périnéale, test anesthésique local guidé par l'imagerie positif.", "Y penser devant une douleur plus latérale et postérieure incluant l'ischion, ou après un bloc pudendal négatif.", "IRM fortement conseillée (hors critères) : cause compressive tumorale, tendinopathie fissuraire des ischio-jambiers qui contre-indiquerait les corticoïdes.", "Patient corpulent : guidage scanner, seule technique décrite dans la littérature, mêmes repères."], "technique": ["Décubitus ventral, comme pour l'exploration des ischio-jambiers.", "Aiguille verte (21 G) ou noire (22 G) selon la corpulence.", "Produit selon la demande : xylocaïne (test anesthésique) ou corticoïdes.", "Sonde axiale sous la fesse ; balayage de haut en bas jusqu'à la face la plus inférieure de l'ischion ; repérer ischio-jambiers, tubérosité ischiatique et grand glutéal.", "Cible : triangle graisseux à l'interface entre ces trois structures.", "Entrée médiale vers latérale (pour éviter le nerf sciatique), à travers les muscles, à ~45° en oblique jusqu'au triangle graisseux, puis injection."], "alertes": [{"type": "warning", "texte": "Voie médiale → latérale pour s'éloigner du nerf sciatique, latéral à la tubérosité ischiatique."}, {"type": "important", "texte": "Avant corticoïdes : éliminer en IRM une lésion fissuraire de l'insertion proximale des ischio-jambiers et une cause tumorale compressive."}, {"type": "tip", "texte": "Bloc pudendal négatif et douleur latérale ischiatique : penser au nerf clunéal inférieur."}], "cochin": "Test anesthésique et infiltration échoguidés réalisables en salle d'écho, avec bascule vers le scanner chez les patients corpulents ; à proposer aux algologues et rééducateurs du périnée.", "tags": ["Échographie", "Hanche-bassin", "Nerfs", "Infiltration"], "images": [{"src": "img/nerf-cluneal-inferieur-echo-1.jpg", "legende": "Anatomie : nerf cutané postérieur de cuisse (S1-S3) et branches du nerf clunéal inférieur, rapports avec sciatique et pudendal", "t": 1360}, {"src": "img/nerf-cluneal-inferieur-echo-2.jpg", "legende": "Territoires sensitifs : clunéal inférieur vs pudendal (zone commune jusqu'à 20 %)", "t": 1400}, {"src": "img/nerf-cluneal-inferieur-echo-3.jpg", "legende": "Technique : décubitus ventral, sonde axiale, voie médiale vers latérale", "t": 1480}, {"src": "img/nerf-cluneal-inferieur-echo-4.jpg", "legende": "Écho : trajet de l'aiguille vers le triangle graisseux sous l'ischion", "t": 1520}], "session": "s89"}, {"id": "acnes-paroi-abdominale", "horaire": "9h32", "titre": "Comment j'infiltre un ACNES (Anterior Cutaneous Nerve Entrapment Syndrome) ?", "orateur": "François Lafourcade (CHU de Toulouse)", "t_start": 1580, "t_end": 2120, "resume": "Le syndrome de compression du nerf cutané antérieur de l'abdomen (branche terminale d'un nerf intercostal) est une cause méconnue de douleur pariétale focale. L'échographie centrée sur le point douloureux montre un petit nerf épaissi (« pépite sur la tablette de chocolat ») à sa sortie du muscle droit, que l'on infiltre après hydrodissection.", "chiffres": [{"val": "1/1800", "label": "incidence (probablement sous-estimée), 3 F / 1 H, tout âge"}, {"val": "57 %", "label": "formes spontanées (chirurgie 28 %, sport/trauma 5 %, grossesse 3 %, post-viral 3 %)"}, {"val": "T10–T12", "label": "niveaux les plus touchés (T11 27 %, T12 34 %)"}, {"val": "Se 87 %", "label": "signe de Carnett (pinch test Se 78 %, dysesthésies Se 78 %)"}, {"val": "1/3 à 2/3", "label": "efficacité au long cours de l'infiltration (pas d'essai randomisé)"}], "points_cles": ["Cas : homme de 29 ans, coach sportif, douleur pariétale abdominale très focale depuis 2 ans, majorée à l'effort ; écho demandée pour suspicion de hernie, sans hernie, masse ni collection.", "Le nerf cutané antérieur de l'abdomen est la branche terminale du nerf intercostal : chemine entre transverse et droit de l'abdomen puis perfore le muscle droit ; anatomie très variable (anastomoses, branches multiples).", "Sortie du nerf entre la ligne blanche et la ligne semi-lunaire de Spiegel, plus proche de cette dernière, via un canal fibreux inextensible : étirement, plicature et surtout compression ; théorie ischémique avec névrome.", "Écho : placer la sonde sur le point exact désigné par le patient ; petit nerf épaissi posé sur le muscle droit, à sa sortie ; l'épreuve dynamique (contraction abdominale) montre la compression.", "Clinique : signe de Carnett (douleur majorée à la contraction des abdominaux : pariétal plutôt que viscéral), pinch test (équivalent du Tinel), dysesthésies ; installation progressive ou brutale à 50/50.", "Différentiels : hernies, déchirures musculaires (penser aussi au nerf chez la femme enceinte), tumeurs.", "Trois traitements : infiltration (efficacité 1/3 à 2/3, servant aussi de test anesthésique), radiofréquence (efficacité transitoire), neurolyse chirurgicale (efficacité > 2/3).", "Le patient présenté est asymptomatique à 1 an du geste."], "technique": ["Repérage écho sur le point douloureux désigné du doigt : couches épiderme, hypoderme, aponévrose antérieure du droit, muscle droit, aponévrose postérieure/fascia transversalis, péritoine.", "Rechercher le nerf à sa sortie du muscle droit, entre ligne blanche et ligne semi-lunaire ; appuyer la sonde dessus reproduit la douleur.", "Interposer un épais gel (« gel pad ») pour la cible très superficielle ; aiguille dans le plan guidée vers le névrome.", "Hydrodissection plan par plan à l'anesthésique pour décoller le nerf/névrome des brides adhérentielles, jusqu'à ce que l'anesthésique englobe le nerf.", "Injection du corticoïde au contact du nerf."], "alertes": [{"type": "tip", "texte": "Douleur pariétale focale sans cause évidente + signe de Carnett : rechercher le nerf cutané antérieur sous le doigt du patient."}, {"type": "important", "texte": "Cible très superficielle : gel épais et aiguille dans le plan ; éviter une injection trop superficielle de corticoïde (risque cutané)."}], "cochin": "Penser à l'ACNES devant les échographies pariétales « normales » pour douleur focale ; infiltration écho-guidée simple, à proposer avant la radiofréquence ou la neurolyse chirurgicale.", "tags": ["Échographie", "Nerfs", "Infiltration"], "images": [{"src": "img/acnes-paroi-abdominale-1.jpg", "legende": "Couches de la paroi abdominale en écho et nerf cutané antérieur à sa sortie du muscle droit (flèche)", "t": 1700}, {"src": "img/acnes-paroi-abdominale-2.jpg", "legende": "Clinique : signe de Carnett (Se 87 %), pinch test, dysesthésies", "t": 1920}, {"src": "img/acnes-paroi-abdominale-3.jpg", "legende": "Épidémiologie : incidence 1/1800, étiologies, niveaux T10-T12", "t": 1960}, {"src": "img/acnes-paroi-abdominale-4.jpg", "legende": "Take-home : y penser, repérer la « pépite » sur la tablette de chocolat, hydrodissection", "t": 2100}], "session": "s89"}, {"id": "complications-dermato-corticoides", "horaire": "9h40", "titre": "Les complications dermatologiques des infiltrations de dérivés cortisoniques", "orateur": "Fadila Mihoubi-Bouvier", "t_start": 2120, "t_end": 2975, "resume": "Revue des effets cutanés des infiltrations de corticoïdes en suivant la diffusion du produit dans la peau : flush, hypersensibilité, syndrome de Tachon, réactivation zostérienne, lipoatrophie, hypopigmentation et syndrome de Nicolau. Prévention : guidage par l'imagerie, corticoïde soluble pour les cibles superficielles (Hydrocortancyl plutôt que Diprostène), aiguille fine, rinçage, compression sans massage ; information du patient tracée dans le dossier.", "chiffres": [{"val": "1–40 %", "label": "flush (15 % jugé désagréable), disparaît en 24–72 h"}, {"val": "1/8000", "label": "syndrome de Tachon (épidurales), survient en 1–5 min dans 78 % des cas, dure 10–25 min, récidive 14–60 %"}, {"val": "1,5–40 %", "label": "lipoatrophie (associée à une hypopigmentation dans 6,9 %)"}, {"val": "1,3–4 %", "label": "hypopigmentation"}, {"val": "≈2 %", "label": "atteintes persistantes (lipoatrophie/hypopigmentation), apparition à 2–4 mois"}], "points_cles": ["Flush : réaction vasomotrice (joues, cou, haut du torse), surtout chez les femmes, en quelques heures à 1–2 jours ; informer avant, rassurer après ; antihistaminique d'intérêt hypothétique.", "Hypersensibilité/allergie (souvent au solvant) : urticaire ou éruption maculo-papuleuse prurigineuse, plus étendue (abdomen, dos) : bilan allergologique.", "Syndrome de Tachon : brutal, transitoire, lombalgie aiguë, oppression thoracique, érythème facial, sueurs, malaise ; non allergique (passage vasculaire de cristaux, réaction neurovégétative) mais à traiter comme une anaphylaxie.", "Réactivation VZV (surtout > 65 ans) : avis dermatologique urgent, valaciclovir dans les 48–72 h ; ne pas infiltrer à proximité d'une éruption (zona ou herpès), attendre la régression en 7–10 jours.", "Lipoatrophie : atteinte des adipocytes et baisse du collagène (fibroblastes), plus fréquente chez la femme, centrée sur le point d'injection, décrite avec tous les corticoïdes.", "Hypopigmentation : dysfonction des mélanocytes (pas de baisse de leur nombre) ; à risque face dorsale du poignet, avant-pied, coude, peau foncée ; non décrite aux doigts ; Kenacort surtout mais tous corticoïdes ; forme linéaire par migration lymphatique.", "Rares : télangiectasies, calcifications, hyperpigmentation, syndrome de Nicolau (thrombose artérielle dermique par microcristaux : livedo douloureux, cyanose, parfois nécrose).", "Choix du corticoïde : du plus soluble (dexaméthasone, sans microcristaux) à Hydrocortancyl, Diprostène (bétaméthasone, potentiel thrombogène), Kenacort puis Hexatrione (triamcinolone, microcristaux ++++) ; moins soluble = plus longue durée mais plus de stagnation cutanée.", "Traitement d'une atrophie persistante (avis dermatologique, Dr C. Velter) : surtout attendre ; éventuellement lipofilling ou acide hyaluronique ; hypopigmentation : pas de traitement recommandé, maquillage correcteur, exposition UV.", "Médico-légal (Me L. Soulier) : risque prévisible donc obligation d'information orale en entretien individuel ; charge de la preuve au praticien : tracer l'information dans le dossier, d'autant plus si l'aspect physique compte dans la profession du patient."], "technique": ["Guider par l'imagerie pour cibler et maîtriser la profondeur.", "Adapter la dose et le volume ; cibles superficielles (épicondylite, poignet) : corticoïde soluble (Hydrocortancyl), Diprostène avec parcimonie.", "Aiguille du plus petit calibre possible pour limiter le reflux.", "Aspirer avant d'injecter (éviter l'intravasculaire) ; ne pas injecter en retirant l'aiguille.", "Rincer l'aiguille à l'anesthésique ou au sérum physiologique pour repousser le corticoïde à distance du derme.", "Après le geste : compression immédiate, « couper » le point de ponction en faisant glisser la peau (effet de cisaillement) ; ne pas masser la zone le jour même."], "alertes": [{"type": "warning", "texte": "Syndrome de Tachon : prendre en charge comme une anaphylaxie jusqu'à preuve du contraire (VVP, remplissage, TA, surveillance, prélèvement sanguin) ; risque de récidive."}, {"type": "warning", "texte": "Zona ou herpès actif au voisinage : ne pas infiltrer, attendre la régression (7–10 j) ; zona : valaciclovir dans les 48–72 h."}, {"type": "important", "texte": "Cibles superficielles : éviter les corticoïdes à microcristaux (Diprostène, Kenacort, Hexatrione), préférer un corticoïde soluble (risque thrombogène, atrophie, hypopigmentation)."}, {"type": "tip", "texte": "Kystes superficiels : pousser/cisailler mais ne pas masser après l'injection."}, {"type": "important", "texte": "Information orale sur le risque esthétique, tracée par écrit dans le dossier."}], "cochin": "Formaliser dans les consignes d'infiltration superficielle le choix du corticoïde soluble, le rinçage, la compression sans massage et une mention écrite du risque cutané dans l'information patient.", "tags": ["Infiltration", "Complications"], "images": [{"src": "img/complications-dermato-corticoides-1.jpg", "legende": "Syndrome de Tachon : incidence, délai, durée et symptômes", "t": 2300}, {"src": "img/complications-dermato-corticoides-2.jpg", "legende": "Hypopigmentation post-infiltration : incidence 1,3–4 %, localisations à risque", "t": 2460}, {"src": "img/complications-dermato-corticoides-3.jpg", "legende": "Tableau des corticoïdes : solubilité, taille des microcristaux, potentiel thrombogène, équivalence en prednisone", "t": 2560}, {"src": "img/complications-dermato-corticoides-4.jpg", "legende": "Prévention post-geste : compression immédiate, cisaillement du point de ponction, pas de massage le jour J", "t": 2620}], "session": "s89"}, {"id": "fake-news-ri", "horaire": "9h55", "titre": "3 Fake news en radiologie interventionnelle", "orateur": "Nicolas Stacoffe (Lyon Sud, HCL) — la partie de N. Theumann (Lausanne) n'apparaît pas dans la vidéo", "t_start": 2975, "t_end": 3720, "resume": "N. Stacoffe démonte trois idées reçues : la vertébroplastie ne provoque pas de fractures adjacentes (au contraire, moins de fractures sous VP/KP dans les essais randomisés), le SpineJack n'est pas réservé aux chirurgiens et reste faisable sur pédicules fins sous TDM/CBCT, et l'ostéosynthèse percutanée du bassin traumatique a toute sa place en radiologie. Seule sa partie figure dans cette vidéo ; l'intervention de N. Theumann, annoncée en fin de session, n'y est pas.", "chiffres": [{"val": "RR 0,66", "label": "nouvelles fractures adjacentes VP/KP vs traitement conservateur (méta-analyse 2005–2024 : 5 ECR + 4 rétrospectives, 1930 patients)"}, {"val": "151", "label": "spondyloplasties SpineJack (148 patients, âge médian 49 ans), dont 51 sur pédicules fins"}, {"val": "100 %", "label": "implants SpineJack bien positionnés ; 18 % de fuites de ciment minimes dans les deux groupes"}, {"val": "102/103", "label": "vis réussies (> 99 %) chez 67 patients, ostéosynthèse du bassin traumatique sous CBCT"}, {"val": "43 min", "label": "durée moyenne pour ~2 vis (minimum 19 min) ; couloirs S1 de 12 à 32 mm"}], "points_cles": ["Cas : demande de vertébroplastie T12 pour douleur persistante à 3 mois : maladie de Kümmell (fente, pseudarthrose ne cicatrisant jamais, charnière thoraco-lombaire, micromobilité), le corset ne marchera pas : cimenter.", "L'IRM préopératoire révélait déjà des fractures sus- et sous-jacentes : ce sont la maladie, le déséquilibre sagittal et le Kümmell qui fracturent, pas le ciment ; l'étude du NEJM n'avait pas d'IRM préopératoire.", "VERTOS IV : pas d'augmentation des nouvelles fractures ; méta-analyse 2025 : pas de différence dans les études rétrospectives, moins de fractures adjacentes après VP/KP dans les ECR (RR 0,66).", "SpineJack : implant en titane expansible (3 tailles) ; recommandations de diamètre pédiculaire (≥ 5–5,8 mm pour l'implant de 4,2 mm), souvent non respectées chez la femme, le sujet jeune et en thoracique haut.", "Étude SpineJack (thèse, sous scanner-scopie ou CBCT) : majorité de fractures A1 (69 %) puis A2/A3, perte de hauteur moyenne 30 % ; même restauration de hauteur et même durée entre pédicules fins et recommandés, implant de taille moyenne le plus souvent ; la HAS le classe comme acte de RI.", "Ostéosynthèse percutanée du bassin traumatique sous CBCT (mars 2023 à septembre 2025, fractures instables de l'anneau pelvien Tile B/C et de l'acétabulum) : aucune contre-indication liée au couloir ou à l'anatomie ; une vis desserrée en postopératoire (Tile B2 en compression, pseudo-sciatalgie).", "Fractures déplacées : réduction par traction des membres/du bassin (poids) puis vissage.", "Échange avec la salle : le cimentage préventif d'une vertèbre adjacente à une fente n'est pas jugé absurde (pas de données) ; le traitement de fond de l'ostéoporose relève des rhumatologues.", "Message : la limite n'est pas la spécialité mais la formation, l'indication et la maîtrise technique."], "technique": ["SpineJack sur pédicule fin : guidage TDM ou CBCT, trajet strictement au centre du pédicule, sans passage parapédiculaire (sous scopie seule : risque de fuite de ciment par l'orifice et de débordement dans les parties molles).", "Le guidage 3D permet de poser un implant plus gros que prévu pour gagner en hauteur.", "Bassin traumatique : vissage percutané sous CBCT, réduction préalable par traction si fracture déplacée."], "alertes": [{"type": "important", "texte": "Ne pas laisser dire en RCP que la vertébroplastie entraîne des fractures adjacentes ; faire une IRM préopératoire pour documenter les fractures préexistantes."}, {"type": "warning", "texte": "SpineJack sous scopie seule sur pédicule fin : risque de fuite de ciment et de débordement dans les parties molles ; préférer TDM/CBCT."}, {"type": "tip", "texte": "Fracture vertébrale non consolidée à 3 mois avec fente (Kümmell) : le corset est inutile, cimenter."}], "cochin": "Argumentaire chiffré utile en RCP pour défendre la cimentoplastie, le SpineJack sous TDM/CBCT y compris sur petits pédicules et le vissage percutané du bassin par l'équipe de RI.", "tags": ["Rachis", "Hanche-bassin", "Cimentoplastie", "Vissage"], "images": [{"src": "img/fake-news-ri-1.jpg", "legende": "Maladie de Kümmell : pseudarthrose de la charnière thoraco-lombaire, risque de fracture adjacente", "t": 3060}, {"src": "img/fake-news-ri-2.jpg", "legende": "Méta-analyse 2025 : moins de fractures adjacentes après VP/KP qu'avec le traitement conservateur (RR 0,66)", "t": 3160}, {"src": "img/fake-news-ri-3.jpg", "legende": "Résultats SpineJack sur pédicules fins (4,8 et 3,9 mm) : 100 % de bon positionnement", "t": 3280}, {"src": "img/fake-news-ri-4.jpg", "legende": "Ostéosynthèse du bassin traumatique sous CBCT : 67 patients, 102/103 vis, 43 min en moyenne", "t": 3440}], "session": "s89"}, {"id": "lisfranc-scopie-fantino", "horaire": "10h45", "titre": "Pourquoi je fais mes infiltrations du Lisfranc sous radioscopie ?", "orateur": "O. Fantino (Imagerie médicale du Parc, Lyon) — présentation conjointe avec W. Khaled", "t_start": 0, "t_end": 270, "resume": "Battle « scopie vs écho » présentée à deux voix. Camp SCOPIE (O. Fantino) : l'abord direct de l'interligne tarsométatarsien sous scopie, tube incliné de 30-45°, avec contrôle arthrographique, est simple et reproductible si l'on connaît l'anatomie arthrographique des 3 compartiments ; arguments POUR : preuve objective intra-articulaire (cliché), astuces pour interligne pincé (récessus, abord intercunéen/cunéonaviculaire). Arguments CONTRE soulevés par l'adversaire : injection parfois douloureuse, ostéophytes pouvant barrer l'accès, pas d'information diagnostique (hyperhémie Doppler).", "chiffres": [{"val": "3", "label": "compartiments du Lisfranc (médial C1-M1, intermédiaire C2-M2/C3-M3, latéral cuboïde-M4/M5)"}, {"val": "30-45°", "label": "inclinaison de l'interligne de Lisfranc / verticale → inclinaison du tube"}, {"val": "1", "label": "seul abord (1re commissure) pour piquer Lisfranc médial puis intermédiaire"}], "points_cles": ["Indications identiques scopie/écho : arthropathies dégénératives, post-traumatiques et rhumatoïdes, OBJECTIVÉES par l'imagerie (radio, écho avec hyperhémie Doppler, IRM avec œdème osseux, scanner).", "Identifier avant le geste le(s) compartiment(s) atteint(s) : médial (C1-M1), intermédiaire (C2-M2, C3-M3), latéral (cuboïde-M4 et M5).", "Anatomie arthrographique : Lisfranc médial TOUJOURS isolé ; intermédiaire et latéral communiquent très souvent (surtout si arthropathie) ; l'intermédiaire communique avec les interlignes naviculocunéens et intercunéens.", "Structures nobles : branche sensitive du nerf fibulaire profond et artère dorsale du pied (pédieuse) entre 1er et 2e rayons.", "POUR la scopie : cliché arthrographique = preuve de la position intra-articulaire ; geste rapide en abord direct.", "Astuce 1 : atteinte médiale + intermédiaire → un seul point de ponction dans la 1re commissure, d'abord Lisfranc médial, retrait léger puis réorientation vers l'interligne intermédiaire (dans l'interligne ou dans le récessus).", "Astuce 2 : interligne C2-M2 très pincé → abord intercunéen ou cunéonaviculaire, en profitant des communications arthrographiques.", "Astuce 3 : impossible d'enfiler l'interligne → contact osseux sur la base métatarsienne, en périphérie, injection dans le récessus : l'arthrographie se remplit souvent quand même.", "Aveu final du camp écho : W. Khaled fait lui aussi « majoritairement » ses Lisfranc sous scopie."], "technique": ["Installation : patient en décubitus, genou fléchi, pied à plat sur la table ; centreur lumineux.", "Incliner le tube de 30 à 45° pour enfiler l'interligne ; pour le Lisfranc latéral (orientation différente), coude de l'opérateur sur le genou du patient et ajustement de l'inclinaison genou/pied.", "Abord direct de l'interligne avec une petite aiguille (orange, 25G) ; anesthésie sous-cutanée à la lidocaïne possible (geste parfois douloureux).", "Dès la sensation d'entrée dans l'interligne : brancher une tubulure reliée à une seringue mi-contraste mi-Xylocaïne, injecter un peu de contraste sous scopie, cliché d'arthrographie.", "Désadapter la tubulure et injecter le corticoïde (Diprostène).", "Si interligne inaccessible : récessus (base du métatarsien) ou articulation communicante (intercunéenne, cunéonaviculaire)."], "alertes": [{"type": "warning", "texte": "Entre le 1er et le 2e rayon : branche sensitive du nerf fibulaire profond et artère dorsale du pied — prudence sur l'abord du Lisfranc médial/intermédiaire."}, {"type": "important", "texte": "Le Lisfranc médial est toujours isolé : une injection intermédiaire ne traite pas le compartiment médial (et inversement)."}, {"type": "tip", "texte": "Ne pas s'acharner dans un interligne pincé : le récessus périphérique ou une articulation communicante (intercunéenne/cunéonaviculaire) suffit souvent."}], "cochin": "Approche directement applicable en salle de scopie : systématiser l'inclinaison du tube 30-45° et la tubulure contraste-Xylocaïne avec cliché de preuve, et repérer sur l'imagerie préalable le compartiment atteint.", "tags": ["Scopie", "Cheville-pied", "Infiltration"], "images": [{"src": "img/lisfranc-scopie-fantino-1.jpg", "legende": "Anatomie arthrographique : Lisfranc médial toujours isolé, intermédiaire et latéral communiquant souvent, intermédiaire communiquant avec les interlignes naviculocunéens et intercunéens", "t": 80}, {"src": "img/lisfranc-scopie-fantino-2.jpg", "legende": "Technique : pied à plat sur la table, tube incliné de 30-45° pour enfiler l'interligne tarsométatarsien", "t": 140}, {"src": "img/lisfranc-scopie-fantino-3.jpg", "legende": "Abord direct avec tubulure au temps arthrographique : arthrographies des Lisfranc médial, intermédiaire et latéral", "t": 160}, {"src": "img/lisfranc-scopie-fantino-4.jpg", "legende": "Astuce 1 : un seul abord par la 1re commissure, Lisfranc médial puis intermédiaire", "t": 200}], "session": "s90"}, {"id": "lisfranc-echo-khaled", "horaire": "10h50", "titre": "Pourquoi je fais mes infiltrations du Lisfranc sous échoscopie ?", "orateur": "W. Khaled (Imagerie médicale Créqui, Lyon) — présentation conjointe avec O. Fantino", "t_start": 255, "t_end": 600, "resume": "Camp ÉCHO (W. Khaled) : articulations superficielles accessibles en échographie à condition d'utiliser un abord IN-PLANE AXIAL (comme une acromioclaviculaire), après repérage de l'interligne en coupe sagittale. Arguments POUR : apport diagnostique (hyperhémie Doppler, ostéophyte barrant l'accès radiologique), pas d'irradiation, visualisation directe de la diffusion ; arguments CONTRE (posés par le camp scopie) : nombreuses articulations arthrosiques difficiles à identifier, pas de preuve arthrographique. Conclusion honnête : il les fait lui aussi majoritairement sous scopie, l'écho élargit les options.", "chiffres": [{"val": "3", "label": "possibilités d'abord écho : in-plane sagittal, out-of-plane, in-plane axial (retenu)"}], "points_cles": ["In-plane sagittal à éviter : difficile de cibler l'interligne, surtout en présence d'ostéophytes.", "Out-of-plane (pratique de cliniciens) : aiguille difficile à visualiser.", "Technique retenue : in-plane AXIAL ; en balayant l'interligne (ex. C2-M2), il existe toujours une coupe axiale passant par l'interligne (le « petit trou » entre corticales de C2 et M2).", "Repérage : coupe sagittale pour identifier C2 puis M2 et donc l'interligne, puis bascule de la sonde en axial.", "Voies d'abord : axiale stricte pour le Lisfranc intermédiaire, plus oblique pour le latéral ; abord médial pour le Lisfranc médial (éviter le pédicule dorsal).", "Critères de réussite : injection facile, non résistive, avec distension du récessus articulaire et/ou diffusion au sein de l'interligne à distance de l'aiguille.", "En cas d'interligne sagittal « hostile », se placer directement dans la synovite en axial ; contrôle arthrographique possible (contraste) qui confirme la diffusion habituelle.", "POUR l'écho : bilan diagnostique concomitant (hyperhémie Doppler), contournement d'un ostéophyte qui barre l'accès en radio.", "Fin de session (commune) : histoire de Jacques Lisfranc de Saint-Martin (1787-1847), description de l'atteinte tarsométatarsienne lors de la chute du cavalier le pied coincé dans l'étrier."], "technique": ["Repérage sagittal de C2 puis M2 (ou du compartiment cible) pour localiser l'interligne tarsométatarsien.", "Bascule en coupe axiale ; abord in-plane axial strict (intermédiaire), oblique (latéral), par voie médiale pour le Lisfranc médial.", "Petit bouton d'anesthésie sous-cutanée (confort et positionnement dans le récessus ou l'interligne).", "Seringue Luer-Lock (contrôle des pressions) ; injection test de lidocaïne.", "Vérifier une injection non résistive avec distension du récessus ou diffusion dans l'interligne, puis injecter le corticoïde."], "alertes": [{"type": "warning", "texte": "Lisfranc latéral/intermédiaire : privilégier un abord latéral en raison des rapports vasculonerveux (nerf fibulaire profond, artère dorsale du pied) ; Lisfranc médial : attention au tendon tibial antérieur en médial."}, {"type": "tip", "texte": "Regarder « dans les coins » : la diffusion dans l'interligne à distance de l'aiguille est le meilleur critère de réussite en l'absence de cliché arthrographique."}, {"type": "important", "texte": "Toute injection résistive doit faire repositionner l'aiguille."}], "cochin": "Alternative utile en salle d'écho quand la scopie est indisponible ou qu'un ostéophyte gêne : apprendre l'abord in-plane axial en partant d'un repérage sagittal C2-M2.", "tags": ["Échographie", "Cheville-pied", "Infiltration"], "images": [{"src": "img/lisfranc-echo-khaled-1.jpg", "legende": "In-plane axial : sur scanner, il existe toujours une coupe axiale passant par l'interligne tarsométatarsien C2-M2", "t": 320}, {"src": "img/lisfranc-echo-khaled-2.jpg", "legende": "Repérage échographique sagittal de C2 et M2 puis coupes axiales C2, C2-M2 et M2", "t": 360}, {"src": "img/lisfranc-echo-khaled-3.jpg", "legende": "Voies d'abord : oblique pour le Lisfranc latéral, axiale pour l'intermédiaire et le médial (attention au tendon tibial antérieur)", "t": 380}, {"src": "img/lisfranc-echo-khaled-4.jpg", "legende": "Critères de réussite : injection non résistive, distension du récessus, diffusion intra-interligne, confirmée en arthrographie", "t": 440}], "session": "s90"}, {"id": "kyste-mucoide-lca-echo-thelen", "horaire": "11h00", "titre": "Pourquoi et comment je fais une infiltration des kystes mucoïdes du LCA sous échographie ?", "orateur": "P. Thelen", "t_start": 600, "t_end": 1020, "resume": "Ponction-infiltration échoguidée par voie postéromédiale descendante des kystes mucoïdes du LCA symptomatiques, après IRM obligatoire. Arguments POUR : très efficace et immédiate sur la forme kystique postérieure (vidange par mise en pression), simple, répétable ; LIMITE reconnue : la forme ligamentaire infiltrante (plus fréquente et la plus problématique) ne se vide pas, résultat lent, et « bénéficiera sûrement d'un geste plus agressif » (argument repris par le camp fénestration).", "chiffres": [{"val": "80 mg", "label": "Kenacort Retard (2 ml = 2 ampoules de 40 mg) en fin de procédure"}, {"val": "21G-18G", "label": "aiguilles : verte 21G, PL jaune 20G ou rose 18G selon morphotype"}, {"val": "4-8 sem", "label": "délai avant éventuelle répétition si résultat insuffisant"}], "points_cles": ["Clinique évocatrice : douleur postérieure et postérolatérale du genou EN FLEXION, gêne en flexion.", "IRM incontournable : pas de ponction sans IRM ; diagnostic positif (localisation, type, volume) et différentiel (TCG/SVN, angiome, tumeurs synoviales, épanchement cloisonné du récessus postérieur pris à tort pour un kyste).", "Formes : antérieure (prépinale, non traitée ici), ligamentaire infiltrante (hypertrophie « ballonisée » du LCA, contenu hypoéchogène comblant l'échancrure), kystique postérieure (masse anéchogène refoulant la capsule).", "Forme kystique : la plus favorable ; lavage à l'anesthésique local en mettant le kyste en pression, puis aspiration de la gelée synoviale, même à l'aiguille fine (« le problème n'est pas la viscosité mais la mise en pression »).", "Forme ligamentaire : peu ou pas de gelée aspirable ; injection d'anesthésique puis allers-retours dans le kyste infiltrant (comme un PRP intratendineux) → fragilisation, petit saignement local, meilleure diffusion du corticoïde.", "Corticoïde : triamcinolone acétonide (Kenacort Retard) ou hexacétonide (Hexatrione 2 %, difficile à obtenir) — action sclérosante (fluor) plus marquée que bétaméthasone (Diprostène) ou prednisolone (Hydrocortancyl), action prolongée car moins hydrosoluble.", "Résultats : rapides pour la forme kystique (décompression mécanique, flexion améliorée dès la fin du geste) mais récidive possible ; plus progressifs pour la forme infiltrante (attendre plutôt 4 semaines que 15 jours).", "Cas illustratif : kyste infiltrant traité par 2 ponctions-infiltrations en 2013 (Altim + Hexatrione), IRM 2025 montrant la disparition.", "Répétition : une fois si résultat insuffisant à 4-8 semaines, ou à distance (1-2 ans) si récidive tardive."], "technique": ["Prérequis : IRM du genou confirmant le kyste mucoïde et éliminant les diagnostics différentiels.", "Patient en procubitus ; abord POSTÉROMÉDIAL (axe vasculaire poplité latéral), trajet DESCENDANT : sonde placée dans le creux poplité à distance du point de ponction (ne pas piquer dans le gel) et évitement des veines jumelles (gastrocnémiennes).", "Repère cutané : tendon semi-tendineux, palpable, correspondant souvent au point d'entrée.", "Aiguille verte 21G, PL jaune 20G ou rose 18G selon le morphotype ; anesthésie locale traçante jusqu'à la capsule postérieure (renforcer à ce niveau).", "Forme kystique : entrée dans le kyste, mise en pression à la lidocaïne (ou sérum), vidange-aspiration progressive.", "Forme ligamentaire : anesthésique local puis multiples allers-retours dans le LCA infiltré.", "Fin de procédure : 2 ml de Kenacort Retard (80 mg)."], "alertes": [{"type": "warning", "texte": "Paquet vasculaire poplité (artère et veine latérales) : rester postéromédial ; ne pas piquer trop bas sous peine d'embrocher une veine jumelle, mal visible en procubitus."}, {"type": "important", "texte": "Jamais de ponction de « kyste » sans IRM : TCG/synovite villonodulaire, angiome, tumeur synoviale ou épanchement cloisonné peuvent mimer un kyste en échographie."}, {"type": "tip", "texte": "Un kyste « trop gélatineux » se vide quand même : le mettre en pression avec l'anesthésique ou du sérum puis aspirer."}], "cochin": "Procédure réalisable en vacation d'échographie interventionnelle : voie postéromédiale descendante guidée par le semi-tendineux, Kenacort Retard 80 mg ; réserver la discussion d'un peignage aux formes infiltrantes résistantes.", "tags": ["Échographie", "Genou", "Infiltration"], "images": [{"src": "img/kyste-mucoide-lca-echo-thelen-1.jpg", "legende": "Pourquoi ponctionner : clinique en flexion, IRM pour diagnostic positif et différentiel, formes ligamentaire et kystique postérieure", "t": 660}, {"src": "img/kyste-mucoide-lca-echo-thelen-2.jpg", "legende": "Comment : abord postéromédial, trajet descendant, repère du semi-tendineux, aiguilles 21G à 18G, anesthésie traçante jusqu'à la capsule", "t": 760}, {"src": "img/kyste-mucoide-lca-echo-thelen-3.jpg", "legende": "Forme ligamentaire : injection d'anesthésique et allers-retours de l'aiguille dans le kyste infiltrant", "t": 880}, {"src": "img/kyste-mucoide-lca-echo-thelen-4.jpg", "legende": "Résultats : kyste infiltrant traité en 2013, disparition à l'IRM 2025 ; procédure répétable à 4-8 semaines", "t": 960}], "session": "s90"}, {"id": "fenestration-lca-mucoide-nice", "horaire": "11h05", "titre": "Pourquoi je traite une atteinte mucoïde du LCA par une fénestration", "orateur": "Présenté par A. Rudel (nom tel que transcrit, incertain) pour l'équipe de N. Amoretti, CHU de Nice", "t_start": 1020, "t_end": 1620, "resume": "Fénestration (« peignage ») échoguidée du LCA à l'aiguille 20G avec 15-20 passages, suivie d'une injection de corticoïde, pour décomprimer le conflit dans l'échancrure intercondylienne dans les dégénérescences mucoïdes peu ou pas kystiques. Arguments POUR : la composante kystique ponctionnable n'existe que dans 25-30 % des cas, la chirurgie (résection ± plastie) est lourde et instabilisante ; série niçoise de 56 genoux : EN 6,35 → 0,8 à 4 mois, aucune rupture ni instabilité, effet « on-off » sur la flexion. Limites : rétrospectif, suivi court (4 mois).", "chiffres": [{"val": "56", "label": "genoux traités (50 dossiers complets), mai 2022 - nov. 2025, rétrospectif"}, {"val": "6,35 → 0,8", "label": "EN moyenne avant / à 4 mois (p < 0,001)"}, {"val": "33 % → 81 %", "label": "SKV (score subjectif du genou) avant / à 4 mois (p < 0,001)"}, {"val": "25-30 %", "label": "des cas seulement avec composante kystique ponctionnable majoritaire"}, {"val": "88 % / 90 %", "label": "diminution de l'hypersignal T2 ligamentaire / du bombement postérieur à l'IRM M1"}, {"val": "0", "label": "rupture du LCA, aucun genou instable cliniquement à 4 mois"}, {"val": "5", "label": "échecs (4 réinfiltrés dont 2 bonnes réponses et 2 chirurgies programmées ; 1 hernie discale lombaire)"}], "points_cles": ["Mécanisme douloureux : conflit mécanique entre LCA épaissi et LCP dans l'échancrure intercondylienne (blocage en flexion) ; objectif = décompression percutanée + effet sclérosant du corticoïde.", "Traitement médical jugé insuffisant dans la littérature, injections conventionnelles peu efficaces ; une seule étude (2021, rétrospective, nombreux perdus de vue) sur la fénestration échoguidée du LCA.", "Chirurgie de référence lourde : résection partielle ± geste osseux d'agrandissement de l'échancrure (risque de rupture secondaire/instabilité), résection isolée (mauvais pronostic à moyen/long terme), résection + plastie (morbidité) — les chirurgiens orthopédistes préfèrent ne pas opérer.", "Série : 32 hommes/24 femmes, âge moyen 54 ans (20-76), 80 % de lésions chondrales ou méniscales associées, 83 % avaient déjà reçu au moins une injection intra-articulaire (corticoïde, acide hyaluronique, PRP), délai moyen douleur-prise en charge 33 mois ; aucun genou instable ni traumatisme récent ; SKV pré-geste 33 %.", "IRM à 1 mois : pas de rupture du LCA, épaisseur moyenne 13,75 → 11,8 mm (sagittal) et 8,2 → 7 mm (axial), pas de complication rapportée.", "Clinique à 4 mois : nette amélioration douleur, amplitudes (quasi immédiate si décompression réussie), IKDC et KOOS ; pas de laxité clinique.", "Discussion : cible = partie haute du LCA (celle qui bloque en flexion, LCP souvent inflammatoire au contact) ; injection intraligamentaire ; pas plus de réaction inflammatoire post-geste qu'une infiltration classique.", "Discussion : le PRP n'est pas retenu en 1re intention car l'effet sclérosant recherché est celui du corticoïde.", "Discussion étiologique : dégénérescence mucoïde associée chez le sujet de ≥ 50 ans à lésion méniscale médiale et chondropathie ; chez le jeune, possible séquelle de petite lésion traumatique du LCA ; aucune rupture après peignage percutané (alors que des ruptures sont décrites après peignage chirurgical)."], "technique": ["Même voie d'abord que la ponction échoguidée (postérieure, dans l'axe des fibres du LCA) ; réalisable aussi sous scanner selon l'organisation du service.", "Aiguille 20G (PL jaune) voire 18G ; 15 à 20 passages au sein du ligament et de son enthèse, en biseautant pour élargir la zone de passage.", "Sensation proche d'une ténotomie : ligament initialement tendu, se ramollissant en fin de procédure.", "Si ligament volumineux : ressortir jusqu'à la capsule pour réorienter et fenestrer une autre zone ; viser la partie haute.", "Injection de corticoïde intraligamentaire en fin de geste (effet sclérosant).", "Suivi : IRM à 1 mois, évaluation clinique à 4 mois."], "alertes": [{"type": "important", "texte": "Objectif principal de sécurité : ne pas créer de rupture ni d'instabilité — aucune observée dans la série, mais suivi limité à 4 mois (résultats à 2 ans attendus)."}, {"type": "warning", "texte": "Profondeur et tissu fibreux : réorientation difficile une fois l'aiguille engagée ; repasser par la capsule plutôt que forcer."}, {"type": "tip", "texte": "Penser à une cause rachidienne en cas d'échec : 1 échec de la série était une hernie discale lombaire avec sciatique atypique."}], "cochin": "Option à discuter avec les orthopédistes/médecins du sport pour les dégénérescences mucoïdes du LCA infiltrantes ou après échec d'une ponction-infiltration simple ; protocole de suivi IRM M1 + clinique M4 facilement reproductible.", "tags": ["Échographie", "Genou", "Infiltration", "Études"], "images": [{"src": "img/fenestration-lca-mucoide-nice-1.jpg", "legende": "Pourquoi le peignage : conflit mécanique dans l'échancrure, composante kystique majoritaire dans seulement 25-30 % des cas", "t": 1120}, {"src": "img/fenestration-lca-mucoide-nice-2.jpg", "legende": "Technique échographique : fenestration du LCA à l'aiguille 20G, 15-20 passages dans le ligament et son enthèse", "t": 1140}, {"src": "img/fenestration-lca-mucoide-nice-3.jpg", "legende": "Expérience niçoise : 56 genoux, âge moyen 54 ans, 83 % déjà infiltrés, délai moyen 33 mois", "t": 1180}, {"src": "img/fenestration-lca-mucoide-nice-4.jpg", "legende": "Résultats à 4 mois : EN 6,35 → 0,8, SKV 33 → 81 % (p < 0,001), aucun genou instable, 5 échecs", "t": 1220}], "session": "s90"}, {"id": "rf-genicules-scopie-rudel", "horaire": "11h10", "titre": "Battle géniculés : pourquoi je fais mes RF de nerfs géniculés sous radioscopie ?", "orateur": "A. (Alexandre) Rudel", "t_start": 0, "t_end": 260, "resume": "Plaidoyer pour la fluoroscopie : technique historique (majorité des publications, surtout américaines), adaptable à tous les morphotypes et aux grosses prothèses, rapide, et offrant de nombreuses cibles alternatives sur repères osseux. Pour compenser la petite taille des zones d'ablation des électrodes 18–20 G, il réalise une ablation en « rail » sur 2 points le long de la diaphyse. En pratique il combine très souvent scopie + échographie.", "chiffres": [{"val": "3", "label": "cibles principales : NGSM, NGSL, NGIM"}, {"val": "≈1 cm", "label": "rayon d'ablation approximatif des systèmes 18–20 G"}, {"val": "2 points", "label": "par nerf pour former un « rail » d'ablation"}, {"val": "2021", "label": "début de sa pratique, selon les points des publications"}], "points_cles": ["Cibles classiques sous scopie : nerfs géniculés supéro-médial (NGSM), supéro-latéral (NGSL) et inféro-médial (NGIM), sur repères osseux (jonction métaphyso-diaphysaire).", "Manque de solutions pour les douleurs péri-patellaires et le compartiment tibial latéral : la scopie permet de nombreuses cibles alternatives décrites dans la littérature (McCormick 2023).", "Plexus supra-patellaire : facile à cibler sous scopie, utile sur PTG en cas d'inadéquation de taille entre bouclier fémoral et bouclier patellaire.", "Branche infra-patellaire du saphène : repère condyle médial ; écho associée pour éviter la patte d'oie (risque tendineux) et le risque cutané ; innervation de la capsule antérieure.", "Nerf géniculé inféro-latéral : souvent évité (proximité du col de la fibula et du nerf fibulaire commun), mais ciblage facile avec test sensitif et moteur sur genou natif ; pas de différence d'efficacité ni de sécurité vs autres quadrants (Shi 2023). La branche récurrente fibulaire est plus difficile (risque pour branches profonde et superficielle).", "Systèmes 20 G (et 18 G même en V) : zone d'ablation de faible taille ; aiguilles placées sur repère osseux sans voir le nerf, avec variabilité anatomique → risque de manquer le nerf (tableau Beckwith 2022 : lésion 9–15 mm de large selon technique).", "Technique en « rail » (Conger 2019) : 1re application à la jonction tiers postérieur/tiers moyen de la diaphyse, puis retrait vers la jonction tiers moyen/tiers antérieur pour une 2e application → lésion confluente ; meilleurs résultats que sa technique monopoint antérieure.", "« 4x4 de la RF » : convient à tous les morphotypes, pas d'artefacts métalliques sur les prothèses (vs scanner sur prothèses de reconstruction), repositionnement dynamique du genou en cas de trouble de rotation des implants, rapidité (temps réel).", "Écho systématique en consultation pré-geste pour repérer les variations du trajet nerveux ; si le nerf ne passe pas sur le point, il le cible sous écho le jour J. Double guidage scopie-écho quasi systématique (table de scanner + arceau + échographe en salle)."], "technique": ["Repérage écho en consultation : trajet des nerfs géniculés, variantes notées dans le dossier.", "Sous scopie, aiguille au contact de l'os à la jonction métaphyso-diaphysaire pour NGSM/NGSL/NGIM ; adapter l'incidence au positionnement (rotation) de la prothèse.", "Ablation en rail : 1re application jonction tiers postérieur/tiers moyen, recul de l'aiguille, 2e application jonction tiers moyen/tiers antérieur.", "Inféro-latéral / branche sensitive fibulaire : trajet oblique ascendant pour que toute la partie active (tip) soit sous la peau ; compresse imbibée de sérum physiologique froid sur la peau pendant la thermocoagulation ; tests sensitif et moteur avant chauffe.", "Anesthésie locale limitée au trajet pour ne pas bloquer le nerf et méconnaître une réponse motrice.", "Discussion : reprise de la kinésithérapie « plein pot » dès J10 (pas de rupture tendineuse observée) ; RF à distance de la PTG (il attend 6 mois, blocs nerveux seuls avant) ; nouvelle RF possible à 6 mois en cas de récidive."], "alertes": [{"type": "warning", "texte": "Inféro-latéral : faible distance peau–site d'ablation et proximité du nerf fibulaire commun (col de la fibula) → trajet ascendant, peau refroidie, test moteur obligatoire, peu d'anesthésique local."}, {"type": "warning", "texte": "Branche infra-patellaire du saphène : risque de lésion de la patte d'oie et risque cutané → contrôle échographique."}, {"type": "tip", "texte": "Électrodes 18–20 G = petite lésion (~1 cm) : multiplier les points (rail) pour compenser la variabilité anatomique."}, {"type": "important", "texte": "Complication rapportée en discussion : pseudo-anévrisme de 1 cm d'une artère géniculée latérale découvert fortuitement à l'écho après RF (patient asymptomatique)."}], "cochin": "La RF géniculée sous scopie avec ablation en rail sur 2 points et contrôle écho de la branche infra-patellaire et de la patte d'oie est reproductible en salle de RI ostéo-articulaire, surtout sur PTG. Une écho systématique en consultation pré-geste permet d'anticiper les variantes de trajet.", "tags": ["Scopie", "Genou", "Radiofréquence", "Nerfs"], "images": [{"src": "img/rf-genicules-scopie-rudel-1.jpg", "legende": "Anatomie des nerfs géniculés et cibles alternatives (d'après McCormick et al., Reg Anesth Pain Med 2023).", "t": 20}, {"src": "img/rf-genicules-scopie-rudel-2.jpg", "legende": "Nerf géniculé inféro-latéral / branche sensitive fibulaire : trajet oblique ascendant, compresse de sérum froid sur la peau.", "t": 80}, {"src": "img/rf-genicules-scopie-rudel-3.jpg", "legende": "Faible taille de la zone d'ablation des systèmes 18–20 G (tableau Beckwith 2022).", "t": 100}, {"src": "img/rf-genicules-scopie-rudel-4.jpg", "legende": "Technique en « rail » : 1re application jonction tiers postérieur/tiers moyen, puis tiers moyen/tiers antérieur (Conger 2019).", "t": 140}], "session": "s91"}, {"id": "rf-genicules-echo-filliole", "horaire": "11h15", "titre": "Battle géniculés : pourquoi je fais mes RF de nerfs géniculés sous échographie ?", "orateur": "A. (Antoine) Filliole (CHU de Toulouse)", "t_start": 280, "t_end": 540, "resume": "À Toulouse, la RF des nerfs géniculés est faite sous échographie, en complément éventuel de la scopie : forte culture écho, salle dédiée, ciblage direct du nerf et de son pédicule vasculaire satellite, absence d'artefact prothétique et anesthésie locale maîtrisée jusqu'au contact du nerf. Efficacité comparable à la fluoroscopie : il faut faire ce dont on a l'habitude et ce à quoi on a accès.", "chiffres": [{"val": "30 min", "label": "créneau par patient en salle d'écho"}, {"val": "104,82 €", "label": "AHPA015 (neurotomie pour hyponeurotisation)"}, {"val": "34,97 €", "label": "YYYY028 (guidage échographique)"}, {"val": "20 G / 18 G", "label": "canules (20 G sur la diapo, 18 G utilisées)"}], "points_cles": ["Formation toulousaine très orientée écho dès le 1er semestre d'internat ; salle d'écho interventionnelle dédiée, facilement accessible.", "Ambiance de salle d'écho : manipulateur au contact du patient, lumière tamisée, musique, hypnose conversationnelle.", "Bilan écho pré-geste = diagnostics différentiels : épanchement/synovite (orientant plutôt vers l'embolisation), corps étranger, névrome sur branche nerveuse (traitement focal).", "NGIM : sonde sagittale, repère ligament collatéral médial au-dessus du condyle tibial médial, branche nerveuse au contact du petit pédicule vasculaire.", "NGSM : repère vaste médial, branche vasculaire en profondeur et distalité au contact du condyle fémoral médial = jonction métaphyso-diaphysaire (comme en scopie). NGSL : idem sous le vaste latéral.", "Avantages : précision sur le nerf et le vaisseau satellite (variantes), pas d'artefact de prothèse, anesthésie locale uniquement sur le trajet en s'arrêtant avant le nerf pour ne pas fausser les tests sensitifs/moteurs, possibilité de cibler d'autres nerfs capsulaires (dont branche infra-patellaire du saphène en évitant la patte d'oie).", "Matériel : identique au plateau classique (canules, électrodes, lidocaïne 2 %) + gel et protège-sonde.", "Cotation : pas d'acte CCAM spécifique ; patients en externe ; AHPA015 + YYYY028 (ZZLJ002 9,60 € cité pour l'injection).", "Discussion : abord écho des nerfs supérieurs plutôt cranio-caudal (coupe axiale du nerf) vs antéro-postérieur en scopie/scanner, compensé par la visualisation directe. Pour la branche infra-patellaire du saphène sur genou opéré : partir du collatéral médial en superficie et suivre ses 2–3 branches (dont une très inférieure vers la TTA) ; névromes millimétriques près des cicatrices, cause fréquente de douleur post-PTG, y compris infero-latérale."], "technique": ["Repérage écho : épanchement, synovite, corps étranger, névrome.", "NGIM : sonde sagittale sur le ligament collatéral médial, cible = branche nerveuse au contact du pédicule vasculaire sur le condyle tibial médial.", "NGSM / NGSL : sous les vastes médial / latéral, cible = pédicule vasculaire à la jonction métaphyso-diaphysaire fémorale.", "Anesthésie locale (lidocaïne 2 %) sur le trajet uniquement, arrêt avant le nerf ; tests sensitifs et moteurs puis RF.", "Option : autres nerfs capsulaires (branche infra-patellaire du saphène) en évitant les tendons de la patte d'oie."], "alertes": [{"type": "tip", "texte": "Ne pas infiltrer d'anesthésique au contact du nerf avant les tests : risque de faux négatif sensitif/moteur."}, {"type": "tip", "texte": "Douleur localisée post-PTG (cicatrice, région infra-patellaire) : chercher un névrome de la branche infra-patellaire du saphène à l'écho = intérêt majeur de la RF écho-guidée."}, {"type": "warning", "texte": "Genoux multi-opérés : repérage écho beaucoup plus difficile (muscles atrophiés, cicatrices)."}], "cochin": "Une écho systématique avant RF géniculée (synovite → discuter l'embolisation, névrome → traitement focal) est facile à intégrer. Le couple AHPA015 + YYYY028 est la cotation utilisée à Toulouse en externe.", "tags": ["Échographie", "Genou", "Radiofréquence", "Nerfs"], "images": [{"src": "img/rf-genicules-echo-filliole-1.jpg", "legende": "Nerf géniculé inféro-médial en écho : sonde sagittale, ligament collatéral médial, condyle tibial médial.", "t": 400}, {"src": "img/rf-genicules-echo-filliole-2.jpg", "legende": "Nerf géniculé supéro-médial : vaste médial et pédicule vasculaire au contact du condyle fémoral médial.", "t": 420}, {"src": "img/rf-genicules-echo-filliole-3.jpg", "legende": "Matériel : canules 20 G, électrodes, lidocaïne 2 %.", "t": 480}, {"src": "img/rf-genicules-echo-filliole-4.jpg", "legende": "Cotation : AHPA015 (104,82 €) + YYYY028 (34,97 €).", "t": 520}], "session": "s91"}, {"id": "rf-genicules-scanner-decoux", "horaire": "11h20", "titre": "Battle géniculés : pourquoi je fais mes RF de nerfs géniculés sous scanner ?", "orateur": "E. (Éric) Decoux (Montpellier — Clinique du Parc / CRP)", "t_start": 560, "t_end": 1460, "resume": "Le scanner apporte un placement multiplanaire millimétrique et traçable des électrodes sur les repères osseux, quelle que soit la morphologie, pour une irradiation faible. Pour compenser la variabilité anatomique des nerfs, il associe de nouveaux points cibles (cadavériques) et une RF bipolaire réalisée au bloc opératoire sous sédation, 60 °C pendant 60 s. Fiche incluant la discussion commune des trois orateurs.", "chiffres": [{"val": "60 °C / 60 s", "label": "paramètres de RF"}, {"val": "≈32 mm", "label": "lésion en bipolaire vs ≈9–10 mm par sonde en monopolaire"}, {"val": "10 mm / 16 mm", "label": "écart inter-sondes : sondes droites / Venom (Stryker)"}, {"val": "0,2–0,5 mSv", "label": "irradiation ≈ 2–3 clichés standards"}], "points_cles": ["Précision : positionnement anatomique multiplanaire millimétrique ; visualisation indirecte mais précise du trajet nerveux par les repères osseux (tubercule de l'adducteur, condyle médial, jonction fémoro-tibiale).", "Sécurité : visualisation des structures traversées et contrôle de la profondeur ; protocole standardisé → reproductibilité inter-opérateurs, geste mesurable et vérifiable.", "Indépendant de la morphologie (obésité, PTG, variantes post-traumatiques) ; documentation médico-légale archivable et pédagogique.", "La variabilité anatomique des nerfs géniculés explique une partie des échecs : le ciblage est le point faible de l'efficacité.", "Nouveaux points cibles (études cadavériques) : NGSM plus proximal sur la métaphyse et décalé en médial (≈1 cm de la corticale) ; NGSL plus proximal et toujours au contact de l'os ; NGIM plus supéro-médial de 10 mm et plus postérieur (bandeau périosté plus large).", "RF bipolaire entre points classiques et nouveaux points : lésions plus larges qui « rattrapent » les variations anatomiques.", "Au bloc opératoire (scanner au bloc) : asepsie chirurgicale, réduction du risque infectieux (utile sur prothèses), accès immédiat à l'équipe d'anesthésie.", "Sédation légère : immobilité, confort, moins de douleur au placement et au début de chauffe → moins d'acquisitions, irradiation réduite.", "Perspective : cartographie 3D des nerfs en IRM pré-procédure et fusion IRM/scanner.", "Discussion commune : douleur diffuse → multiplier les cibles ; douleur localisée → écho (petits nerfs, infra-patellaire). Test anesthésique positif puis RF inefficace = argument pour brûler large (bipolaire, rails). Douleur « en étau »/postérieure post-PTG la plus difficile. Kiné reprise dès J10 sans rupture tendineuse. RF à ≥6 mois après PTG, répétable à 6 mois ; demandes de RF pré-opératoires pour retarder la chirurgie. Ponction d'hydarthrose avant le geste : non systématique."], "technique": ["Décubitus dorsal, au bloc, sous sédation.", "Acquisition scanner de repérage des repères osseux.", "Placement des aiguilles sous fluoroCT : écart inter-sondes ≈10 mm (sondes droites) ou ≈16 mm (Venom, Stryker).", "Plaque de dispersion conservée : bascule en RF monopolaire si la distance inter-sondes est trop grande et les sondes ne se reconnaissent pas.", "Confirmation 3D du positionnement.", "Bloc anesthésique local complémentaire + sérum salé pour étendre la zone d'ablation, test moteur.", "RF bipolaire 60 °C pendant 60 s."], "alertes": [{"type": "warning", "texte": "Même au scanner, incertitude persistante sur la localisation exacte des nerfs (trajets inconstants) : prévoir plusieurs points/bipolaire."}, {"type": "important", "texte": "Garder la plaque de dispersion en bipolaire pour pouvoir basculer en monopolaire."}, {"type": "warning", "texte": "Pseudo-anévrisme de 1 cm d'une artère géniculée latérale rapporté en discussion après RF : complication vasculaire possible."}], "cochin": "Le scanner reste pertinent pour les genoux difficiles (obésité, anatomie post-traumatique) ; la RF bipolaire sur points classiques + nouveaux points cadavériques est une piste pour les échecs de RF monopolaire.", "tags": ["Scanner", "Genou", "Radiofréquence", "Nerfs"], "images": [{"src": "img/rf-genicules-scanner-decoux-1.jpg", "legende": "Nouveaux points cibles cadavériques : NGSM plus proximal et médial, NGSL plus proximal au contact de l'os, NGIM plus supéro-médial de 10 mm.", "t": 660}, {"src": "img/rf-genicules-scanner-decoux-2.jpg", "legende": "Ablation bipolaire : lésions plus larges rattrapant les variations anatomiques.", "t": 700}, {"src": "img/rf-genicules-scanner-decoux-3.jpg", "legende": "Placement des aiguilles sous fluoroCT et confirmation 3D ; écart inter-sondes 10 mm (droites) / 16 mm (Venom).", "t": 760}, {"src": "img/rf-genicules-scanner-decoux-4.jpg", "legende": "Protocole : bloc AL + sérum salé, test moteur, RF 60 °C pendant 60 s.", "t": 780}], "session": "s91"}, {"id": "embolisation-arteres-geniculees-chalamet", "horaire": "11h25", "titre": "Pourquoi je fais aussi des embolisations des artères géniculées ?", "orateur": "B. (Bastien) Chalamet (CHU Lyon Sud)", "t_start": 1470, "t_end": 2300, "resume": "À Lyon Sud, la même équipe fait RF et embolisation : genoux inflammatoires/congestifs → embolisation en 1re intention, genoux secs mécaniques → RF (orientation à confirmer). L'embolisation cible les néovaisseaux synoviaux (blush) concordants avec la douleur ; l'équipe utilise le Lipiojoint (émulsion Lipiodol/Optiray), agent transitoire d'efficacité équivalente à l'imipénème sans risque d'antibiorésistance.", "chiffres": [{"val": "84 %", "label": "succès sur hémarthrose récidivante post-PTG (récidive 23 %)"}, {"val": "2 mL + 6 mL", "label": "Optiray + Lipiodol, 20 passages = Lipiojoint"}, {"val": "7–15 min", "label": "délai de réouverture des vaisseaux après Lipiojoint"}, {"val": "1/31", "label": "nécrose condylienne et 1/31 arthrite septique (microparticules < 100 µm)"}], "points_cles": ["Technique décrite par Okuno (Japon) il y a ~10 ans ; physiopathologie : microtraumatismes → synovite, cytokines → angiogenèse pathologique → néo-innervation → douleur. Cible = néovaisseaux dystrophiques (endothélium seul), pas les vaisseaux normaux.", "Indications : gonarthrose résistante au traitement médical > 3–6 mois, EVA > 50 malgré antalgiques/kiné/acide hyaluronique, non encore chirurgicale, Kellgren-Lawrence 1–2 surtout (3 possible) ; hémarthrose récidivante post-PTG (0,5–1 %) après échec du traitement conservateur, alternative à la synovectomie ; PTG douloureuse après élimination des autres causes.", "Résultats : baisse de l'EVA et du WOMAC jusqu'à 2 ans (Okuno 2017, Bagla 2020) ; hémarthrose : 84 % de succès, 23 % de récidive.", "Agents : microbilles 100–300 µm (définitives), imipénème/cilastatine (cristaux ≈40 µm, néovaisseaux ≈50 µm ; risque d'antibiorésistance pour un antibiotique de réanimation), Lipiojoint (Sapoval, essai LipioJoint-1) transitoire : l'effet toxique endothélial du Lipiodol détruit les néovaisseaux, tandis que les artères à paroi complète cicatrisent.", "Comparaison imipénème vs Lipiodol : efficacité équivalente (Guzelbey, CVIR 2024).", "Avantage du transitoire : préservation de la vascularisation à long terme ; idéal futur = billes résorbables (« Nexsphere », centaines de µm).", "Complications (Casadaban ; Luyckx) : érythème 11 %, hématome au point de ponction 10 %, paresthésies 1 % (connaître l'anatomie), fièvre 0,5 % ; arthrite septique 1/31, nécrose condylienne 1/31 avec microparticules < 100 µm.", "Variantes anatomiques fréquentes, surtout sur genou prothétique (néovascularisation, « l'arbre qui cache la forêt ») : multiplier les incidences.", "Logistique : 45 min–1 h pour un opérateur entraîné, 2–3 embolisations par matinée ; ambulatoire (compression 6 h en décubitus ou système de fermeture) → plutôt le matin.", "Cas : PTG avec synovite diffuse en scintigraphie, douleurs condyliennes bilatérales ; gonarthrose native avec chondropathie médiale grade IV exsudative ; hémarthrose : blush synovial, retour veineux précoce, dévascularisation complète après 1,5 mL de Lipiojoint."], "technique": ["Abord fémoral homolatéral antérograde 5F (ou controlatéral selon l'opérateur).", "Angiographie poplitée en amont de la corticale diaphysaire fémorale : cartographie des artères géniculées (descendante, supéro-médiale/latérale, inféro-médiale/latérale, récurrente tibiale antérieure) et des blushs synoviaux.", "Corréler le blush à la topographie clinique de la douleur (ne pas traiter toutes les artères sur une synovite diffuse).", "Microcathétérisme sélectif 1,7 / 2,0 / 2,4F selon le calibre artériel.", "Préparation du Lipiojoint : 2 mL d'Optiray + 6 mL de Lipiodol, 20 allers-retours entre seringues pour émulsionner.", "Injection jusqu'à saturation (≈1,5 mL) ; la reproduction de la douleur du patient à l'injection est un bon signe de ciblage.", "Contrôle : dévascularisation du territoire, disparition du blush. Hémostase : compression 6 h ou système de fermeture ; ambulatoire."], "alertes": [{"type": "warning", "texte": "Microparticules définitives < 100 µm : risque de nécrose osseuse (condyle fémoral) et de lésions cutanées."}, {"type": "warning", "texte": "Imipénème : antibiotique de réanimation, risque d'antibiorésistance en usage pour une pathologie mécanique."}, {"type": "tip", "texte": "Érythème cutané post-injection : vessie de glace."}, {"type": "important", "texte": "Genou inflammatoire ≠ forcément meilleur répondeur à l'embolisation : orientation empirique, encore à prouver."}], "cochin": "L'embolisation géniculée par Lipiojoint est une option à discuter en RCP pour les hémarthroses récidivantes post-PTG et les gonarthroses synovitiques, en lien avec l'équipe vasculaire ; une synovite à l'écho pré-RF peut orienter vers ce geste.", "tags": ["Embolisation", "Genou", "Études"], "images": [{"src": "img/embolisation-arteres-geniculees-chalamet-1.jpg", "legende": "Indications : gonarthrose résistante, hémarthrose récidivante, PTG douloureuse.", "t": 1580}, {"src": "img/embolisation-arteres-geniculees-chalamet-2.jpg", "legende": "Technique : abord fémoral 5F, angiographie poplitée, microcathéter 1,7–2,4F ; schéma des artères géniculées.", "t": 1780}, {"src": "img/embolisation-arteres-geniculees-chalamet-3.jpg", "legende": "Préparation de l'émulsion Lipiojoint (Optiray 2 mL + Lipiodol 6 mL, 20 passages).", "t": 1940}, {"src": "img/embolisation-arteres-geniculees-chalamet-4.jpg", "legende": "Complications de l'embolisation géniculée (érythème 11 %, hématome 10 %, nécrose condylienne 1/31 avec particules < 100 µm).", "t": 2020}], "session": "s91"}, {"id": "doigt-ressaut-lapegue", "horaire": "11h40", "titre": "Auto-battle : pourquoi j'ai changé ma technique pour les doigts à ressaut — up and down versus allers-retours", "orateur": "F. (Franck) Lapègue (Toulouse)", "t_start": 2300, "t_end": 3000, "resume": "Après 2014–2019 de libération écho-guidée de la poulie A1 à l'aiguille 21 G par allers-retours horizontaux (10–15 passages), F. Lapègue est passé à des mouvements ascendants « up and down » par rotation, biseau toujours latéral, aiguille courbée à 145°, par sections de 2 mm. Impressions (non publiées) : moins de ressaut résiduel, plus d'échec sur les grades 4 et beaucoup moins de ténosynovites exsudatives de novo.", "chiffres": [{"val": "315/350 (90 %)", "label": "absence de ressaut à J0, ancienne technique ; 96,8 % à 1 mois"}, {"val": "13 %", "label": "douleur à 1 mois (39/300 : 33 modérées, 6 importantes)"}, {"val": "98 %", "label": "patients satisfaits ou très satisfaits à 6 mois"}, {"val": "3/an vs 1/mois", "label": "ténosynovites de novo nouvelle vs ancienne technique"}], "points_cles": ["Point clé inchangé : biseau orienté latéralement.", "Ancienne technique : allers-retours horizontaux, 10–15 passages ; libération anatomique incomplète en laboratoire d'anatomie.", "Résultats 2014–2019 : 90 % sans ressaut à J0, 9,4 % de grade 1 résiduel, 0,6 % d'échec (grade 4, surtout pouces) ; ecchymose 8 % ; pas de rupture tendineuse ni de bowstring.", "Ténosynovite exsudative de novo 1–2 mois après le geste (2 à 13 %), traitée par simple infiltration en un mois.", "Dispositifs dédiés imaginés (enveloppe Soleau 2016) mais non fabriqués ; choix d'une solution low-tech avec le matériel existant.", "Nouvelle technique : aiguille 21 G courbée à 145°, mouvements ascendants de rotation bas→haut au-dessus de la poulie, de distal en proximal par sections de 2 mm (longueur du biseau), ≈5 passages ; libération ressentie, voire entendue.", "Angle aiguille/poulie A1 idéal 30–45° ; en béquant on arrive à 5/0°. Astuce : positionner l'aiguille en oblique (non strictement sagittale) pour passer dans l'espace interdigital et augmenter l'angle de rotation.", "Résultats préliminaires : ressaut résiduel ≤ 5 % (vs 10 %), 0 % d'échec sur grade 4, dissection (atelier de Genève) en faveur d'une meilleure libération anatomique — à confirmer.", "Hypothèse : incision plus linéaire et propre, moins de « charpie » de la gaine synoviale → moins d'inflammation."], "technique": ["Diagnostic clinique + échographique : épaississement et hyperhémie Doppler de la poulie A1, épaississement des fléchisseurs en aval, défaut de glissement dynamique, nodule de tendinose.", "Matériel : champ stérile troué, protège-sonde, gel stérile, compresses, Diprostène (aiguilles orange 25 G et verte 21 G), seringue 5 mL, Xylocaïne, pansement.", "Patient allongé, main paume vers le haut sur une table ; asepsie selon protocole.", "Anesthésie : aiguille 25 G visant la partie distale de A1, technique du gel pad, 3 mL de Xylocaïne autour de la poulie et dans la gaine des fléchisseurs.", "Préparation de l'aiguille 21 G : biseau latéral, courbure à 145°.", "Libération : aiguille à la partie distale de A1, position vérifiée en longitudinal et en axial ; angulation 30–45° ; mouvements ascendants de rotation par sections de 2 mm jusqu'à la partie proximale ; contrôle par mouvements ascendants finaux.", "Injection de corticoïde (Diprostène) pour limiter la réaction inflammatoire ; vérification clinique (± écho du glissement) ; pansement compressif."], "alertes": [{"type": "tip", "texte": "Angle insuffisant : déporter l'aiguille en oblique dans l'espace interdigital pour pouvoir béquer davantage."}, {"type": "warning", "texte": "Pouces et grades 4 : techniquement plus difficiles, principale source d'échec avec l'ancienne technique."}, {"type": "important", "texte": "Ténosynovite exsudative de novo à 1–2 mois : penser à l'écho, une infiltration suffit en général."}, {"type": "tip", "texte": "Résultats de la nouvelle technique = impressions personnelles, série et dissections à confirmer."}], "cochin": "La technique « up and down » à l'aiguille 21 G courbée, réalisable avec le matériel standard, peut remplacer les allers-retours horizontaux pour les libérations de A1 écho-guidées, en restant prudent faute de série publiée. Tutoriel YouTube disponible via le QR code de la présentation.", "tags": ["Échographie", "Main-poignet", "Tendons"], "images": [{"src": "img/doigt-ressaut-lapegue-1.jpg", "legende": "Résultats 2014–2019 de l'ancienne technique (allers-retours) : 90 % de libération à J0.", "t": 2400}, {"src": "img/doigt-ressaut-lapegue-2.jpg", "legende": "Signes écho du doigt à ressaut : épaississement et hyperhémie de A1, épaississement des fléchisseurs en aval.", "t": 2600}, {"src": "img/doigt-ressaut-lapegue-3.jpg", "legende": "Aiguille 21 G courbée à 145°, biseau latéral, en place sur la poulie A1.", "t": 2740}, {"src": "img/doigt-ressaut-lapegue-4.jpg", "legende": "Point clé n° 3 : angle aiguille/poulie A1, béquage vers le haut.", "t": 2880}], "session": "s91"}, {"id": "toxine-botulique-sdlc", "horaire": "11h50", "titre": "Efficacité antalgique des infiltrations musculaires de toxine botulique A dans le traitement du syndrome des loges chronique des membres inférieurs : série de 40 patients", "orateur": "C. Goumarre (CHU de Toulouse)", "t_start": 0, "t_end": 520, "resume": "Travail de thèse rétrospectif monocentrique (CHU de Toulouse, juin 2019 – mai 2023) : 36 patients présentés (45 infiltrations) traités par injections intramusculaires échoguidées de toxine botulique A (Botox) pour un syndrome des loges chronique d'effort. Diminution significative de l'EVA à 1, 3 et 6 mois dès la première infiltration, sans complication majeure. Option simple, peu invasive, renouvelable, pouvant servir de test thérapeutique avant fasciotomie.", "chiffres": [{"val": "36", "label": "patients inclus (≈ 25 ans, majoritairement sportifs ; programme : 40)"}, {"val": "45", "label": "infiltrations (7 patients × 2, 1 patient × 3)"}, {"val": "8,03 → 4,75", "label": "EVA moyenne avant → 1 mois après 1re infiltration (p < 0,0001)"}, {"val": "5,29 / 6", "label": "EVA à 3 mois (p < 0,0001) / à 6 mois (p < 0,01)"}, {"val": "2/3", "label": "infiltrations avec amélioration au moins modérée (GPE), aucune aggravation"}, {"val": "15 + 7", "label": "patients avec reprise sportive complète + partielle"}, {"val": "17 %", "label": "patients avec complication mineure (6/36 ; 10 infiltrations = 27 %) vs 75 % dans Isner-Horobeti 2013"}], "points_cles": ["SDLC : douleur d'effort récurrente, rapidement progressive, régressive au repos, chez le sujet jeune sportif (décrit initialement chez les militaires) ; physiopathologie multifactorielle (hyperpression intramusculaire à l'effort, déséquilibre apports/besoins en O2).", "Diagnostic : clinique + mesures de pression intramusculaire (critères de Pedowitz) au repos, à l'effort sur tapis puis à 1 et 5 min ; test positif si au moins une pression augmentée. Écho-Doppler artériel systématique pour éliminer un syndrome de l'artère poplitée piégée.", "Traitement non invasif (kiné, AINS, orthèses, 3 à 6 mois) : succès insuffisant et inadapté aux sportifs/militaires ; fasciotomie = traitement de référence curatif mais ~20 % d'échec/douleur résiduelle, moins efficace sur les loges postérieures, complications croissantes avec le nombre de loges opérées.", "Toxine botulique A : dénervation chimique → amyotrophie, effet antinociceptif et anti-inflammatoire.", "Population : atteinte surtout bilatérale (80 % des infiltrations) ; loges ciblées : antérieure 64 %, latérale 58 %, postérieure superficielle 29 %, postérieure profonde 33 %.", "EVA significativement réduite à 1, 3 et 6 mois (toutes infiltrations et 1re infiltration seule), et à 1 et 3 mois après une 2e infiltration ; pas de différence d'efficacité selon la loge (antéro-latérale vs postérieure).", "Recul ≥ 10 mois : aucune complication majeure ; 5 patients avec douleurs post-injection soulagées par palier 1, 1 patient (3 infiltrations) avec déficit des releveurs sans retentissement fonctionnel.", "Résultats moins francs qu'Isner-Horobeti (2013, 16 patients, loges antéro-latérales seulement, Dysport) : différence de spécialité, ratio de conversion Dysport/Botox de 2,5 à 3.", "Limites : rétrospectif, effectif limité, recueil téléphonique biaisé, doses infiltrées mal documentées."], "technique": ["Indication : SDLC confirmé par médecin du sport (Pedowitz positif), patient ≥ 15 ans, diagnostics différentiels vasculaires éliminés (écho-Doppler artériel).", "Produit : toxine botulique A (Botox), poudre reconstituée dans plusieurs mL de NaCl 0,9 %.", "Dose : 30 à 100 U par loge musculaire, 100 à 200 U au total par jambe, répartition homogène dans la loge.", "Guidage échographique : ponction intramusculaire, injection en se retirant progressivement de la profondeur vers la superficie.", "Suivi : EVA à 1, 3 et 6 mois, échelle d'impression globale de changement (GPE), reprise sportive ; ré-infiltration possible."], "alertes": [{"type": "warning", "texte": "Déficit moteur possible (déficit des releveurs observé après 3 infiltrations) : informer le patient d'une perte de force transitoire, surtout chez le sportif."}, {"type": "important", "texte": "Les doses ne sont pas interchangeables entre spécialités : ratio de conversion Dysport/Botox ≈ 2,5 à 3."}, {"type": "tip", "texte": "Une réponse franche à la toxine peut servir de test thérapeutique/diagnostique en cas de doute avant fasciotomie."}], "cochin": "Geste échoguidé simple et reproductible, à proposer en lien avec les médecins du sport chez un patient avec SDLC prouvé (Pedowitz) refusant ou en attente de fasciotomie, en notant précisément spécialité et unités par loge.", "tags": ["Échographie", "Muscles", "Infiltration", "Études"], "images": [{"src": "img/toxine-botulique-sdlc-1.jpg", "legende": "Déroulement de l'infiltration : Botox dilué dans le NaCl 0,9 %, 30 à 100 U/loge et 100 à 200 U/jambe, image échographique d'injection des loges antérieure et latérale", "t": 180}, {"src": "img/toxine-botulique-sdlc-2.jpg", "legende": "Caractéristiques de la population : 45 infiltrations, latéralité, loges ciblées (dont 29 % postérieure superficielle et 33 % postérieure profonde), nombre d'infiltrations par patient", "t": 260}, {"src": "img/toxine-botulique-sdlc-3.jpg", "legende": "Évolution de l'EVA après la première infiltration : 8,03 → 4,75 (1 mois), 5,29 (3 mois), 6 (6 mois)", "t": 280}, {"src": "img/toxine-botulique-sdlc-4.jpg", "legende": "Conclusion : option simple, efficace, peu invasive et renouvelable, risque faible, possible traitement d'épreuve", "t": 500}], "session": "s92"}, {"id": "ponction-hematome-musculaire", "horaire": "12h00", "titre": "Quand et comment je ponctionne un hématome musculaire sous échoscopie ?", "orateur": "L. Moya (INSEP, Paris)", "t_start": 520, "t_end": 1165, "resume": "Chez le sportif, on ponctionne un hématome musculaire symptomatique ou ≥ 3 cm dès que l'échographie montre un contenu liquidien ou mixte compressible, quel que soit le délai. Matériel simple (aiguille 18 G, seringue 10 mL ± robinet 3 voies), massage manuel vers l'aiguille, et surtout compression faite par le radiologue avec contrôle échographique : la ponction seule n'est que la moitié du travail.", "chiffres": [{"val": "≥ 3 cm", "label": "plus grand diamètre justifiant la ponction (ou hématome symptomatique)"}, {"val": "J4–J10", "label": "fenêtre théorique idéale (phase de liquéfaction J5–J14)"}, {"val": "12–13 %", "label": "hématomes caillotés/organisés non ponctionnables (~15 % chez le sportif)"}, {"val": "18 G", "label": "aiguille rose recommandée (verte 21 G insuffisante)"}, {"val": "10 mL", "label": "seringue optimale (20 mL : +15 % de vide mais 2× plus de force)"}, {"val": "24–72 h", "label": "bandage élastique compressif immédiat"}], "points_cles": ["Trois populations : sujets âgés sous anticoagulants (> 80 ans, ¾ des hématomes majeurs, ilio-psoas et droits de l'abdomen), hémophiles (15 % des saignements), sportifs.", "Sportif : lésions intrinsèques (efforts violents : droit fémoral, biceps fémoral, plus rarement triceps sural et adducteurs) et extrinsèques/contusions (sports collectifs, combat : vaste latéral, vaste intermédiaire, mollet).", "Phases : hémorragique → caillotée (J1–J5, plus rapide et marquée chez le sportif, hypercoagulabilité transitoire d'effort) → liquéfaction (J5–J14, phase optimale de ponction, non systématique) → résorption/cicatrisation (J20–J40).", "La liquéfaction peut manquer : gros volume initial, organisation rapide (traumatisme direct), localisation profonde peu vascularisée. Des ponctions productives sont rapportées jusqu'à J90 : c'est l'échographie qui décide.", "Buts : soulager, accélérer le retour sur le terrain, limiter fibrose, raideur, ossification secondaire, et plus rarement compression nerveuse, syndrome des loges, infection. Une aspiration partielle reste utile.", "Ponctionner ce qui est anéchogène/hypoéchogène et dépressible sous la sonde ; ne pas ponctionner l'hématome caillotté, échogène complexe, incompressible.", "Un seul point de ponction suffit même pour un très gros hématome (ex. disséquant vaste latéral/vaste intermédiaire) : là où c'est le plus facile et le plus volumineux.", "Ossification secondaire périphérique : ne pas renoncer, l'aiguille traverse la coque et l'aspiration du centre liquidien réduit le volume ossifié et les séquelles.", "Hématome caillotté : rien d'injecté pour le dissoudre (rien de validé) ; contrôle à J5–J10 pour attraper une liquéfaction secondaire.", "PRP systématique après ponction (études anglaises : moins de récidive, retour plus rapide) : faible niveau de preuve et favorise les ossifications ; non pratiqué à l'INSEP."], "technique": ["Asepsie stricte : gants stériles, désinfection, protège-sonde.", "Aiguille 18 G (rose), longueur 4–5 cm en général (plus longue si profond) ; garder le capuchon. Aiguilles plus grosses rarement utiles et plus traumatiques.", "Seringue 10 mL ; si hématome volumineux, robinet 3 voies (système clos, vidanges répétées sans souiller le champ).", "Un seul point de ponction, sur la zone la plus accessible et la plus volumineuse ; vigilance vasculo-nerveuse surtout aux adducteurs.", "Comprimer et masser l'hématome à la main pour diriger le sang vers l'aiguille ; la sonde peut être lâchée, seringue bloquée en aspiration (capuchon calé) pour récupérer les derniers mL.", "Fin de geste : bandage élastique compressif posé par le radiologue (24–72 h, 30–50 mmHg), relais bas de contention classe II ou III 1 à 2 semaines aux membres inférieurs, glaçage les premiers jours.", "Contrôle échographique à J+5 si hématome très volumineux (> 1 seringue retirée) ; systématique chez l'hémophile ou le patient sous anticoagulant."], "alertes": [{"type": "warning", "texte": "Hématome caillotté (échogène, complexe, incompressible) : ne pas s'acharner, reprogrammer un contrôle à J5–J10."}, {"type": "important", "texte": "Sans compression ni contrôle, récidive/fibrose fréquente : la ponction seule ne fait que la moitié du travail."}, {"type": "warning", "texte": "Patient hémophile ou sous anticoagulant : contrôle échographique systématique après ponction."}, {"type": "tip", "texte": "Éviter le PRP post-ponction systématique : risque d'ossification secondaire."}], "cochin": "Protocole facilement standardisable en salle d'échographie : kit 18 G + seringue 10 mL + robinet 3 voies + bande élastique, avec contrôle échographique programmé à J5 pour les gros volumes et les patients anticoagulés.", "tags": ["Échographie", "Muscles", "Complications"], "images": [{"src": "img/ponction-hematome-musculaire-1.jpg", "legende": "Phases de l'hématome musculaire : hémorragique, caillotée (J1–5), liquéfaction (J5–14) = moment de la ponction", "t": 640}, {"src": "img/ponction-hematome-musculaire-2.jpg", "legende": "Choix de l'aiguille : tableau couleur/gauge/diamètre, aiguille rose 18 G (1,20 mm) recommandée", "t": 800}, {"src": "img/ponction-hematome-musculaire-3.jpg", "legende": "Post-ponction : bandage élastique 24–72 h, bas classe II–III 1–2 semaines, glace, contrôle échographique à J+5", "t": 920}, {"src": "img/ponction-hematome-musculaire-4.jpg", "legende": "Ossification secondaire : ponction productive avec affaissement significatif malgré une minéralisation périphérique", "t": 1020}], "session": "s92"}, {"id": "doxycycline-collections-recidivantes", "horaire": "12h10", "titre": "Comment je traite les collections traumatiques récidivantes à la « Vibramycine » (doxycycline) ?", "orateur": "N. Sans (CHU de Toulouse)", "t_start": 1165, "t_end": 1830, "resume": "Sclérothérapie à la doxycycline (Vibraveineuse) des lésions de Morel-Lavallée récidivantes, étendue aux hématomes chroniques récidivants multiponctionnés (tennis leg) : ponction-aspiration par cathéter 18 G, injection de 50 mL de mélange doxycycline/NaCl, infusion 1 h avec rotations, réaspiration puis compression énergique. Série pragmatique toulousaine 2021–2024 : 6 succès sur 8. Technique simple, peu morbide mais totalement hors AMM.", "chiffres": [{"val": "8", "label": "patients (6 hommes, 2 femmes), CHU de Toulouse 2021–2024"}, {"val": "6/8", "label": "succès (pas de récidive clinique ni échographique)"}, {"val": "5 × 100 mg", "label": "ampoules de Vibraveineuse (25 mL) + 25 mL NaCl 0,9 % = 50 mL"}, {"val": "1 h", "label": "infusion intracavitaire, ¼ de tour toutes les 15 min"}, {"val": "< 400 mL", "label": "volume de collection associé à un meilleur succès"}, {"val": "81,60 €", "label": "par ampoule (4 à 5 nécessaires)"}], "points_cles": ["Morel-Lavallée : décollement traumatique par cisaillement créant une néocavité sus-aponévrotique remplie de sang, lymphe et graisse, pouvant se chroniciser ; diagnostic échographique (collection fluctuante au-dessus de l'aponévrose) ± IRM.", "Options : ponctions itératives (récidive fréquente), éthanol, talc (comme pour les pleurésies récidivantes), chirurgie parfois délabrante. Un talcage chez un sportif professionnel a entraîné une granulomatose de la cavité.", "Principe de la doxycycline : supprimer la cavité libre en provoquant une inflammation contrôlée de la paroi favorisant l'adhésion des tissus et prévenant la récidive.", "Extension aux hématomes chroniques récidivants multiponctionnés, notamment tennis leg : cas d'un rugbyman international avec 3 ponctions récidivées, restitution ad integrum et reprise de la compétition au niveau international quelques mois plus tard.", "Série observationnelle rétrospective : inclusion > 18 ans, hématome musculaire ou Morel-Lavallée en échec après 3 ponctions ou 1 geste hors AMM (ex. talcage) ; exclusion < 18 ans, collection non compressible, refus. Critère principal : récidive clinique/échographique.", "Littérature pauvre (cas cliniques, séries rétrospectives hétérogènes) ; une revue (Injury) suggère de meilleurs résultats de la doxycycline que le talc ou l'éthanol.", "Une seule complication : douleur pendant l'heure d'infusion.", "Intérêt médico-économique vs chirurgie et indemnités journalières chez le sportif de haut niveau ; alternative low-cost décrite (comprimés ouverts et dilués, ≈ 2,50 €), non retenue ici."], "technique": ["Acte A – Indication : collection traumatique récidivante (Morel-Lavallée ou hématome chronique) après ≥ 3 ponctions en échec ou un geste hors AMM, collection compressible, patient > 18 ans, information du caractère hors AMM.", "Préparation : 5 ampoules de Vibraveineuse 100 mg (25 mL) + 25 mL de NaCl 0,9 % = 50 mL de mélange.", "Acte B/C – Ponction-aspiration échoguidée aussi complète que possible par cathéter court 18 G laissé en place avec robinet 3 voies (ex. 4 seringues de 50 mL), jusqu'au collapsus de la cavité.", "Acte D – Injection des 50 mL de mélange par le cathéter, puis infusion 1 h : rotation du patient d'un quart de tour toutes les 15 min pour imprégner toutes les parois (brancard immobilisé 1 h).", "Acte E – Réaspiration du mélange.", "Acte F – Compression énergique (bandage) à garder 72 h à 4 jours ; suivi clinique et échographique de la récidive."], "alertes": [{"type": "important", "texte": "Usage totalement hors AMM, aucune recommandation française ou européenne : information et consentement du patient indispensables."}, {"type": "warning", "texte": "Compression insuffisante = récidive : la compression finale (72 h – 4 j) conditionne le succès."}, {"type": "warning", "texte": "Douleur possible pendant l'infusion ; collection non compressible = contre-indication."}, {"type": "tip", "texte": "Meilleures chances de succès si volume < 400 mL."}], "cochin": "Option de recours à discuter pour les Morel-Lavallée et hématomes chroniques récidivant après plusieurs ponctions, avant la chirurgie, avec la pharmacie (coût de la Vibraveineuse) et un consentement spécifique hors AMM.", "tags": ["Échographie", "Muscles", "Complications"], "images": [{"src": "img/doxycycline-collections-recidivantes-1.jpg", "legende": "Doxycycline (Vibraveineuse 5 × 100 mg, 25 mL) : principe de sclérose de la cavité libre", "t": 1320}, {"src": "img/doxycycline-collections-recidivantes-2.jpg", "legende": "Acte C : ponction-aspiration échoguidée par cathéter avec robinet 3 voies, seringues de 50 mL de liquide séro-hématique", "t": 1380}, {"src": "img/doxycycline-collections-recidivantes-3.jpg", "legende": "Acte D : infusion d'une heure avec rotation du patient d'un quart de tour toutes les 15 minutes", "t": 1440}, {"src": "img/doxycycline-collections-recidivantes-4.jpg", "legende": "Facteurs de succès (volume < 400 mL, technique aisée, peu de complications) et limites (hors AMM, données limitées, récidive si compression insuffisante, 81,60 €/ampoule)", "t": 1740}], "session": "s92"}, {"id": "rf-nevromes-genou-cheville", "horaire": "14h00", "titre": "Comment je traite par radiofréquence échoguidée des névromes du genou et de la cheville ?", "orateur": "A. Ponsot (clinique, Lyon)", "t_start": 0, "t_end": 740, "resume": "Les névromes post-opératoires du genou et de la cheville sont fréquents, très invalidants et mal pris en charge (délai d'adressage moyen de 24 mois). Après un test anesthésique positif et un échec de l'infiltration cortisonée, la thermocoagulation par radiofréquence monopolaire échoguidée (80 °C, 90 s par position) est très efficace sur les névromes nodulaires bien limités, avec des complications exceptionnelles.", "chiffres": [{"val": "5 %", "label": "névromes symptomatiques après prothèse totale de genou"}, {"val": "3,5 %", "label": "lésions nerveuses après arthroscopie de cheville"}, {"val": "24 mois", "label": "délai moyen d'adressage au chirurgien des nerfs"}, {"val": "18", "label": "interventions (20 névromes : 10 genoux, 8 chevilles/pieds) en 16 mois"}, {"val": "12/18", "label": "névromes bien limités et test complet : régression complète dans près de 100 % des cas (recul max 12 mois)"}, {"val": "12 × 6 mm", "label": "volume ovalaire de thermocoagulation, électrode 20 G tip 10 mm, 80 °C, 90 s"}], "points_cles": ["Physique : à 45 °C destruction de la myéline, au-delà de 60 °C destruction de l'axone et de l'endonèvre ; le nerf peut se régénérer dans les mois/années suivants.", "Le volume de thermocoagulation dépend de la taille de l'électrode, de la température maximale et de la durée.", "Indication posée en consultation : anamnèse, compte rendu opératoire, douleur neuropathique (DN4, EVA), Tinel, échographie (nerf lésé, névrome, structures adjacentes) et absence d'indication chirurgicale prévalente.", "Test anesthésique et infiltratif obligatoire : positif si régression d'au moins 50 % (disparition complète le plus souvent) ; la RF n'est proposée qu'en cas d'échec de l'infiltration cortisonée.", "Nerfs les plus traités : infrapatellaire au genou (après PTG/PUC), sural à la cheville ; délai moyen après chirurgie de 3 ans, patients de 34 à 73 ans.", "On peut placer la canule sous le nerf puis directement à travers le névrome (la thermocoagulation intranévromateuse est décrite sans problème dans les névromes d'amputation).", "6 patients aux résultats mitigés (1 succès, 3 incomplets, 2 échecs) : neuropathies discutables, épaississements de branches sans névrome nodulaire, tests anesthésiques incomplets.", "Causes d'échec supposées : électrode mal positionnée dans les tissus cicatriciels (surtout nerf infrapatellaire) et prise en charge trop tardive avec douleurs de désafférentation.", "Attendre 6 mois post-opératoires avant de traiter (la majorité des douleurs nerveuses post-opératoires régressent spontanément) ; alternative chirurgicale : résection-enfouissement, difficile sur ces petits nerfs distaux.", "Discussion : à distance, le gros névrome sural (9 × 7 mm) paraissait moins « joufflu » en échographie ; récidive probable à long terme, mais pas d'expérience de la RF pulsée pour ces nerfs sensitifs distaux (thermique préférée)."], "technique": ["Consultation préalable + test : 1 à 2 mL d'un mélange 50/50 lidocaïne 1 % / ropivacaïne 1 % + 1/3 d'ampoule de Diprostène au contact du névrome sous échographie, réévaluation après 1 à 5 min.", "Information du patient (résultats attendus, risque de névrite thermique, lésion des structures adjacentes), remise d'une fiche explicative.", "En externe, salle d'échographie avec une aide-soignante, environ 45 min ; plaque de retour sur le mollet homolatéral.", "Matériel : générateur Stryker Multigen 2 (4 entrées), électrodes Venom tip 1 cm, canules courbes 20 G de 10 cm ; mode monopolaire thermique (continu).", "Bloc nerveux d'amont quelques centimètres au-dessus du névrome : 3 à 5 mL lidocaïne 1 % / ropivacaïne.", "Hydrodissection périnévrome au sérum physiologique (3 à 5 mL) pour refouler peau et tendons (ex. fibulaires) et favoriser la diffusion de l'onde.", "Mise en place de la canule : d'abord sous le nerf, puis à travers le névrome ; contrôle de la distance aux structures adjacentes.", "Vérification de l'impédance (200-300 Ω), tests sensitifs jusqu'à 2 V (souvent négatifs après le bloc), pas de test moteur (nerfs purement sensitifs).", "1 cycle de 90 s à 80 °C par position (2 positions) ; baisser à 60 °C si trop douloureux ; reproduction initiale de la douleur puis disparition.", "Infiltration finale par la canule : 1 mL d'Hydrocortancyl (acétate de prednisolone), car sous-cutané : réduit le risque de névrite thermique et de dystrophie cutanée.", "Sortie : consignes de pansement, antalgiques, arrêt de travail si besoin, disponibilité de l'opérateur (mail/téléphone)."], "alertes": [{"type": "warning", "texte": "Risque de névrite thermique secondaire invalidante et de brûlure des structures adjacentes (peau, tendons, nerf voisin) : hydrodissection systématique et information du patient. Une complication mineure observée : lésion thermique douloureuse du rétinaculum des fibulaires, résolutive."}, {"type": "tip", "texte": "Névrome proche d'un nerf noble (ex. rameau calcanéen médial à 4 mm du nerf plantaire latéral) : seconde électrode placée entre les deux nerfs comme thermocouple, montée progressive à partir de 42-45 °C par paliers de 5 °C jusqu'à 60 °C, en gardant moins de 45 °C au thermocouple (43,5 °C observés)."}, {"type": "important", "texte": "Ne traiter que des névromes nodulaires bien visibles avec un test anesthésique complet : les neuropathies mal définies donnent des résultats aléatoires."}], "cochin": "Geste réalisable en salle d'échographie avec un générateur de RF standard pour les névromes post-PTG (nerf infrapatellaire) ou post-chirurgie de cheville (nerf sural), à condition d'un test anesthésique préalable et d'un recul post-opératoire d'au moins 6 mois.", "tags": ["Échographie", "Radiofréquence", "Nerfs", "Genou"], "images": [{"src": "img/rf-nevromes-genou-cheville-1.jpg", "legende": "Test anesthésique et infiltratif échoguidé au contact du névrome : mélange, critères de positivité et information du patient", "t": 240}, {"src": "img/rf-nevromes-genou-cheville-2.jpg", "legende": "Paramètres de RF : impédance 200-300 Ω, tests sensitifs, cycle monopolaire thermique 80 °C pendant 90 s (écran du générateur)", "t": 400}, {"src": "img/rf-nevromes-genou-cheville-3.jpg", "legende": "Astuce : électrode utilisée comme thermocouple entre névrome du nerf calcanéen médial et nerf plantaire latéral (60,2 °C vs 43,5 °C)", "t": 500}, {"src": "img/rf-nevromes-genou-cheville-4.jpg", "legende": "Retour d'expérience : 18 interventions, 20 névromes post-opératoires (genoux et chevilles), délai moyen 3 ans", "t": 560}], "session": "s93"}, {"id": "myeloscanner-fuite-lcs", "horaire": "14h10", "titre": "Comment je diagnostique une fuite de LCS au myéloscanner ?", "orateur": "S. Henry (CHU Lille, service du Pr A. Cotten)", "t_start": 740, "t_end": 1630, "resume": "Chez un patient avec hypotension intracrânienne spontanée prouvée en IRM, un protocole de myéloscanner dynamique en trois acquisitions (deux décubitus latéraux déclives précoces puis un décubitus dorsal tardif) permet de rechercher en un seul examen les trois types de fuite de LCS : diverticule radiculaire rompu, brèche ventrale par ostéophyte/calcification discale et fistule durale-veineuse.", "chiffres": [{"val": "≈ 80 %", "label": "des fuites dues à une épine osseuse / calcification discale érodant le sac dural"}, {"val": "5-6 mL", "label": "de produit de contraste iodé 300 par injection (10 mL maximum au total)"}, {"val": "3", "label": "spirales de la charnière occipito-cervicale au sacrum"}], "points_cles": ["Indication : céphalées orthostatiques type syndrome post-PL sans ponction lombaire ni geste rachidien (spontanées ou post-traumatiques), adressées surtout par les neurologues.", "Prérequis : IRM cérébrale montrant des signes d'hypotension intracrânienne (pachyméningite, collections sous-durales bilatérales) puis IRM du rachis entier pour rechercher une collection épidurale de LCS.", "Classification de Schievink (2016) : 1) rupture d'un diverticule radiculaire, 2) brèche ventrale par ostéophyte ou calcification discale (la plus fréquente), 3) fistule durale-veineuse (sans collection, céphalées plutôt après orthostatisme prolongé, la plus difficile à voir).", "Les acquisitions précoces en décubitus latéral sont les seules qui détectent les fistules durales-veineuses (concentration maximale de produit de contraste dans les diverticules et foramens).", "L'acquisition tardive montre le passage du contraste dans la collection ; la cinétique de densité entre temps précoce et tardif aide à localiser le point de fuite.", "Lecture : suivre le gradient de densité dans la collection jusqu'au maximum (diverticule ou épine discale calcifiée), rechercher de petites veines épidurales/foraminales opacifiées en fenêtre serrée pour les fistules.", "Si aucune fuite visible et pas de collection : acquisition sur les reins à 30 min ; contraste rénal = très haute probabilité de fistule non vue, compléter par myélographie dynamique en salle vasculaire (soustraction).", "Collection visible mais non opacifiée : faire marcher le patient autour du brancard jusqu'à réapparition des céphalées puis réacquérir.", "Fuites surtout au rachis thoracique mais possibles sur toute la hauteur (y compris kystes de Tarlov) ; l'IRM seule s'est souvent trompée sur le point de fuite exact."], "technique": ["Patient hospitalisé (reste allongé après l'examen).", "Décubitus latéral au scanner avec billot sous le bassin pour créer une déclivité céphalique, vérifiée sur le topogramme.", "Ponction lombaire strictement médiane (ligament interépineux) ; retrait éventuel de quelques gouttes (souvent peu de reflux en hypotension) ; biseau orienté vers la tête.", "Injection de 5 à 6 mL de produit le plus concentré autorisé en intrathécal (iopamidol 300 / ioméprol 300 / iohexol 300).", "Spirale caudo-crâniale lancée immédiatement après l'injection (manipulateur prêt, aiguille laissée en place et rebouchée), vitesse de rotation/pitch réduits pour suivre la progression ; si le contraste stagne en thoracique, relancer une spirale plus haut.", "Retournement du patient (via le ventre) sur l'autre côté, toujours avec le billot, nouveau topogramme puis réinjection de 5 à 6 mL et 2e spirale précoce (opacification des diverticules controlatéraux).", "Retrait de l'aiguille, manœuvres de Trendelenburg / rotations du corps sur lui-même, puis 3e spirale tardive en décubitus dorsal."], "alertes": [{"type": "warning", "texte": "Pas de produit de contraste à concentration supérieure à 300 en intrathécal (hors AMM) ; volume total limité à 10 mL ; examen irradiant (3 spirales occiput-sacrum)."}, {"type": "important", "texte": "Les fistules durales-veineuses ne se voient que sur les acquisitions précoces : la coordination opérateur-manipulateur pour lancer la spirale dès l'injection est déterminante."}, {"type": "tip", "texte": "Ne poser l'indication que si l'IRM cérébrale montre des signes d'hypotension intracrânienne : le myéloscanner reste un geste invasif."}], "cochin": "Protocole transposable à un service MSK disposant d'un scanner : il nécessite une hospitalisation, une IRM cérébrale et rachidienne préalable et une étroite collaboration avec les neurologues.", "tags": ["Scanner", "Rachis", "Études"], "images": [{"src": "img/myeloscanner-fuite-lcs-1.jpg", "legende": "Les trois types de fuite de LCS (classification de Schievink 2016) : diverticule, brèche ventrale, fistule durale-veineuse", "t": 880}, {"src": "img/myeloscanner-fuite-lcs-2.jpg", "legende": "Installation en décubitus latéral avec surélévation du bassin, ponction lombaire et produit de contraste (300, 5 à 6 mL)", "t": 1000}, {"src": "img/myeloscanner-fuite-lcs-3.jpg", "legende": "Myéloscanner : fuite à partir d'un diverticule radiculaire, avec contraste suivi en coupes sagittale et axiale", "t": 1320}, {"src": "img/myeloscanner-fuite-lcs-4.jpg", "legende": "Absence de fuite visible : contraste dans les cavités rénales à 30 min, en faveur d'une fistule durale-veineuse", "t": 1400}], "session": "s93"}, {"id": "ablation-nerf-basivertebral", "horaire": "14h20", "titre": "Comment je fais une ablation du nerf basivertébral ?", "orateur": "A. Kastler (CHU Grenoble)", "t_start": 1630, "t_end": 2690, "resume": "La douleur vertébrogénique, transmise par le nerf basivertébral, est proche cliniquement de la douleur discogénique et correspond surtout au Modic 1. À Grenoble, l'ablation du nerf basivertébral (BVNA) est réalisée depuis 5 ans sous scanner, sous sédation, avec du matériel de thermoablation osseuse standard (RF bipolaire ou cryoablation). Le système dédié (Intracept) n'est donc pas nécessaire : les radiologues ont déjà tous les outils.", "chiffres": [{"val": "225", "label": "patients randomisés (147 traités / 78 sham) dans l'étude SMART 2018"}, {"val": "65 %", "label": "des patients SMART douloureux depuis plus de 5 ans"}, {"val": "60 %", "label": "de Modic 2 dans SMART, sans différence d'efficacité Modic 1/2"}, {"val": "10 mm / 7 min 30", "label": "ablation OsteoCool recommandée"}, {"val": "15-20 mm", "label": "taille minimale du glaçon en cryoablation"}, {"val": "≈ 1 000 €", "label": "par aiguille de thermoablation (usage unique), souvent 2 par patient"}], "points_cles": ["Physiopathologie : la dégénérescence discale inflammatoire entraîne une densification des nocicepteurs des plateaux et une néo-vascularisation/néo-innervation transitant par le nerf basivertébral (70 % de l'innervation intracorporéale), qui rejoint le nerf sinuvertébral.", "Douleur vertébrogénique vs discogénique : pas de vraie différence clinique, si ce n'est le caractère inflammatoire (raideur matinale, douleur nocturne) ; aspect IRM Modic 1 (± 2).", "SMART 2018 (Relievant, rachetée par Boston Scientific en 2023) : essai multicentrique en double aveugle contre sham, bons résultats à 2 ans ; commercialisation d'Intracept annoncée en Europe en 2025.", "Indications à Grenoble : Modic 1 (Modic 2 seulement si transformation d'un Modic 1 connu), après échec d'infiltrations intradiscales (jusqu'à 2 ou 3 selon la réponse) ou contre-indication à l'intradiscal ; lombaire exclusivement (jusqu'à T12-L1), ni thoracique ni cervical.", "Cibles privilégiées : patients multi-étagés, non opérables, sans autre alternative ; geste positionné avant l'arthrodèse.", "Résultats meilleurs quand le nerf est bien ciblé (centrage latéral et sagittal, la veine basivertébrale aide au repérage en IRM) ; moins bons en L5-S1 (ailes iliaques) : abord trans-sacro-iliaque désormais.", "Les ablations de 7 mm étaient un facteur d'échec : passage à 10 mm ou plus.", "Neurolyse sèche type branche médiale/genou peu efficace (1 ou 2 cas) ; générateur Multigen 20 G jugé insuffisant (impédance), préférer un système osseux robuste.", "OsteoCool : les deux sondes « bipolaires » fonctionnent indépendamment (pas de bipolarité croisée) ; deux aiguilles bien placées suffisent, plus serait agressif pour le corps vertébral.", "Pas de cimentation associée : la BVNA reste un traitement intermédiaire qui préserve l'option chirurgicale ; pas de cotation spécifique (cotation de type ostéome ostéoïde)."], "technique": ["Hospitalisation ambulatoire, sous sédation (anesthésie locale possible mais douloureuse, surtout chez le sujet jeune à l'os dur).", "Guidage scanner, ou double guidage scanner + scopie, ou CBCT.", "Abord transpédiculaire très latéral (angulé) pour atteindre la portion postérieure et centrale du corps vertébral, au niveau du nerf basivertébral, sur les vertèbres sus- et sous-jacentes au disque (plateau supérieur et inférieur).", "Trocart 11 G (préféré au 13 G pour le torque) ; création d'un tunnel au biopsieur ou à l'extenseur pour un diamètre adapté à l'électrode.", "RF bipolaire OsteoCool : tip 10 mm, 7 min 30 (arrêt possible dès 70 °C) ; ou cryoablation avec glaçon d'au moins 15-20 mm, en connaissant la cinétique de glace propre à chaque aiguille.", "Levée de la sédation pendant l'ablation : douleur lombaire tolérée, mais douleur irradiant dans la jambe = chauffe radiculaire, donc repositionner.", "L5-S1 : abord trans-sacro-iliaque.", "Suivi clinique à 1, 3 et 6 mois ; IRM de contrôle à 1 mois."], "alertes": [{"type": "warning", "texte": "Risque radiculaire thermique : réveiller le patient pendant l'ablation et repositionner l'aiguille en cas de douleur irradiant au membre inférieur."}, {"type": "important", "texte": "Risque de fracture vertébrale dans le mois suivant (non rapporté dans les études, mais décrit par les gros centres), surtout chez le sujet âgé ostéoporotique : prévenir le patient et limiter les contraintes pendant 1 mois."}, {"type": "tip", "texte": "En L5-S1, l'abord trans-sacro-iliaque améliore le centrage, gêné par les ailes iliaques."}], "cochin": "Réalisable avec les outils de thermoablation osseuse et de cryoablation déjà disponibles en RI ostéo-articulaire, chez des Modic 1 lombaires réfractaires à l'infiltration intradiscale, en particulier en cas d'atteinte multi-étagée non chirurgicale.", "tags": ["Rachis", "Radiofréquence", "Scanner", "Études"], "images": [{"src": "img/ablation-nerf-basivertebral-1.jpg", "legende": "Étude SMART 2018 : douleur depuis plus de 5 ans chez 65 %, Modic 2 chez 60 %, sans différence d'efficacité entre Modic 1 et 2", "t": 1840}, {"src": "img/ablation-nerf-basivertebral-2.jpg", "legende": "Technique : sédation, guidage scanner/scopie/CBCT, RF osseuse (OsteoCool, StarMed) ou cryoablation, hospitalisation ambulatoire", "t": 2000}, {"src": "img/ablation-nerf-basivertebral-3.jpg", "legende": "Abord transpédiculaire latéral vers la portion postérieure centrale du corps vertébral sous double guidage, électrodes en place", "t": 2080}, {"src": "img/ablation-nerf-basivertebral-4.jpg", "legende": "Tips and tricks : taille et durée d'ablation (OsteoCool 10 mm 7 min 30 ; cryo 15-20 mm minimum)", "t": 2300}], "session": "s93"}, {"id": "cimentoplastie-arthrodeses", "horaire": "14h30", "titre": "Comment je fais une cimentoplastie autour des arthrodèses chirurgicales ?", "orateur": "C. Journe (radiologue libéral, Lyon)", "t_start": 2690, "t_end": 3700, "resume": "Chez des patients souvent ostéoporotiques et déjà arthrodésés plusieurs fois, la cimentation percutanée autour des vis pédiculaires ou sacrées mobiles est une alternative à la reprise chirurgicale. Le geste est techniquement difficile (abord tangent aux vis, ciment très visqueux) mais sûr. L'efficacité tient à la recréation d'un point de fixation vis-os spongieux plus qu'à un beau remplissage des cavités.", "chiffres": [{"val": "24 patients / 38 vis", "label": "série préliminaire sur les 2 dernières années"}, {"val": "70 %", "label": "d'amélioration de la douleur"}, {"val": "10 %", "label": "de reprise chirurgicale (échec)"}, {"val": "20 %", "label": "de décompensation à un autre étage"}, {"val": "0", "label": "complication"}, {"val": "× 2", "label": "temps moyen par rapport à une vertébroplastie simple"}], "points_cles": ["Indication principale : vis mobiles (cavités de mobilité au scanner, hyperfixation scintigraphique) aux extrémités d'une arthrodèse chez un patient ostéoporotique, après au moins deux chirurgies, plutôt que révision chirurgicale.", "Bibliographie : Hoppe & Keel 2017 (augmentation de vis : 2 à 3 cc de ciment, force d'arrachement × 1,5 à 2, descellement 4 % vs 63 %) ; Chiu 2023 (sacroplastie pour descellement de vis sacrée, n = 18 : EVA 5,6 → 1,7, ODI 51,8 → 25,6) ; méta-analyse d'environ 800 patients (12 études) avec amélioration significative.", "Série : âge moyen 65,7 ans (plus jeune que la vertébroplastie classique), prédominance féminine, majorité avec deux arthrodèses préalables, en libéral sous anesthésie locale seule.", "Cimenter les vis « redonne un tour de tournevis » et bloque tout : les contraintes se reportent sur l'étage sus-jacent (décompensation de la cyphose thoracique 3 mois après chez une patiente de 73 ans ostéopéniques), donc anticiper et revoir les patients.", "L'étage S1 répond particulièrement bien (cas d'une femme de 71 ans, 3 arthrodèses, vis sacro-iliaques mobiles : 1 an d'excellente évolution puis décompensation haute).", "Le facteur pronostique le plus net : toucher la vis (le patient éveillé le ressent et a la sensation d'un verrouillage lors du passage du ciment), même sans diffusion dans la cavité.", "Patients peu inflammatoires au moment du geste dans son expérience (scintigraphie plutôt éteinte) ; un intervenant a souligné l'intérêt d'une cartographie scintigraphique pour cibler les zones en résorption.", "Prise en charge en hôpital de jour (environ 10 h) ; suivi au long cours indispensable (« revoir tes patients »)."], "technique": ["Bilan : scanner (cavités de mobilité, position des vis dans le pédicule), scintigraphie, EOS debout ; décision conjointe avec le chirurgien.", "Anesthésie locale (sans anesthésiste dans son centre), double guidage scanner/scopie.", "Trajet tangent à la vis dans les deux plans (axial et sagittal), au contact de la corticale du pédicule voire sans pédicule, par le haut ou par le bas ; ne jamais être parallèle à la vis.", "Étages bas : partir le plus bas possible et remonter vers les vis sous scopie ; abord trans-iliaque possible pour atteindre S1.", "Toucher la vis avec le trocart avant l'injection.", "Ciment très visqueux, attendre plus longtemps qu'en vertébroplastie standard avant d'injecter, au contact de la vis et du spongieux adjacent, voire dans la cavité."], "alertes": [{"type": "warning", "texte": "Fuites fréquentes : le ciment peut remonter le long de la vis jusqu'à la tête et l'articulaire postérieure, ce qui peut gêner une future ablation du matériel par le chirurgien."}, {"type": "warning", "texte": "Risques vasculaires et neurologiques liés aux abords acrobatiques des pédicules fins ou déjà occupés par le matériel ; prévenir le patient du risque de radiculalgie lorsque la vis est basse dans le pédicule."}, {"type": "important", "texte": "Le blocage de l'étage cimenté peut décompenser l'étage adjacent (20 % dans la série) : informer le patient et le chirurgien, et assurer un suivi rapproché."}], "cochin": "Option à discuter avec les chirurgiens du rachis pour les descellements de vis chez les patients ostéoporotiques multi-opérés, en sachant que la courbe d'apprentissage est longue et le temps de salle doublé.", "tags": ["Cimentoplastie", "Rachis", "Scanner", "Scopie"], "images": [{"src": "img/cimentoplastie-arthrodeses-1.jpg", "legende": "Bibliographie : augmentation de vis pédiculaires (Hoppe & Keel 2017) et sacroplastie pour descellement de vis sacrée (Chiu 2023)", "t": 2840}, {"src": "img/cimentoplastie-arthrodeses-2.jpg", "legende": "Principe de l'abord tangentiel aux vis pédiculaires sous scopie", "t": 3140}, {"src": "img/cimentoplastie-arthrodeses-3.jpg", "legende": "Cas 3 : femme de 71 ans, 3 arthrodèses, cimentation au contact des vis sacrées par voie basse", "t": 3220}, {"src": "img/cimentoplastie-arthrodeses-4.jpg", "legende": "Série préliminaire : 24 patients, 38 vis ; amélioration 70 %, reprise 10 %, décompensation 20 %, aucune complication", "t": 3340}], "session": "s93"}, {"id": "vissage-transfacettaire-post-laminectomie", "horaire": "14h40", "titre": "Comment je fais un vissage transfacettaire post-laminectomie pour éviter la chirurgie ?", "orateur": "K. Desalos pour N. Amoretti (CHU Nice, Pasteur 2)", "t_start": 3700, "t_end": 4240, "resume": "Le vissage transfacettaire percutané sous anesthésie locale, en double guidage scanner et scopie, stabilise l'instabilité segmentaire après laminectomie ou le syndrome du segment adjacent après arthrodèse. Dans une série prospective niçoise de 52 patients âgés, il réduit durablement la douleur d'environ 3 points et évite la reprise chirurgicale sous anesthésie générale.", "chiffres": [{"val": "52", "label": "patients inclus (février 2017 à août 2025)"}, {"val": "77 ans", "label": "âge médian (41-93)"}, {"val": "−3/10", "label": "baisse moyenne de l'EVA, maintenue à 6 mois et 1 an"}, {"val": "2 points", "label": "d'amélioration médiane de la qualité de vie (EQ-5D/ODI)"}, {"val": "49 min", "label": "durée médiane d'intervention"}, {"val": "603 mGy.cm", "label": "PDL par intervention"}], "points_cles": ["Épidémiologie : instabilité segmentaire post-laminectomie 5 à 20 % ; syndrome du segment adjacent symptomatique 5 à 18 % à 10 ans.", "Facteurs de risque : âge, étendue de la laminectomie, délai depuis la chirurgie, arthrose, discopathies, obésité, ostéoporose, amyotrophie.", "Traitement de référence : reprise chirurgicale par arthrodèse transpédiculaire (PLIF) sous anesthésie générale ; alternative mini-invasive sous anesthésie locale.", "Base biomécanique : la fixation transfacettaire ou translaminofacettaire par deux vis donne une stabilité comparable à la fixation transpédiculaire (études cadavériques).", "Critères d'inclusion : instabilité segmentaire après laminectomie ou syndrome du segment adjacent avec critères d'instabilité en imagerie (spondylolisthésis, discopathie inflammatoire Modic, instabilité/diastasis facettaire).", "Population : 1 étage chez 47 patients, 2 étages chez 5 ; spondylolisthésis au niveau traité 18/52 ; niveaux surtout L4-L5 (24) et L5-S1 (18), puis L3-L4 (11), L2-L3 (3), L1-L2 (1).", "Suivi : EVA et EQ-5D/ODI avant, à 6 mois (EVA de 44 patients) et à 1 an (EVA de 34 patients) ; nombreux perdus de vue (patients âgés).", "Réduction immédiate du diastasis facettaire après vissage, signe de stabilisation.", "Gain de qualité de vie modeste, en partie lié à la polypathologie et à la sénescence de cette population.", "Pas d'effet indésirable ; vis mal positionnées facilement retirées et repositionnées sous anesthésie locale ; évite hospitalisation conventionnelle et anesthésie générale."], "technique": ["Hélice scanner de repérage, repère cutané et planification de la balistique.", "Point d'entrée : base de la facette articulaire supérieure (sus-jacente) ; trajet légèrement caudal et latéral pour traverser la facette puis le pédicule de la vertèbre sous-jacente en évitant les structures nerveuses.", "Terminaison optimale : au moins dans le tiers postérieur du pédicule homolatéral de la vertèbre sous-jacente.", "Technique de Seldinger : aiguille de PL au contact de la facette, anesthésie du périoste, trocart 13 G monté sur l'aiguille pour perforer et transfixer la facette.", "Échange sur broche de Kirschner, mesure de la longueur de vis, puis vissage sur la broche sous contrôle scopique continu.", "Simple pansement cutané ; geste programmable de moins d'une heure."], "alertes": [{"type": "warning", "texte": "Trajet à orienter pour éviter les structures nerveuses (racines, canal) dans un rachis déjà opéré et laminectomisé : double guidage scanner/scopie indispensable."}, {"type": "tip", "texte": "En cas de malposition, la vis se retire et se replace facilement sous anesthésie locale."}], "cochin": "Alternative à discuter en RCP rachis pour les patients âgés récusés de l'anesthésie générale, avec instabilité post-laminectomie ou syndrome du segment adjacent, si l'on dispose du matériel de vissage percutané.", "tags": ["Vissage", "Rachis", "Scanner", "Scopie"], "images": [{"src": "img/vissage-transfacettaire-post-laminectomie-1.jpg", "legende": "Épidémiologie : instabilité post-laminectomie 5 à 20 %, syndrome du segment adjacent 5 à 18 % à 10 ans, facteurs de risque", "t": 3760}, {"src": "img/vissage-transfacettaire-post-laminectomie-2.jpg", "legende": "Population : âge médian 77 ans, niveaux traités, PDL 603 mGy.cm, durée 49 min", "t": 3940}, {"src": "img/vissage-transfacettaire-post-laminectomie-3.jpg", "legende": "Trajet idéal d'une vis transfacettaire L3-L4 : point d'entrée, direction et terminaison dans le pédicule sous-jacent", "t": 4000}, {"src": "img/vissage-transfacettaire-post-laminectomie-4.jpg", "legende": "Discussion : EVA −3/10, qualité de vie +2 points, pas d'effet indésirable, chirurgie et AG évitées", "t": 4160}], "session": "s93"}, {"id": "bousson-scanner-ri", "horaire": "14h50", "titre": "Auto-battle : quel scanner pour l'imagerie interventionnelle ostéo-articulaire ? Scanner simple, couplage avec la scopie, scanner spectral", "orateur": "V. Bousson (Lariboisière, AP-HP Nord – Université Paris Cité)", "t_start": 0, "t_end": 925, "resume": "Revue des modalités de guidage scanographique en RI ostéo-articulaire : scanner simple pour les gestes courts dans le plan axial, scanner + arceau de scopie pour les gestes dynamiques (herniectomie, vertébroplastie, vissage), navigation électromagnétique (Imactis) pour les trajets complexes et multi-aiguilles, et scanner spectral / à comptage photonique pour la résolution, la caractérisation tissulaire et la réduction des artefacts métalliques. Conclusion : « chacun fait ce qui lui plaît », selon le geste et l'équipement disponible.", "chiffres": [{"val": "0,2 mm", "label": "épaisseur de coupe possible en scanner à comptage photonique (PCCT)"}, {"val": "20 vs 27", "label": "cimentoplasties PCCT vs scanner Siemens Definition Edge (étude de dose, recueil avril–juillet 2025)"}, {"val": "165 vs 138 mGy", "label": "IDSV total cimentoplastie PCCT vs Edge (PDL 2383 vs 1883 mGy.cm), phase de prise en main"}, {"val": "55 vs 65 mGy", "label": "IDSV total biopsie osseuse PCCT (n=26) vs Edge (n=21)"}, {"val": "45 vs 46 mGy", "label": "IDSV total ostéome ostéoïde PCCT (n=8, 5 acquisitions) vs Edge (n=11, 10 acquisitions)"}, {"val": "1982", "label": "première résection d'ostéome ostéoïde sous guidage TDM"}], "points_cles": ["Exigences du guidage en RI : précision idéalement temps réel, visualisation de la cible et des structures nobles, contrôle de la position des instruments, maîtrise de l'irradiation patient et opérateur.", "Scanner simple : disponibilité universelle ; modes hélicoïdal, séquentiel pulsé ou fluoroscopie basse dose à la pédale. Les modes fluoroscopiques/pulsés sont nettement moins irradiants que les acquisitions volumiques, même répétés : acquisitions volumiques pour le repérage et le contrôle final, modes séquentiels/fluoroscopiques en phase intermédiaire.", "Indications du scanner simple : biopsies os/tissus mous, infiltrations, fenestration de kystes, destruction thermique (ex. laser d'ostéome ostéoïde) : trajets courts, plan axial ou peu oblique, peu de repositionnements.", "Scanner + amplificateur de brillance (arceau mobile dans la salle, souvent laissé en profil) : planification TDM + guidage dynamique scopique ; indications : herniectomie percutanée, vertébroplastie, vertébroplastie + vis, analyse de vascularisation. Limites : manipulation de l'équipement, encombrement.", "Navigation électromagnétique (système Imactis) : station à écran tactile, générateur de champ posé près du point de ponction et inclus dans le volume d'acquisition, porte-aiguille avec détecteur ; trajectoire affichée en temps réel sur 2 plans perpendiculaires. Plus rapide et plus exacte dans la littérature, mais pas forcément moins irradiante (champ d'acquisition élargi).", "Indications Imactis : trajets complexes hors plan axial et/ou multiples aiguilles (C1 sur myélome en décubitus ventral, acétabulum postérieur/branche ischio-pubienne, fracture adjacente à une ostéosynthèse, ostéome ostéoïde au contact de la racine L5 foraminale avec hydrodissection au CO2, vissage + cimentoplastie sacrée avec 5–6 aiguilles en voies longitudinales ascendantes).", "Scanner spectral (double énergie ou comptage photonique) : meilleure résolution spatiale et en contraste, baisse de dose potentielle, réduction des artefacts métalliques (trocart masquant la cible, utile aux extrémités).", "Exemples PCCT : visualisation du nerf radial avant thermoablation d'un ostéome ostéoïde huméral ; visualisation du glaçon en cryothérapie des tissus mous ; repérage prébiopsique d'une métastase non lytique (soustraction du calcium, cartographie médullaire) ; cartographie de composition tissulaire d'un kyste anévrismal traité par dénosumab pour anticiper la diffusion d'un sclérosant ou du ciment.", "Étude de dose locale (PCCT vs Definition Edge) : pas de réduction de dose démontrée pendant la phase de prise en main par les manipulateurs.", "Discussion : le suivi per-procédure de la nécrose (thermoablation) est un potentiel majeur, mais les post-traitements spectraux sont trop complexes à réaliser en temps réel ; pas encore de protocole idéal dans l'os (« work in progress »)."], "technique": ["Scanner simple : acquisition volumique de repérage → progression de l'aiguille en mode séquentiel pulsé ou fluoroscopie basse dose (pédale) → acquisition volumique de contrôle final.", "Scanner + scopie : planification et contrôle TDM, arceau en profil pour suivre en dynamique la progression (herniatome, trocart, vis, ciment).", "Imactis : poser le générateur de champ près du point de ponction, l'inclure dans l'acquisition TDM, planifier la trajectoire, suivre l'aiguille montée sur le porte-aiguille détecteur en temps réel sur 2 plans perpendiculaires."], "alertes": [{"type": "tip", "texte": "Les modes fluoroscopiques pulsés sont moins irradiants que les volumiques même répétés : réserver le volumique au repérage et au contrôle final."}, {"type": "warning", "texte": "La navigation électromagnétique n'abaisse pas forcément la dose : le générateur doit être inclus dans le champ d'acquisition, ce qui l'élargit."}, {"type": "important", "texte": "Le gain dosimétrique du comptage photonique n'est pas automatique : nécessite une courbe d'apprentissage et des manipulateurs formés."}], "cochin": "Choisir la modalité selon le geste : scanner simple pour biopsies/infiltrations/ablations à trajet axial court, couplage scopie pour herniectomie et cimentoplastie-vissage, navigation électromagnétique pour les abords obliques multi-aiguilles (bassin, sacrum, rachis cervical haut).", "tags": ["Scanner", "Scopie", "Organisation", "Radiofréquence"], "images": [{"src": "img/bousson-scanner-ri-1.jpg", "legende": "Synthèse : choix du mode de scanner selon le geste (scanner simple, CT + arceau, guidage électromagnétique, DECT/PCCT)", "t": 900}, {"src": "img/bousson-scanner-ri-2.jpg", "legende": "Navigation électromagnétique Imactis : station, générateur de champ, porte-aiguille détecteur", "t": 300}, {"src": "img/bousson-scanner-ri-3.jpg", "legende": "Ostéome ostéoïde de l'humérus proximal en PCCT : visualisation du nerf radial avant thermoablation", "t": 660}, {"src": "img/bousson-scanner-ri-4.jpg", "legende": "Étude de dose PCCT vs Definition Edge (cimentoplastie, biopsie osseuse, ostéome ostéoïde)", "t": 820}], "session": "s94"}, {"id": "thouvenin-sacroplastie-simple", "horaire": "15h05", "titre": "Pourquoi je fais une sacroplastie simple sur un bassin ostéoporotique ?", "orateur": "Y. Thouvenin (CHU de Montpellier)", "t_start": 950, "t_end": 1525, "resume": "La fracture ostéoporotique du sacrum est sous-diagnostiquée (clinique peu spécifique, radiographies insensibles) ; l'IRM (≈100 % de sensibilité) et le scanner en fenêtre parties molles font le diagnostic. La sacroplastie simple (PMMA en zone 1 de Denis, sous scanner et anesthésie locale) apporte une antalgie immédiate et durable avec très peu de complications et convient à la majorité des patients ; le message principal est d'orienter vers une prise en charge de l'ostéoporose.", "chiffres": [{"val": "≈100 %", "label": "sensibilité de l'IRM pour la fracture sacrée"}, {"val": "64–89 %", "label": "risque de perte d'autonomie après fracture (diapo)"}, {"val": "13–27 %", "label": "mortalité (diapo)"}, {"val": "≈20 %", "label": "prise en charge satisfaisante de l'ostéoporose au décours"}, {"val": "0,3 %", "label": "complications majeures de la sacroplastie (littérature)"}, {"val": "2,2–3,3 %", "label": "fuites de ciment (le plus souvent sans conséquence)"}, {"val": "jusqu'à 10 ans", "label": "durabilité de l'antalgie rapportée"}], "points_cles": ["Terrain : femmes âgées surtout (hommes en hausse), incidence croissante depuis 30 ans ; diagnostic souvent tardif ; évaluation du risque de chute faite dans moins de la moitié des cas.", "Présentation simple : sujet âgé, douleur fessière mécanique récente et invalidante, traumatisme ou ostéoporose connue. Plus difficile : douleurs peu invalidantes, tableau de lombalgie/sciatique, douleur de hanche ou pubalgie, absence de traumatisme, fracture vertébrale au premier plan.", "Traits : longitudinaux dans l'aileron (uni- ou bilatéraux) ± refend horizontal = fracture en H, la plus fréquente.", "Imagerie : radiographies peu sensibles (à éviter en 1re intention) ; IRM de référence (≈100 %) ; scintigraphie si contre-indication à l'IRM. Au scanner : traquer le décroché cortical et l'infiltration des parties molles présacrées ; analyser en filtre/fenêtre parties molles car l'aileron du sujet âgé est physiologiquement graisseux.", "Réflexe sur imagerie non dédiée : regarder le haut du sacrum sur le scanner lombaire ; sur l'IRM lombaire, chercher l'œdème sur les coupes sagittales les plus latérales (intérêt du « de Sèze magnétique » / STIR coronal).", "Indications de sacroplastie : douleur très invalidante, mauvaise tolérance ou résistance au traitement médical, risque de syndrome de glissement et de complications de décubitus ; proposée très largement.", "Abords : grand axe longitudinal dans l'aileron ou petit axe parallèle au disque L5-S1 (efficacité et fuites similaires) ; voie médiane pour le trait horizontal peu utile ; axial strict = voie royale en scanner.", "Expérience locale : reprise de la marche le jour même chez des patientes de 75 à 90 ans ; geste plus court, moins douloureux, plus simple et moins risqué qu'une vertébroplastie.", "Littérature : antalgie immédiate et durable (6–12 mois, jusqu'à 10 ans), baisse des morphiniques, meilleure mobilité, coût inférieur au traitement médical ; complications rares (fuites, radiculalgie 0,4–0,6 %) à mettre en balance avec celles du décubitus.", "Place de l'ostéosynthèse non définie dans les fractures par insuffisance (littérature surtout orthopédique, transposée de la haute énergie) : une étude sacroplastie vs ostéosynthèse est souhaitée."], "technique": ["Décubitus ventral sous scanner ; scanner de repérage et planification ; asepsie, champage.", "Anesthésie locale sous-cutanée plan par plan jusqu'au périoste ; antalgie paracétamol/morphine, MEOPA (Kalinox) au besoin.", "Trocart (biopsieur biseauté) introduit directement sans aiguille de Chiba (os superficiel et fragile : pas de marteau nécessaire).", "Anesthésie intra-osseuse : 1/3 lidocaïne + 2/3 ropivacaïne (Naropeine).", "Injection progressive de PMMA en zone 1 de Denis (latérale aux foramens) sous contrôle scanner ; abord uni- ou bilatéral selon les traits.", "Pas de suture (point minuscule) ; mobilisation précoce."], "alertes": [{"type": "warning", "texte": "Une radiographie normale n'élimine pas une fracture sacrée : demander IRM ou scanner devant une lombalgie basse/sciatalgie du sujet âgé."}, {"type": "tip", "texte": "Penser à la fracture du sacrum devant une fracture vertébrale, du cadre obturateur ou d'une transverse de L5 ostéoporotique ; lire le scanner en fenêtre parties molles."}, {"type": "important", "texte": "Rester en zone 1 de Denis (latéralement aux foramens sacrés) pour limiter le risque de fuite foraminale et de radiculalgie."}, {"type": "important", "texte": "Adresser systématiquement pour bilan et traitement de l'ostéoporose et évaluation du risque de chute."}], "cochin": "Sacroplastie sous scanner et anesthésie locale (trocart sans marteau, anesthésie intra-osseuse) faisable en hospitalisation courte chez le sujet âgé fragile ; inclure un circuit vers la filière ostéoporose.", "tags": ["Cimentoplastie", "Hanche-bassin", "Scanner", "Rachis"], "images": [{"src": "img/thouvenin-sacroplastie-simple-1.jpg", "legende": "Principes de la sacroplastie : injection de PMMA en zone 1 de Denis par trocart", "t": 1160}, {"src": "img/thouvenin-sacroplastie-simple-2.jpg", "legende": "Abords : petit axe (parallèle à L5-S1), grand axe et axial strict au scanner", "t": 1200}, {"src": "img/thouvenin-sacroplastie-simple-3.jpg", "legende": "Antalgie : paracétamol, morphine, anesthésie intra-osseuse 1/3 lidocaïne 2/3 ropivacaïne, MEOPA", "t": 1260}, {"src": "img/thouvenin-sacroplastie-simple-4.jpg", "legende": "Messages : regarder le sacrum sur les imageries lombaires, scanner en fenêtre parties molles, IRM", "t": 1480}], "session": "s94"}, {"id": "benrejeb-vissage-cimentoplastie-bassin", "horaire": "15h15", "titre": "Pourquoi je fais un vissage-cimentoplastie (ostéosynthèse renforcée) sur un bassin ostéoporotique ?", "orateur": "M. I. Ben-Rejeb (CHU Lyon Sud, HCL)", "t_start": 1535, "t_end": 2095, "resume": "Argumentaire biomécanique : le bassin subit à la fois compression (traitée par le ciment) et cisaillement (traité par les vis) ; l'ostéosynthèse renforcée (vis ilio-sacrée/trans-ilio-sacrée + PMMA, principe du béton armé) apporte stabilité, verticalisation précoce et antalgie rapide. Cohorte lyonnaise de 68 fractures par insuffisance sacrée : douleur divisée par 2 dès J1, 4,4 % de complications ; la sacroplastie seule reste réservée aux sujets fragiles récusés pour l'anesthésie générale.", "chiffres": [{"val": "68", "label": "fractures sacrées par insuffisance (FFP II) traitées par vis + ciment, cohorte bicentrique 2022–2025"}, {"val": "81 ans", "label": "âge médian"}, {"val": "IIa 31 % / IIb 56 % / IIc 13 %", "label": "classification de Rommens"}, {"val": "÷2", "label": "score de douleur (EVA) dès J1, amélioration significative du score fonctionnel (0–5)"}, {"val": "3 (4,4 %)", "label": "complications : 1 fuite de ciment (grade 1), 1 hémorragie et 1 desserrage de vis (grade 3 CIRSE)"}, {"val": "43 % + 15 %", "label": "patients en ambulatoire et hospitalisés < 3 jours"}, {"val": "15–20 min", "label": "durée d'une vis ilio-sacrée unilatérale + cimentoplastie sous CBCT"}, {"val": "jusqu'à 30 %", "label": "surmortalité dans les 10–15 ans suivant une fracture par insuffisance"}], "points_cles": ["Rappels biomécaniques : module de Young (rigidité) élevé chez l'adulte jeune, abaissé par le vieillissement et effondré dans l'ostéoporose ; l'os spongieux est plus élastique que rigide, l'os cortical plus rigide qu'élastique.", "Urgence de la prise en charge : antalgie (réduction des paliers 3/morphiniques), verticalisation précoce pour limiter le décubitus, rééducation et retour à domicile.", "Bassin = forces de compression ET de cisaillement : le PMMA répond à la compression, les vis au cisaillement ; d'où l'ostéosynthèse renforcée percutanée.", "Spécificités du sujet âgé : ancrage solide indispensable, extrémité distale de la vis dans le promontoire (zone la plus solide) ; vis à filetage long.", "Principe du béton armé : vis + ciment bloquent compression et cisaillement ; cimentoplastie indispensable et généreuse, sinon descellement de vis et douleurs ; sacroplastie complémentaire dans les ailerons.", "Descellement rattrapable : recathétérisme de la vis sur broche, nouvelle vis et cimentation.", "Cohorte : fractures des ailerons bilatérales 46 %, fractures en H 29 %, atteinte du cadre obturateur 66 % ; abord percutané sous CBCT ou CT + fluoroscopie ; 1 à 2 vis à filetage long + PMMA systématique ; critères : EVA et score de mobilité 0 (alité) à 5 (marche normale).", "Choix des vis selon le couloir : grande vis trans-ilio-sacrée (un seul trajet) si couloir favorable, sinon 2 vis ilio-sacrées bilatérales ; puis 2 trocarts 13 G par voie postérieure pour cimenter les ailerons.", "Sacroplastie simple conservée pour les fractures en H chez les patients fragiles récusés pour l'AG (faisable sous anesthésie locale, abord postérieur bilatéral simple).", "Littérature citée : étude cadavérique montrant que la sacroplastie seule ne suffit pas à la stabilité biomécanique ; vis ilio-sacrées augmentées assistées par ordinateur = alternative raisonnable à la sacroplastie ; sacroplastie à 10 ans (Frey) efficace sur la douleur."], "technique": ["Anesthésie générale de préférence (immobilité nécessaire au CBCT ; ostéosynthèse sous AL faisable mais moins confortable).", "Guidage CBCT (rapide) ou scanner + scopie ; analyse du couloir ilio-sacré.", "Vis à filetage long, pointe dans le promontoire : vis trans-ilio-sacrée unique si couloir favorable, sinon vis ilio-sacrées bilatérales.", "Cimentation PMMA de l'aileron par 2 trocarts 13 G par voie postérieure, comme une sacroplastie, et/ou augmentation au contact de la vis.", "Scanner de contrôle à 1 mois (position de vis, absence de débricolage)."], "alertes": [{"type": "warning", "texte": "Ciment insuffisant = risque de descellement de vis et de douleur : être généreux sur la cimentoplastie."}, {"type": "important", "texte": "Vérifier le couloir ilio-sacré sur l'imagerie avant de choisir vis trans-ilio-sacrée ou vis bilatérales."}, {"type": "tip", "texte": "Le CBCT impose un patient immobile : privilégier l'AG pour l'ostéosynthèse ; réserver la sacroplastie sous AL aux patients récusés."}], "cochin": "Discuter en staff l'ostéosynthèse renforcée (vis + PMMA) pour les fractures sacrées par insuffisance avec composante de cisaillement ou atteinte du cadre obturateur, et garder la sacroplastie simple sous AL pour les patients récusés pour l'AG.", "tags": ["Vissage", "Cimentoplastie", "Hanche-bassin", "Études"], "images": [{"src": "img/benrejeb-vissage-cimentoplastie-bassin-1.jpg", "legende": "Principe du « béton armé » : vis trans-ilio-sacrée + ciment, ancrage dans le promontoire", "t": 1800}, {"src": "img/benrejeb-vissage-cimentoplastie-bassin-2.jpg", "legende": "Cohorte Lyon Sud/Édouard Herriot 2022–2025 : 68 fractures FFP II traitées par vis + ciment", "t": 1840}, {"src": "img/benrejeb-vissage-cimentoplastie-bassin-3.jpg", "legende": "Durée d'hospitalisation et complications (CIRSE) de la cohorte (Peraldi et al.)", "t": 1900}, {"src": "img/benrejeb-vissage-cimentoplastie-bassin-4.jpg", "legende": "Vis trans-ilio-sacrée bi-iliaque cimentée : contrôle scanner", "t": 1960}], "session": "s94"}, {"id": "clarencon-nucleolyse-ozone", "horaire": "15h30", "titre": "Pourquoi je traite une hernie discale par ozone (nucléolyse à l'ozone) ?", "orateur": "F. Clarençon (Pitié-Salpêtrière, AP-HP)", "t_start": 2095, "t_end": 2720, "resume": "La nucléolyse à l'ozone (mélange O2/O3) oxyde les protéoglycanes du nucleus, réduit le volume et la pression intradiscale et a un effet anti-inflammatoire. Geste simple, rapide (<20 min), ambulatoire, peu coûteux, efficace dans environ 60–70 % des cas, non inférieur à la microdiscectomie dans un essai randomisé, et ne gênant pas une chirurgie ultérieure ; le risque principal est infectieux au rachis cervical (transfixion œsophagienne), prévenu par hydrodissection.", "chiffres": [{"val": "31", "label": "patients de la série Pitié 2022 (âge moyen 56 ans, 10 F / 21 H)"}, {"val": "22 % + 40,7 %", "label": "amélioration modérée + nette à 6 semaines (37 % inchangés, 11 % chirurgie)"}, {"val": "0", "label": "infection discale dans la série lombaire 2022"}, {"val": "81,8 % / 86,3 %", "label": "baisse d'EVA ≥3 points à 2 et 12 mois (série prospective marseillaise, 20 patients)"}, {"val": "75 %", "label": "réduction de surface herniaire à 2 mois (réduction moyenne 20 %)"}, {"val": "71 %", "label": "patients traités par ozone ayant évité la microdiscectomie (essai randomisé de non-infériorité, ≈25/bras)"}, {"val": "30 µg/mL", "label": "concentration d'ozone injectée"}, {"val": "≈100/an", "label": "nucléolyses à l'ozone dans le service"}], "points_cles": ["Ozone = trioxygène, oxydant très instable, obtenu en faisant passer un courant électrique dans du dioxygène ; utilisation discale depuis les années 1980.", "Mécanisme : oxydation des protéoglycanes du nucleus pulposus → déshydratation, réduction du volume et de la pression intradiscale, résorption de la hernie ; effet anti-inflammatoire et anti-nociceptif.", "Matériel : générateur relié à l'O2 mural (mélange O2/O3 95/5 %), filtre bactériologique Millipore.", "Difficulté principale : centrer l'aiguille dans le disque L5-S1 (aile iliaque, ostéophytes) ; incidence de trois-quarts pour dégager le triangle d'accès ; voie controlatérale si ostéophytes trop marqués ; une aiguille 20 G trop souple peut gêner.", "Anomalies transitionnelles : pas d'abord du côté d'une hémisacralisation de L5 (risque de transfixion radiculaire foraminale, déjà observé avec douleur intense).", "Risque infectieux cervical : infection précervicale après nucléolyse C5-C6/C6-C7 par passage trans-œsophagien ; depuis, hydrodissection systématique (≈20 mL de sérum physiologique + produit de contraste) pour refouler l'œsophage.", "Facteurs prédictifs d'efficacité (série marseillaise) : sexe masculin, lomboradiculalgie, symptômes < 1 an ; pas de corrélation avec la hauteur discale.", "Essai randomisé ozone vs microdiscectomie : non-infériorité en ITT et en per-protocole, pas d'événement indésirable, efficacité similaire sur douleurs radiculaires et lombaires.", "Limites : inefficacité dans 30–40 % des cas ; positionnement parfois douloureux ; littérature surtout monocentrique et rétrospective.", "Discussion : générateurs de fournisseurs italiens, statut réglementaire en France non clarifié ; un cas de déficit moteur radiculaire définitif rapporté par une participante après ozonothérapie (bulle de gaz péri-radiculaire au scanner) ; l'orateur n'a jamais eu de complication neurologique définitive."], "technique": ["Décubitus ventral ; anesthésie locale ± MEOPA, voire sédation consciente (disque inflammatoire, positionnement parfois douloureux).", "Guidage scopique (pratique habituelle de l'orateur) ou TDM.", "Aiguille 22 G ou 20 G (17 G en L5-S1), longueur 150 à 200 mm, voie postéro-latérale, extrémité au centre du disque.", "Injection de 5 mL d'O2/O3 (30 µg/mL) en intradiscal puis 5 mL en péri-radiculaire + 3 mL d'Hydrocortancyl ; contrôle scopique du gaz dans la partie centrale du disque.", "Au rachis cervical : hydrodissection préalable (≈20 mL sérum physiologique + contraste) pour refouler l'œsophage.", "Durée < 20 min, ambulatoire ; geste réitérable."], "alertes": [{"type": "warning", "texte": "Nucléolyse cervicale : risque d'infection précervicale par transfixion œsophagienne → hydrodissection systématique pour refouler l'œsophage."}, {"type": "warning", "texte": "Hémisacralisation de L5 : ne pas passer du côté homolatéral (racine foraminale à risque) ; dépister les anomalies transitionnelles avant le geste."}, {"type": "important", "texte": "Utiliser un filtre bactériologique sur la ligne d'ozone."}, {"type": "important", "texte": "Statut réglementaire des générateurs d'ozone en France non clarifié (fournisseurs italiens) : à vérifier avant mise en place."}], "cochin": "Option mini-invasive ambulatoire pour les hernies discales lombaires résistantes au traitement médical, avant chirurgie ; nécessite un générateur dédié et une vérification réglementaire, avec dépistage systématique des anomalies transitionnelles.", "tags": ["Rachis", "Scopie", "Infiltration", "Études"], "images": [{"src": "img/clarencon-nucleolyse-ozone-1.jpg", "legende": "Nucléolyse à l'ozone : aspects techniques (décubitus ventral, aiguille 22/20/17 G, voie postéro-latérale, centre du disque)", "t": 2280}, {"src": "img/clarencon-nucleolyse-ozone-2.jpg", "legende": "Paramètres : ozone 30 µg/mL, filtre Millipore, 5 mL intradiscal + 5 mL péri-radiculaire + 3 mL Hydrocortancyl", "t": 2360}, {"src": "img/clarencon-nucleolyse-ozone-3.jpg", "legende": "Risque infectieux des nucléolyses cervicales (transfixion œsophagienne) et hydrodissection", "t": 2460}, {"src": "img/clarencon-nucleolyse-ozone-4.jpg", "legende": "Take-home messages : simple, rapide, ambulatoire, efficacité 60–70 %, réitérable", "t": 2680}], "session": "s94"}, {"id": "theumann-herniectomie-percutanee", "horaire": "15h40", "titre": "Pourquoi je traite une hernie discale par herniectomie percutanée (mécanique) ?", "orateur": "N. Theumann (Clinique Bois-Cerf, Lausanne)", "t_start": 2720, "t_end": 3525, "resume": "L'herniectomie mécanique percutanée guidée par scanner + scopie retire uniquement la hernie (herniatome à extrémité recourbée) en épargnant le nucleus, sous anesthésie locale cutanée pure, souvent par voie transdurale. Sur 11 ans (202 patients), EVA médiane de 8 à 0 dès 24 h et maintenue à 12 mois, sans complication grave ; meilleurs résultats pour les hernies postéro-latérales et foraminales/extraforaminales que médianes, avec une courbe d'apprentissage importante.", "chiffres": [{"val": "202", "label": "patients consécutifs sur 11 ans (173 suivis jusqu'à la fin)"}, {"val": "8 → 0", "label": "EVA médiane avant → 24 h (IQR 0–2), 2 à 1 mois, 0 à 12 mois (p<0,001)"}, {"val": "57 → 9", "label": "score de Québec à 12 mois (p<0,001)"}, {"val": "87,3 % → 34,1 %", "label": "positivité du Lasègue (p<0,001)"}, {"val": "76,3 %", "label": "arrêt complet des antalgiques postopératoires"}, {"val": "53,8 %", "label": "approches transdurales"}, {"val": "5 (2,9 %)", "label": "céphalées post-ponction (transdural) traitées par blood patch"}, {"val": "80 % vs 50 %", "label": "bons résultats hernies latérales vs médianes (Amoretti, Skeletal Radiol 2013, 50 patients)"}, {"val": "87 / 93 %", "label": "étude niçoise (Ranc et al.) : 87 patients ; 93 % referaient le geste, 94 % le recommanderaient"}, {"val": "12,9 j", "label": "délai moyen de reprise du travail (50/57 actifs, étude niçoise)"}], "points_cles": ["Philosophie : faire un geste proche de la chirurgie (herniectomie) et non une nucléotomie/discectomie ; épargner le nucleus pour éviter les lombalgies secondaires (micro-instabilités focales) observées après discectomie.", "Critères d'inclusion : lombosciatique/lombocruralgie avec conflit sur IRM récente, radiculalgie > lombalgie, échec d'un traitement conservateur bien conduit incluant 1–2 infiltrations sous imagerie, EVA > 6/10, disque bien hydraté, hauteur discale préservée (Pfirrmann 1 à 3).", "Fenêtre idéale : entre le 4e et le 6e mois de sciatique (au-delà, risque de douleurs neuropathiques persistantes) ; intervention rarement nécessaire avant 8 semaines sauf hyperalgie.", "Exclusions de l'étude : sténose canalaire (Schizas ≥ B), déficit neurologique sensitif ou moteur, hernie séquestrée, discectomie antérieure au même étage. Déficit moteur → adresser directement au chirurgien.", "Herniatome : extrémité distale discrètement recourbée, la rotation retire un volume conique ; vis sans fin remontant le matériel herniaire dans un réservoir.", "Résultats par localisation (Amoretti 2013) : très efficace pour les hernies postéro-latérales et foraminales/extraforaminales, moins pour les médianes ; les chirurgiens adressent volontiers les foraminales/extraforaminales (abord délabrant).", "Étude niçoise (87 patients, 54,6 ans, EVA 8,5, ODI 44 %, L4-L5 46 %, L5-S1 43,7 %) : 96,5 % sortis le jour même ; EVA per-procédure 4,8 ; procédure tolérable pour 87,4 % ; AL jugée adaptée dans 82,8 % ; 2 céphalées sur brèche, 1 hématome épidural sans critère de sévérité.", "Contrôle IRM désormais à 3 mois (à 2 mois la rétraction du sac n'est pas toujours visible).", "Courbe d'apprentissage importante ; sélection rigoureuse des cas indispensable.", "Discussion : distinguer la douleur de mise en pression du sac herniaire (progressive, identique à la douleur habituelle) du contact radiculaire (le patient « saute sur la table »)."], "technique": ["Salle scanner + arceau de scopie (2 écrans TDM en haut, 2 écrans scopie en bas).", "Anesthésie locale cutanée seule, aucune sédation (garder le retour du patient pour ne jamais toucher le nerf).", "Introduction d'une aiguille de Chiba jusque dans la hernie sous scopie ; contrôle TDM en translatant le patient de 20 cm dans le statif ; discographie qui doit reproduire la douleur.", "Voie latéro-épidurale ou souvent transdurale (pour éviter de toucher la racine, plutôt qu'une hydrodissection).", "Section de la tête de la Chiba, mise en place coaxiale de la canule à extrémité légèrement inclinée, retrait de la Chiba, contrôle de position.", "Herniatome : curetage-aspiration en balayant toute la hernie jusqu'à disparition complète de résistance.", "Contrôle : réinjection de contraste ou réaspiration montrant le produit/gaz diffusant dans la cavité herniaire.", "Voie transdurale : 24 h d'hospitalisation, lever le lendemain ; arrêt de travail ≈10 jours, revue à 20 jours ; IRM de contrôle à 3 mois."], "alertes": [{"type": "warning", "texte": "Pas d'anesthésie épidurale ni de sédation : un contact radiculaire doit être signalé par le patient (risque de lésion du nerf)."}, {"type": "important", "texte": "Déficit moteur, sténose canalaire, hernie séquestrée ou antécédent de discectomie au même étage : hors indication, adresser au chirurgien."}, {"type": "tip", "texte": "Douleur progressive identique à la douleur habituelle = mise en pression du sac ; douleur brutale avec sursaut = contact radiculaire."}, {"type": "warning", "texte": "Voie transdurale : céphalées post-ponction (≈3 %), blood patch si besoin."}], "cochin": "Alternative mini-invasive pour les hernies foraminales/extraforaminales et postéro-latérales résistantes à 1–2 infiltrations, idéalement au 4e–6e mois ; demande salle scanner + scopie et une courbe d'apprentissage.", "tags": ["Rachis", "Scanner", "Scopie", "Études"], "images": [{"src": "img/theumann-herniectomie-percutanee-1.jpg", "legende": "Critères d'inclusion de l'herniectomie percutanée", "t": 2840}, {"src": "img/theumann-herniectomie-percutanee-2.jpg", "legende": "Section de la tête de la Chiba et introduction coaxiale de la canule", "t": 2960}, {"src": "img/theumann-herniectomie-percutanee-3.jpg", "legende": "Résultats selon la localisation de la hernie (Amoretti et al., Skeletal Radiol 2013)", "t": 3060}, {"src": "img/theumann-herniectomie-percutanee-4.jpg", "legende": "Résultats fonctionnels et sécurité de la série sur 11 ans (202 patients)", "t": 3240}], "session": "s94"}, {"id": "ranc-infiltration-cle", "horaire": "15h55", "titre": "Pourquoi et comment j'infiltre un canal lombaire étroit ?", "orateur": "P.-A. Ranc (CHU de Nice)", "t_start": 3525, "t_end": 4100, "resume": "L'infiltration épidurale interlamaire sous scanner est le traitement de première ligne interventionnel du canal lombaire étroit symptomatique : efficace à court et moyen terme (plus modeste à long terme), recommandée par l'ASIPP 2021 après 3 mois d'échec du traitement médical, avec un rapport bénéfice/risque favorable. Hydrocortancyl uniquement en épidural lombaire (dexaméthasone en foraminal) ; l'infiltration est la porte d'entrée vers d'autres options (implant interépineux).", "chiffres": [{"val": "70–80 %", "label": "efficacité jusqu'à 24 mois (Manchikanti), anesthésique seul ou + corticoïde"}, {"val": "≥3 mois", "label": "symptômes avec échec du traitement médical avant infiltration (ASIPP 2021)"}, {"val": "4/an", "label": "nombre maximal d'infiltrations recommandé"}, {"val": "0,5–1 %", "label": "brèches durales (complication mineure)"}, {"val": "<1/100 000", "label": "complications graves (infarctus médullaire surtout cervical/foraminal, abcès, discite, méningite)"}, {"val": "≈7/1 000 000", "label": "complications neurologiques (données AFSSAPS)"}, {"val": "15–20 %", "label": "passage systémique du corticoïde ; 5 mL d'Hydrocortancyl ≈ 20 mg/j de prednisone pendant 10 jours"}, {"val": "×3", "label": "événements thrombotiques jusqu'à 3 fois plus fréquents que les hématomes épiduraux après arrêt des anticoagulants"}], "points_cles": ["Rationnel : passer un cap d'inflammation radiculaire aiguë, réduire la douleur, maintenir la mobilité et l'autonomie (sujets âgés), retarder ou éviter la chirurgie.", "Méta-analyses hétérogènes (indications mélangées : CLE, hernie, facettes) : lire de façon critique ; se fier aux recommandations SFR/SIMS et ASIPP 2021.", "ASIPP 2021 : CLE confirmé par imagerie avec lombalgie + douleurs radiculaires = indication validée ; niveau de preuve modéré à fort, meilleur pour la voie interlamaire que foraminale ou hiatus sacro-coccygien ; analyse médico-économique favorable.", "Produit : Hydrocortancyl (prednisolone 2,5 %) seul à avoir l'AMM en épidural ; contre-indiqué en voie foraminale (cervicale et lombaire) et au rachis cervical ; rachis opéré = décision en RCP (HAS).", "Complications mineures : brèche durale avec céphalées résolutives, accentuation des douleurs, malaise vagal, flush, hyperglycémie transitoire, insomnie.", "Antithrombotiques : pas d'arrêt de l'aspirine ; anticoagulants au cas par cas avec le cardiologue/prescripteur ; 46 hématomes rapportés dans une revue de 160 publications ; infiltration épidurale licite en cas de sténose serrée au-dessus de L5 (diapo) ; voie foraminale possible si anticoagulation non interruptible.", "Organisation : consultation préalable (indication, contre-indications : coagulation, capacité à rester en procubitus, antécédent chirurgical ; information), repos relatif 48 h, scanner interventionnel avec asepsie et manipulateurs formés.", "Mécanisme : surtout anti-inflammatoire radiculaire, petit effet mécanique d'hydrodissection.", "Discussion : en sténose très serrée (Schizas D), injection au niveau du conflit, très lentement ; l'étage adjacent est une alternative viable ; sur 2 étages, ampoule divisée en deux.", "En cas d'échec : orienter vers d'autres options (implant interépineux, cf. N. Amoretti)."], "technique": ["Scanner de repérage, choix de l'étage du conflit, voie interlamaire ; procubitus, champ stérile.", "Matériel : Xylocaïne, aiguille de ponction lombaire 22 G, produit de contraste, Hydrocortancyl.", "Anesthésie locale ; progression interlamaire jusqu'au contact du ligament jaune ; contrôle TDM.", "Connexion de la seringue de contraste et avancée lente en maintenant une pression (perte de résistance) pour disséquer l'espace épidural sans brèche.", "Vérifier la diffusion du contraste de part et d'autre de la sténose ; injecter lentement l'Hydrocortancyl (douloureux si sténose serrée).", "Repos relatif 48 h."], "alertes": [{"type": "warning", "texte": "Hydrocortancyl contre-indiqué en voie foraminale (cervicale et lombaire) et au rachis cervical : utiliser la dexaméthasone en foraminal."}, {"type": "important", "texte": "Anticoagulants : décision au cas par cas avec le prescripteur ; le risque thrombotique de l'arrêt peut dépasser le risque d'hématome épidural ; aspirine poursuivie."}, {"type": "warning", "texte": "Rachis opéré : facteur de risque d'effets indésirables neurologiques graves, décision en RCP."}, {"type": "tip", "texte": "Injection lente en sténose serrée ; si difficulté, l'étage adjacent est une option."}], "cochin": "Infiltration épidurale interlamaire sous scanner (aiguille PL 22 G, perte de résistance au contraste, Hydrocortancyl) en première ligne du CLE après 3 mois d'échec médical, limitée à 4/an, avec protocole anticoagulants discuté au cas par cas.", "tags": ["Infiltration", "Rachis", "Scanner", "Complications"], "images": [{"src": "img/ranc-infiltration-cle-1.jpg", "legende": "Recommandations ASIPP 2021 pour l'infiltration épidurale du canal lombaire étroit", "t": 3660}, {"src": "img/ranc-infiltration-cle-2.jpg", "legende": "Complications mineures et graves des infiltrations épidurales, passage systémique", "t": 3740}, {"src": "img/ranc-infiltration-cle-3.jpg", "legende": "Gestion des traitements antithrombotiques", "t": 3800}, {"src": "img/ranc-infiltration-cle-4.jpg", "legende": "Points clés de l'infiltration épidurale du CLE", "t": 4040}], "session": "s94"}, {"id": "amoretti-implant-interepineux", "horaire": "16h05", "titre": "Pourquoi je traite en percutané les canaux lombaires étroits en radiologie interventionnelle (implant interépineux)", "orateur": "N. Amoretti (CHU de Nice)", "t_start": 4100, "t_end": 4848, "resume": "Après échec de plusieurs infiltrations, l'implant interépineux percutané par voie latérale sous scanner + scopie écarte les épineuses, met en tension le ligament jaune (ligamentotaxie) et élargit canal et foramens ; la nouvelle génération se fixe aux épineuses (arthrodèse postérieure). Indication retenue : sténose sur hypertrophie du ligament jaune, un seul étage, avec signe du caddie.", "chiffres": [{"val": "≈50 %", "label": "des CLE liés à un épaississement du ligament jaune"}, {"val": "10 / 12 / 14 mm", "label": "tailles d'implant usuelles en Europe (orateur jamais au-delà de 14 mm)"}, {"val": "1 étage", "label": "limite recommandée en RI"}, {"val": "niveau 3–4", "label": "difficulté du geste"}], "points_cles": ["Chirurgie de référence lourde : laminectomie + flavectomie avec risque d'instabilité, souvent arthrodèse postérieure associée.", "Seule indication retenue : sténose par hypertrophie du ligament jaune sur un seul étage, périmètre de marche très réduit, résistance à plusieurs infiltrations.", "Signe clé de réussite : signe du caddie (soulagement penché en avant, vélo bien toléré) = la flexion ouvre l'espace interépineux et réduit le bombement du ligament jaune.", "Principe : distraction interépineuse → tension du ligament jaune qui diminue son volume intracanalaire (effet accordéon, ligamentotaxie) et élargissement foraminal.", "Avantages vs chirurgie : abord latéral sans résection musculaire, procédure raccourcie, action ciblée sur le ligament jaune.", "Nouvelle génération (ex. Q-Fusion, Techlamed) : implants carrés répartissant les forces (moins d'érosion/fracture des épineuses ostéoporotiques que les anciens modèles ronds) et ailettes fixées dans les corticales des épineuses = ligamentotaxie + fixation postérieure.", "Résultats : élargissement canalaire (passage Schizas D → C voire B) et foraminal, réduction possible d'un antélisthésis ; FELIX trial (implant chirurgical vs décompression) sans différence à court terme ; meilleurs résultats que le traitement conservateur (Zucherman).", "Q&R : implants type « lobster » retirables en percutané ; ce modèle fixé ne l'est pas mais une ablation chirurgicale reste possible ; syndrome adjacent : pose d'un second implant ou chirurgie ; AG actuellement, neuroleptanalgésie envisagée.", "Multi-étagé techniquement faisable mais déconseillé en RI (trois abords = autant aller en chirurgie).", "Courbe d'apprentissage ; accessible aux opérateurs maîtrisant SpineJack, cyphoplastie et vissages."], "technique": ["Anesthésie générale (neuroleptanalgésie envisagée) ; procubitus ; double guidage scanner + scopie.", "Abord latéral, broche guide alignée entre les deux épineuses au plus près des articulaires postérieures (temps le plus difficile).", "Dilatation progressive de l'espace interépineux, puis canule porteuse ; mesure au « fantôme » pour choisir la taille (10, 12 ou 14 mm).", "Distraction douce et progressive pour ne pas fracturer les épineuses.", "Déploiement/expansion de l'implant au contact des épineuses, largage des ailettes de fixation dans les corticales, retrait du matériel.", "Contrôle post-procédure : distraction interépineuse, ligamentotaxie, élargissement des foramens, alignement des corps vertébraux."], "alertes": [{"type": "warning", "texte": "Distraire progressivement : risque de fracture/érosion des épineuses, surtout chez l'ostéoporotique."}, {"type": "important", "texte": "Indication stricte : hypertrophie du ligament jaune, un seul étage, signe du caddie ; l'antélisthésis n'est pas l'indication pour l'orateur."}, {"type": "tip", "texte": "Les implants fixés ne sont pas retirables en percutané (ablation chirurgicale possible)."}], "cochin": "Option à discuter en RCP rachis pour les CLE mono-étagés par hypertrophie du ligament jaune résistants aux infiltrations, chez des opérateurs déjà rodés au vissage et à la cyphoplastie.", "tags": ["Rachis", "Scanner", "Scopie", "Vissage"], "images": [{"src": "img/amoretti-implant-interepineux-1.jpg", "legende": "Principes de la distension ligamentaire (ligamentotaxie, effet accordéon)", "t": 4200}, {"src": "img/amoretti-implant-interepineux-2.jpg", "legende": "Mise en place de la broche guide et dilatation de l'espace interépineux par voie latérale", "t": 4320}, {"src": "img/amoretti-implant-interepineux-3.jpg", "legende": "Contrôle post-procédure : distraction interépineuse, élargissement foraminal, alignement", "t": 4460}, {"src": "img/amoretti-implant-interepineux-4.jpg", "legende": "Conclusion / messages à retenir", "t": 4640}], "session": "s94"}, {"id": "bmc-arthrose-femoro-patellaire", "horaire": "17h00", "titre": "Injection de concentré de moelle osseuse dans les arthroses fémoro-patellaires : quelle indication ? quels résultats ?", "orateur": "B. Dallaudière (Clinique du Sport, Bordeaux)", "t_start": 0, "t_end": 585, "resume": "Série rétrospective d'injections intra-articulaires uniques de concentré de moelle osseuse (BMC) prélevé à l'aile iliaque dans l'arthrose fémoro-patellaire isolée : amélioration fonctionnelle significative et stabilisation du volume cartilagineux en cartographie T2 à 12 mois versus témoins (Silvestre 2022), puis stabilisation des symptômes à 5 ans (Silvestre 2025). Procédure sûre, bénéfice plus marqué chez les patients initialement les plus symptomatiques ; essais randomisés nécessaires.", "chiffres": [{"val": "96 + 21", "label": "patients traités + témoins (cohorte 2022, 227 dossiers screenés)"}, {"val": "40 mL → ~10 mL", "label": "moelle aspirée (2 seringues de 20 mL) puis concentrée et réinjectée"}, {"val": "13 G", "label": "trocart de prélèvement iliaque (pointe diamant, orifices latéraux)"}, {"val": "71", "label": "patients revus à 5 ans (38 répondeurs / 33 non-répondeurs)"}, {"val": "≥ 10 pts", "label": "amélioration WOMAC à 1 an = définition du répondeur"}, {"val": "0", "label": "effet indésirable grave rapporté"}], "points_cles": ["Rationnel : le BMC contient des cellules souches mésenchymateuses, des plaquettes et des facteurs de croissance ; effet au minimum anti-inflammatoire et stabilisant, régénératif discuté.", "Population : arthrose fémoro-patellaire isolée prouvée en IRM ; exclusion des arthroses multicompartimentales, des traitements intra-articulaires antérieurs (n = 95), des lésions de l'appareil extenseur/tendon patellaire (n = 23) et des données incomplètes (n = 13).", "Évaluation : EVA, WOMAC, IKDC ; IRM à 1 an avec cartographie T2 standardisée (horaire, positionnement, température) pour le volume cartilagineux.", "À 12 mois : hausse de l'IKDC, baisse du WOMAC et de l'EVA dans le groupe BMC, scores stables chez les témoins ; groupes comparables à l'inclusion (âge, sexe, IMC, volume cartilagineux, scores).", "Cartilage : pas de véritable « repousse » en statistique, mais stabilité du volume du cartilage restant, alors que les témoins présentent la perte attendue.", "À 5 ans (injection unique) : les répondeurs, initialement plus symptomatiques, s'améliorent nettement à 1 an puis présentent une légère remontée des symptômes à 5 ans, sans revenir à l'état initial ; les non-répondeurs restent stables.", "Limites : design rétrospectif non randomisé, petit groupe témoin (21), perdus de vue à 5 ans, composition du BMC non standardisée.", "Perspectives : standardiser préparation et dosage, mieux définir les critères de sélection (phénotype d'arthrose, sévérité, âge, IMC), essais randomisés avec critères cliniques et d'imagerie (volume cartilagineux, T2 mapping).", "Autres sites de prélèvement testés par l'équipe (plateau tibial, graisse sous-cutanée) : pour débuter, privilégier l'os iliaque, la moelle rouge résiduelle étant plus abondante dans le squelette axial.", "En discussion : l'orateur juge le score Kellgren-Lawrence trop grossier pour sélectionner les patients et préconise une sélection plus précoce sur la chondropathie IRM."], "technique": ["Patient en décubitus ventral ; repérage échographique de l'épine iliaque postéro-supérieure ; anesthésie locale (MEOPA en complément).", "Trocart de 13 G à pointe diamant et orifices latéraux, orienté à environ 45° vers la face externe de l'aile iliaque pour rester à distance de l'articulation sacro-iliaque.", "Franchir la corticale, avancer légèrement puis tourner régulièrement le trocart pour orienter les orifices latéraux ; aspirer 2 seringues de 20 mL (≈ 40 mL de moelle).", "Centrifugation pour obtenir environ 10 mL de concentré (contrôle de la cellularité : plaquettes, leucocytes, cellules mononucléées).", "Réinjection intra-articulaire unique dans le genou sous échographie (ou scopie) ; point d'entrée illustré à 2,5 cm en dedans et 1,5 cm au-dessus du bord supérieur de la patella.", "Suivi clinique (EVA, WOMAC, IKDC) et IRM avec cartographie T2 à 12 mois."], "alertes": [{"type": "warning", "texte": "Prélèvement iliaque : le seul risque cité est l'articulation sacro-iliaque adjacente ; orienter le trocart vers la face externe de l'aile iliaque."}, {"type": "important", "texte": "Données rétrospectives non randomisées, groupe témoin de 21 patients, BMC non standardisé : niveau de preuve encore insuffisant."}, {"type": "tip", "texte": "Le bénéfice est plus net chez les patients très symptomatiques au départ, mais une légère remontée des symptômes est possible à 5 ans."}], "cochin": "Option envisageable dans un cadre protocolisé (recherche, registre) pour l'arthrose fémoro-patellaire isolée du sujet jeune ou actif, avec prélèvement iliaque échoguidé et injection échoguidée ; évaluation prospective conseillée (scores et cartographie T2).", "tags": ["Genou", "Infiltration", "Échographie", "Études"], "images": [{"src": "img/bmc-arthrose-femoro-patellaire-1.jpg", "legende": "Technique : kit de prélèvement et de concentration, trocart iliaque, repère d'épine iliaque postéro-supérieure et injection échoguidée du genou (point d'entrée à 2,5 cm en dedans et 1,5 cm au-dessus de la patella).", "t": 180}, {"src": "img/bmc-arthrose-femoro-patellaire-2.jpg", "legende": "Cartographie T2 du cartilage patellaire à M0 et M12 chez un homme de 39 ans : volume de cartilage sain préservé.", "t": 240}, {"src": "img/bmc-arthrose-femoro-patellaire-3.jpg", "legende": "Suivi à 5 ans : WOMAC et IKDC à l'inclusion, 1 an et 5 ans chez les répondeurs et non-répondeurs.", "t": 400}, {"src": "img/bmc-arthrose-femoro-patellaire-4.jpg", "legende": "Conclusion : bénéfice clinique à court terme, stabilisation des symptômes à 5 ans, efficacité plus marquée en cas de symptomatologie initiale sévère.", "t": 500}], "session": "s95"}, {"id": "rf-genicules-serie-80", "horaire": "17h10", "titre": "Radiofréquences percutanées pour le traitement des douleurs articulaires : mise au point à partir d'une série de 80 patients", "orateur": "M. Faruch (CHU de Toulouse)", "t_start": 585, "t_end": 1460, "resume": "Série rétrospective de 80 radiofréquences continues échoguidées de trois nerfs géniculés (63 genoux prothésés, 17 gonarthroses), en externe sous anesthésie locale : baisse significative de l'EVA jusqu'à 12 mois, cliniquement pertinente (≥ 2 points, critère IMMPACT) jusqu'à environ 6 mois, plus marquée sur genou natif. Aucune complication ; le bloc test n'est pas prédictif de la réponse et les épanchements récidivants après prothèse sont des facteurs d'échec qui orientent vers l'embolisation.", "chiffres": [{"val": "156 → 136 → 106 → 80", "label": "demandes → infiltrations tests → RF réalisées → procédures analysées (11/2021–05/2025)"}, {"val": "69,5 ans", "label": "âge moyen ; 46 F (57,5 %) / 34 H"}, {"val": "7,70 → 5,25", "label": "EVA avant RF → à 1 mois (p < 0,001), 5,96 à 6 mois (p < 0,001), 6,87 à 12 mois (p = 0,008), 7,47 à 24 mois (NS)"}, {"val": "50 % / 40,3 %", "label": "répondeurs (baisse EVA > 2) à 1 et 3 mois sur la cohorte"}, {"val": "61,5 %", "label": "répondeurs à 3 mois dans le sous-groupe gonarthrose (−3,46 points)"}, {"val": "54 %", "label": "douleur transitoire au contact périosté des canules"}, {"val": "0", "label": "complication pendant la procédure, à 1 mois et à 6 mois"}], "points_cles": ["Contexte : 20 à 30 % de douleurs chroniques après PTG, dont environ 15 % sans étiologie ; hausse de 30 % des PTG entre 2009 et 2019 ; RF et embolisation des artères géniculées ont des indications voisines mais des mécanismes différents.", "Post-PTG (n = 63) : EVA 7,75 → 5,57 à 1 mois, significatif jusqu'à 12 mois (6,73 ; p = 0,02), mais gain de l'ordre de 2 points seulement jusqu'à 6 mois puis remontée ; environ un tiers de vrais répondeurs.", "Gonarthrose (n = 17) : EVA 7,53 → 4,06 à 1 mois (p = 0,002), 5,11 à 6 mois (p = 0,03) ; meilleure réponse que sur prothèse, effectif insuffisant au-delà de 6 mois.", "Moitié de la cohorte perdue de vue à 1 an (80 à M1, 31 à M12, 15 à M24) : biais d'attrition majeur.", "Infiltration test (n = 130) : baisse EVA −2,73 à 24 h (74 % > 2 points) et −2,03 à 1 mois (44,1 %) ; corrélation avec la baisse post-RF uniquement à 1 mois (p = 0,032) ; le statut à 24 h n'est pas prédictif (p > 0,05).", "Revue systématique de l'équipe : 55 études sur 1 293 (3 281 patients) ; EVA améliorée dans deux tiers des études à 6 et 12 mois ; taux de répondeurs de 4 à 92 % selon les séries.", "Méta-analyses : Soetjahjo 2024 (11 études, 604 patients, RF pulsée et refroidie, gonarthrose) −3,4 à 1 mois, −3,0 à 3 mois, −2,4 à 6 mois ; une autre méta-analyse (8 études, 256 patients, RF échoguidée) retrouve −4 points mais seulement à 1 mois.", "Points de discussion : le guidage échographique repère le pédicule vasculo-nerveux (le nerf n'est pas toujours visible, surtout sur genou opéré) ; traiter plus de nerfs améliorerait les résultats selon certains auteurs ; la RF refroidie pénétrerait mieux le tissu cicatriciel post-PTG (pas d'expérience de l'oratrice).", "Mauvais répondeurs pressentis : épanchements ou hémarthroses récidivants après prothèse ; distinguer une douleur neuropathique (immédiatement après la PTG, sans épanchement) d'une douleur non neuropathique (apparue à distance).", "Algorithme de l'oratrice : gonarthrose → traitement médical bien conduit → infiltration test puis RF des 3 nerfs géniculés → si échec, extension à d'autres cibles ou embolisation ; après PTG avec épanchement récidivant → embolisation des artères géniculées d'emblée."], "technique": ["En externe, anesthésie locale pure, durée d'environ 30 minutes ; infiltration test systématique préalable, couplée à la consultation (explications sur la suite).", "Cibles : nerfs géniculés supéro-médial, supéro-latéral et inféro-médial, repérés à l'échographie (pédicule vasculo-nerveux).", "Anesthésie locale du trajet en amont du nerf, sans anesthésier le contact périosté ; tests sensitif et moteur au contact du périoste, puis lidocaïne injectée par la canule.", "RF continue (thermique, non pulsée) : 2 cycles de 60 secondes à 60 °C par nerf.", "Suivi : EVA à 1, 3, 6, 12 et 24 mois ; recueil des effets indésirables pendant et après la procédure."], "alertes": [{"type": "tip", "texte": "Douleur au contact du périoste chez 54 % des patients : ne pas infiltrer le contact périosté avant les tests sensitif et moteur, puis administrer la lidocaïne par la canule."}, {"type": "warning", "texte": "Un pseudo-anévrisme a été rapporté dans la littérature : le guidage échographique permet de visualiser l'artère géniculée et de l'éviter."}, {"type": "important", "texte": "Après PTG avec épanchement ou hémarthrose récidivants, la RF échoue souvent : l'oratrice propose désormais l'embolisation des artères géniculées en première intention."}, {"type": "important", "texte": "Le bloc test n'est pas prédictif de la réponse à la RF ; il reste utile pour la relation avec le patient douloureux chronique."}], "cochin": "Protocole simple et reproductible en ambulatoire (3 nerfs, 2 × 60 s à 60 °C, échoguidage), à réserver aux gonarthroses après échec d'un traitement médical vérifié ; dépister l'épanchement récidivant post-PTG avant d'indiquer une RF et discuter alors l'embolisation.", "tags": ["Genou", "Radiofréquence", "Nerfs", "Échographie"], "images": [{"src": "img/rf-genicules-serie-80-1.jpg", "legende": "Procédure : en externe sous anesthésie locale, nerfs supéro-médial, supéro-latéral et inféro-médial échoguidés, RF continue 2 cycles de 60 °C pendant 60 s, environ 30 min.", "t": 720}, {"src": "img/rf-genicules-serie-80-2.jpg", "legende": "Résultats sur la cohorte (n = 80) : EVA de 7,70 avant RF à 5,25 à 1 mois, significativement plus basse jusqu'à 12 mois, non significative à 24 mois.", "t": 820}, {"src": "img/rf-genicules-serie-80-3.jpg", "legende": "Différence minimale cliniquement importante (IMMPACT) : pourcentage de patients avec une baisse d'EVA > 2 points sur la cohorte, après PTG et dans la gonarthrose.", "t": 920}, {"src": "img/rf-genicules-serie-80-4.jpg", "legende": "Infiltrations tests : baisse d'EVA à 24 h et à 1 mois ; pas de valeur prédictive du statut à 24 h sur la réponse à la RF.", "t": 1000}], "session": "s95"}, {"id": "embolisation-tennis-elbow", "horaire": "17h30", "titre": "Embolisation du tennis elbow : quelles indications, quels résultats ?", "orateur": "M. Sapoval (HEGP, AP-HP, Paris)", "t_start": 1460, "t_end": 2140, "resume": "Présentée en premier dans la vidéo. L'épicondylite latérale rebelle s'accompagne d'une néovascularisation tendineuse pathologique que l'embolisation transitoire (émulsion lipiodolée à l'HEGP, imipénem-cilastatine au Japon) cherche à supprimer en préservant les vaisseaux normaux. Une vingtaine de patients ont été traités à l'HEGP ; il existe un signal d'efficacité mais sans essai randomisé, et l'indication est posée après échec des traitements conservateurs.", "chiffres": [{"val": "≈ 20", "label": "patients traités à l'HEGP"}, {"val": "> 800", "label": "tendinopathies embolisées par une équipe japonaise sans rupture tendineuse"}, {"val": "2,4–9,8 %", "label": "ruptures tendineuses après infiltrations de corticoïdes (fasciite plantaire, Acevedo 1998)"}, {"val": "30 min", "label": "durée de la procédure, en ambulatoire sous anesthésie locale"}, {"val": "EVA 9 → 1", "label": "cas clinique, QuickDASH 62 → 27 à 5 mois"}], "points_cles": ["Pathologie de surutilisation (sportifs du dimanche, travailleurs manuels) ; microfissures tendineuses avec néo-angiogenèse qui serait destructrice et non réparatrice (Pufe, Scand J Med Sci Sports 2005) dans un tendon normalement hypovasculaire qui sécrète des facteurs anti-angiogéniques.", "Diagnostics différentiels à éliminer : plica (claquement, ressaut, blocage intermittent) ; l'épicondylite est bien plus fréquente que l'arthrose du coude.", "L'hypervascularisation tendineuse est visible en écho-Doppler.", "Pas de fragilisation tendineuse rapportée : aucune rupture dans les séries japonaises, alors que les infiltrations de corticoïdes exposent à 2,4–9,8 % de ruptures (fasciite plantaire).", "Embole HEGP : émulsion lipiodolée temporaire et radio-opaque (occlusion de 15 à 30 min chez l'animal) ; les pionniers japonais utilisent l'imipénem-cilastatine, non utilisable hors indication en France.", "Une seule artère cible en général : l'artère récurrente épicondylienne latérale, avec un blush hypervasculaire ; les micro-vaisseaux ne sont pas cathétérisables et l'embole est injecté en amont.", "Cas : homme de 54 ans, épicondylite latérale droite depuis plus de 5 ans, échec de 3 infiltrations et de la kinésithérapie, EVA 9, QuickDASH 62 ; sortie à 4 h, soulagement dès le soir, œdème 48 h ; à 5 mois EVA 1, QuickDASH 27.", "Littérature limitée : série japonaise d'une trentaine de patients (bons résultats en QuickDASH), aucun essai randomisé ; recueil multicentrique français en cours.", "Indications (non codifiées) : symptômes depuis 6 à 12 mois (à préciser), échec des traitements conservateurs (kinésithérapie, infiltrations, etc.), douleur fonctionnellement invalidante, besoin de reprise rapide (sportifs) ; la phase précoce, plus inflammatoire, n'est pas traitée pour l'instant.", "Contre-indications : infection, arthropathie inflammatoire."], "technique": ["Ambulatoire, environ 30 minutes, anesthésie locale, en salle d'angiographie.", "Abord radial échoguidé, introducteur 4 F, cocktail radial ; voie radiale si belle artère radiale et patient de plus de 50 ans, sinon voie fémorale.", "Angiographie haute au bras : une artère brachiale postérieure peut alimenter l'artère épicondylienne.", "Cathéter 4 F mammaire interne puis microcathéter 1,7 F (Pursue) ou 1,9 F (Terumo Progreat Lambda) dans l'artère récurrente épicondylienne latérale.", "Injection de l'émulsion lipiodolée en amont du blush jusqu'à réduction de l'hypervascularisation (gouttelettes radio-opaques visibles).", "Sortie vers 4 h ; prévenir le patient d'un œdème transitoire d'environ 48 h."], "alertes": [{"type": "warning", "texte": "Contre-indications : infection et arthropathie inflammatoire ; éliminer une plica ou une autre cause mécanique avant de poser l'indication."}, {"type": "important", "texte": "Technique au stade initial : environ 20 patients à l'HEGP, aucun essai randomisé ; indication posée seulement après échec des traitements conservateurs."}, {"type": "tip", "texte": "L'imipénem-cilastatine utilisé au Japon n'est pas utilisable comme embole hors indication en France ; l'HEGP utilise une émulsion lipiodolée."}], "cochin": "Option à évoquer en RCP avec les radiologues interventionnels vasculaires pour les épicondylites latérales rebelles et invalidantes après échec de la kinésithérapie et des infiltrations, si possible dans le cadre du recueil multicentrique ; l'écho-Doppler documente l'hypervascularisation.", "tags": ["Coude", "Tendons", "Embolisation"], "images": [{"src": "img/embolisation-tennis-elbow-1.jpg", "legende": "Mécanisme hypothétique : embolisation transitoire de la néovascularisation par l'émulsion lipiodolée puis restauration du flux dans les vaisseaux sains.", "t": 1780}, {"src": "img/embolisation-tennis-elbow-2.jpg", "legende": "« Comment je fais » : ambulatoire, 30 min, anesthésie locale, abord radial échoguidé avec introducteur 4 F, cathéter 4 F mammaire interne et microcathéter 1,7–1,9 F.", "t": 1840}, {"src": "img/embolisation-tennis-elbow-3.jpg", "legende": "Artériographie du coude : blush hypervasculaire de l'artère récurrente épicondylienne latérale avant embolisation.", "t": 1900}, {"src": "img/embolisation-tennis-elbow-4.jpg", "legende": "Cas clinique : sortie à 4 h, soulagement dès le soir, œdème 48 h ; à 5 mois EVA 1 et QuickDASH 27 (contre 9 et 62).", "t": 1940}], "session": "s95"}, {"id": "embolisation-gonarthrose", "horaire": "17h20", "titre": "Embolisation des arthroses de genou : quelles indications, quels résultats ?", "orateur": "M. Sapoval (HEGP, AP-HP, Paris)", "t_start": 2140, "t_end": 3060, "resume": "L'embolisation des artères géniculées vise la néo-angiogenèse synoviale et sous-chondrale de l'arthrose. L'étude de sécurité Lipiojoint-1 (émulsion lipiodolée temporaire, 23 patients) ne montre aucune complication liée à l'embole, une baisse significative de l'EVA et du WOMAC à 3 mois, stable à 1 an, avec un meilleur résultat dans les KL ≤ 3 mais aussi des répondeurs KL4. Signal d'efficacité réel mais effet placebo important : l'essai randomisé contre procédure simulée Lipiojoint-2 est en cours ; le défi principal reste la sélection des patients.", "chiffres": [{"val": "23", "label": "patients dans Lipiojoint-1 (étude ouverte de sécurité)"}, {"val": "73–76 %", "label": "répondeurs à 1 semaine, 1 mois et 3 mois (16/22, 16/21, 16/22)"}, {"val": "80–90 % vs 58–67 %", "label": "répondeurs KL3 vs KL4"}, {"val": "37,2 ± 26,7", "label": "EVA moyenne à 3 mois (sur 100)"}, {"val": "1", "label": "insuffisance rénale aiguë transitoire liée au produit de contraste ; 0 complication cutanée, au point de ponction ou d'embolisation non ciblée"}, {"val": "40 / 130", "label": "patients inclus sur 130 prévus dans Lipiojoint-2 (1/3 sham, 2/3 embolisation)"}, {"val": "9", "label": "PTG posées après échec d'embolisation, sans complication chirurgicale rapportée"}], "points_cles": ["Physiopathologie : l'arthrose est aussi inflammatoire ; l'angiogenèse synoviale et ostéochondrale entretient la douleur (croissance de fibres sensitives non myélinisées) ; cible = néo-vaisseaux, en épargnant les vaisseaux normaux.", "Embole utilisé : émulsion lipiodolée (Lipiojoint), embole temporaire et radio-opaque ; chez l'animal (épaule de porc), les artères occluses se reperméabilisent en 15 à 30 minutes ; dans un modèle inflammatoire d'oreille de lapin, les néo-vaisseaux disparaissent durablement alors que les vaisseaux sains réapparaissent.", "Lipiojoint-1 : baisse significative de l'EVA et du WOMAC à 3 mois (écarts-types importants), résultats stables jusqu'à 1 an sans effet rebond net : ne marche pas chez tous, mais de façon durable chez les répondeurs.", "Les patients KL4 répondent aussi : piste pour des patients non opérables ou refusant la chirurgie, avec l'objectif de retarder la prothèse.", "Lipiojoint-2 : essai randomisé contre procédure simulée (EVA > 40), sham sous anesthésie locale avec lunettes de réalité virtuelle et sans ponction artérielle (refus du comité d'éthique) ; effet placebo important observé.", "Douleur après PTG (environ 20 % de patients douloureux) : indication potentielle intéressante, illustrée par un cas avec régression de l'hypervascularisation péri-prothétique ; peu de cas à l'HEGP faute de recrutement chirurgical.", "Autres essais : MOTION (microsphères Embosphere vs infiltration de corticoïdes, n = 100, randomisé 1:1, 6 mois) ; la FDA demande une comparaison au traitement médical, qui n'est pas standardisé.", "Indications hors essai : échec du traitement médical, absence d'indication chirurgicale, douleur (raideur) fonctionnellement invalidante, après avis spécialisé.", "Contre-indications : vraie indication chirurgicale, grandes déformations ; obésité et KL4 discutés, le KL4 n'étant pas pour l'orateur une vraie contre-indication.", "Discussion : sélection actuelle sur une arthrose radiologique ; espoir de critères pronostiques en IRM injectée (synovite) ; la sélectivité pour les néo-vaisseaux tiendrait à un effet différent de l'embole sur des capillaires anormaux, sans preuve formelle ; la capsulite rétractile en phase inflammatoire serait le territoire où l'embolisation marche le mieux."], "technique": ["Artériographie en salle d'angiographie sous anesthésie locale, en ambulatoire.", "Cathétérisme des artères géniculées (exemple : tronc commun géniculé supéro-médial et supéro-latéral) et repérage du blush hypervasculaire.", "Injection en amont des micro-vaisseaux de l'émulsion lipiodolée radio-opaque (ou de microsphères selon les équipes), sans chercher à cathétériser les néo-vaisseaux un par un.", "Surveillance du point de ponction (au moins 1 à 2 % de complications en abord fémoral) et de la fonction rénale (produit de contraste)."], "alertes": [{"type": "warning", "texte": "Technique plus invasive que la RF : risque au point de ponction artériel (1 à 2 % par voie fémorale) et néphrotoxicité du produit de contraste (1 insuffisance rénale transitoire dans Lipiojoint-1)."}, {"type": "important", "texte": "Effet placebo très important dans la gonarthrose : seuls des essais randomisés positifs contre procédure simulée ou traitement médical optimisé permettront de défendre la technique."}, {"type": "tip", "texte": "Question fréquente des chirurgiens : une PTG après échec d'embolisation n'a pas posé de problème chez 9 patients publiés, sans donnée de plus grande ampleur."}], "cochin": "À réserver aux gonarthroses invalidantes en échec médical sans indication chirurgicale, ou aux douleurs post-PTG avec épanchement récidivant, après discussion multidisciplinaire et de préférence dans un essai ; une IRM injectée recherchant une synovite peut aider à la sélection.", "tags": ["Genou", "Embolisation", "Études"], "images": [{"src": "img/embolisation-gonarthrose-1.jpg", "legende": "Lipiojoint-1 : artériographies géniculées montrant l'émulsion lipiodolée radio-opaque ; aucune complication cutanée, au point de ponction ou d'embolisation non ciblée, une insuffisance rénale transitoire.", "t": 2340}, {"src": "img/embolisation-gonarthrose-2.jpg", "legende": "Répondeurs à 1 semaine, 1 mois et 3 mois selon le grade Kellgren-Lawrence (KL3 vs KL4) et patients en état symptomatique acceptable.", "t": 2400}, {"src": "img/embolisation-gonarthrose-3.jpg", "legende": "Embolisation pour douleur après prothèse totale de genou : hypervascularisation péri-prothétique avant et après embolisation.", "t": 2540}, {"src": "img/embolisation-gonarthrose-4.jpg", "legende": "Conclusion : signal d'efficacité, technique faisable, indication après avis spécialisé et échec des méthodes classiques ; problème principal : trouver les bons patients.", "t": 2620}], "session": "s95"}]};
